type HelpLabelProps = {
  children: React.ReactNode;
  htmlFor?: string;
  tip: string;
};

function InlineHelp({ tip }: { tip: string }) {
  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <button
          type="button"
          className="inline-flex size-4 shrink-0 items-center justify-center rounded-full text-muted-foreground transition hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
          aria-label="Подсказка"
        >
          <CircleHelpIcon className="size-3.5" />
        </button>
      </TooltipTrigger>
      <TooltipContent className="max-w-72 text-pretty leading-relaxed">
        <p>{tip}</p>
      </TooltipContent>
    </Tooltip>
  );
}

function HelpLabel({ children, htmlFor, tip }: HelpLabelProps) {
  return (
    <div className="flex items-center gap-1.5">
      <FieldLabel htmlFor={htmlFor}>{children}</FieldLabel>
      <InlineHelp tip={tip} />
    </div>
  );
}

const authorGenderOptions: { value: AuthorGender; label: string }[] = [
  { value: "neutral", label: "Нейтральный" },
  { value: "masculine", label: "Мужской" },
  { value: "feminine", label: "Женский" },
];

function normalizeAuthorGender(value: unknown): AuthorGender {
  if (value === "masculine" || value === "feminine" || value === "neutral") {
    return value;
  }
  return "neutral";
}

function authorGenderFromForm(form: FormData): AuthorGender {
  return normalizeAuthorGender(form.get("author_gender"));
}

function AuthorGenderField({
  id,
  defaultValue = "neutral",
}: {
  id: string;
  defaultValue?: unknown;
}) {
  return (
    <Field>
      <HelpLabel
        htmlFor={id}
        tip="Выберите, какие формы первого лица AI должен использовать: нейтральные, мужские или женские."
      >
        Авторский голос
      </HelpLabel>
      <NativeSelect
        id={id}
        name="author_gender"
        defaultValue={normalizeAuthorGender(defaultValue)}
      >
        {authorGenderOptions.map((option) => (
          <NativeSelectOption key={option.value} value={option.value}>
            {option.label}
          </NativeSelectOption>
        ))}
      </NativeSelect>
    </Field>
  );
}

