  async function handleImportSessionFileAccount(
    payload: AccountSessionFileImportPayload,
  ) {
    setActionBusy("account-import");
    setActionMessage(null);
    const body = new FormData();
    body.set("telethon_session", payload.telethon_session);
    if (payload.phone) body.set("phone", payload.phone);
    if (payload.username) body.set("username", payload.username);
    if (payload.display_name) body.set("display_name", payload.display_name);
    if (payload.proxy_id) body.set("proxy_id", payload.proxy_id);
    if (payload.new_proxy_raw) body.set("new_proxy_raw", payload.new_proxy_raw);
    if (payload.new_proxy_max_accounts) {
      body.set("new_proxy_max_accounts", String(payload.new_proxy_max_accounts));
    }
    body.set("proxy_required", String(payload.proxy_required));
    if (payload.warmup_status) body.set("warmup_status", payload.warmup_status);
    if (payload.warmup_score !== null && payload.warmup_score !== undefined) {
      body.set("warmup_score", String(payload.warmup_score));
    }
    try {
      await authedRequest<TelegramAccount>(
        "/telegram-accounts/import-session-file",
        {
          method: "POST",
          body,
        },
      );
      trackGoal("account_connected", { method: "session_file" });
      setActionMessage("Telethon session файл импортирован");
      await refreshData();
    } finally {
      setActionBusy(null);
    }
  }

