  async function handleReorderAccounts(accountIds: string[]) {
    setActionBusy("accounts-reorder");
    setActionMessage(null);
    setDataError(null);
    setData((current) => {
      const accountsById = new Map(current.accounts.map((account) => [account.id, account]));
      const orderedAccounts = accountIds
        .map((accountId) => accountsById.get(accountId))
        .filter((account): account is TelegramAccount => Boolean(account));
      return orderedAccounts.length === current.accounts.length
        ? { ...current, accounts: orderedAccounts }
        : current;
    });
    try {
      const accounts = await authedRequest<TelegramAccount[]>("/telegram-accounts/order", {
        method: "PUT",
        body: { account_ids: accountIds },
      });
      setData((current) => ({ ...current, accounts }));
      setActionMessage("Порядок аккаунтов сохранен");
    } catch (error) {
      setActionKind("error");
      setActionMessage(errorMessage(error));
      await refreshData();
    } finally {
      setActionBusy(null);
    }
  }

