  async function handleAccountAction(
    accountId: string,
    action: "archive" | "quarantine" | "restore" | "delete",
  ) {
    if (
      action === "delete" &&
      !window.confirm("Удалить аккаунт из рабочего контура?")
    ) {
      return;
    }
    if (
      action === "archive" &&
      !window.confirm(
        "Отправить аккаунт в архив? Все кампании, где используется этот аккаунт, будут остановлены и тоже отправлены в архив. Источники этих кампаний освободятся для новых запусков.",
      )
    ) {
      return;
    }
    if (
      action === "quarantine" &&
      !window.confirm(
        "Отправить аккаунт в карантин? Он останется в менеджере, но активные сценарии и массовые действия должны его пропускать.",
      )
    ) {
      return;
    }

    setActionBusy(`account-${action}-${accountId}`);
    setActionMessage(null);
    setDataError(null);
    try {
      if (action === "archive") {
        const account = await authedRequest<TelegramAccount>(
          `/telegram-accounts/${accountId}/archive`,
          { method: "POST" },
        );
        upsertAccountLocally(account);
        setActionMessage(
          "Аккаунт отправлен в архив, связанные кампании остановлены и архивированы",
        );
      } else if (action === "quarantine") {
        const account = await authedRequest<TelegramAccount>(
          `/telegram-accounts/${accountId}/quarantine`,
          { method: "POST" },
        );
        upsertAccountLocally(account);
        setActionMessage("Аккаунт отправлен в карантин");
      } else if (action === "restore") {
        const account = await authedRequest<TelegramAccount>(
          `/telegram-accounts/${accountId}`,
          {
            method: "PATCH",
            body: { status: "active" },
          },
        );
        upsertAccountLocally(account);
        setActionMessage("Аккаунт восстановлен из архива");
      } else {
        await authedRequest<void>(`/telegram-accounts/${accountId}`, {
          method: "DELETE",
        });
        moveAccountsLocally([accountId], "deleted");
        setActionMessage("Аккаунт удален");
      }
    } finally {
      setActionBusy(null);
    }
  }

  async function handleBulkAccountLifecycleAction(
    accountIds: string[],
    action: "archive" | "delete",
  ) {
    const uniqueIds = Array.from(new Set(accountIds.filter(Boolean)));
    if (!uniqueIds.length) return;
    if (
      action === "archive" &&
      !window.confirm(`Отправить выбранные аккаунты в архив: ${uniqueIds.length}?`)
    ) {
      return;
    }
    if (
      action === "delete" &&
      !window.confirm(`Удалить выбранные аккаунты: ${uniqueIds.length}?`)
    ) {
      return;
    }

    setActionBusy(`account-bulk-${action}`);
    setActionMessage(null);
    setDataError(null);
    try {
      const result = await authedRequest<AccountBulkActionResponse>(
        `/telegram-accounts/bulk/${action}`,
        {
          method: "POST",
          body: { account_ids: uniqueIds },
        },
      );
      moveAccountsLocally(uniqueIds, action === "archive" ? "archived" : "deleted");
      setActionMessage(`${result.message}: ${result.account_count}`);
    } catch (error) {
      setDataError(errorMessage(error));
      throw error;
    } finally {
      setActionBusy(null);
    }
  }

