  async function checkSourcesAfterImport(
    sources: Source[],
    onProgress?: (progress: SourceImportProgress) => void,
  ): Promise<SourceImportResult> {
    const checkedSources: Source[] = [];
    let checked = 0;
    let failed = 0;
    let nextIndex = 0;

    async function checkNextSource() {
      while (nextIndex < sources.length) {
        const source = sources[nextIndex];
        nextIndex += 1;
        try {
          if (sourceNeedsCommentCheck(source)) {
            const nextSource = await authedRequest<Source>(
              `/sources/${source.id}/check-comments`,
              { method: "POST" },
            );
            checkedSources.push(nextSource);
          } else {
            checkedSources.push(source);
          }
          checked += 1;
        } catch {
          checkedSources.push(source);
          failed += 1;
        }
        onProgress?.({
          stage: "checking",
          processed: checked + failed,
          total: sources.length,
          checked,
          failed,
          currentTitle: source.title || sourceRef(source),
          sources: checkedSources,
        });
      }
    }

    await Promise.all(
      Array.from({
        length: Math.min(SOURCE_COMMENT_CHECK_CONCURRENCY, sources.length),
      }).map(() => checkNextSource()),
    );

    return { sources: checkedSources, checked, failed };
  }

  async function handleCreateSource(payload: SourceCreatePayload) {
    setActionBusy("source-create");
    setActionMessage(null);
    try {
      const source = await authedRequest<Source>("/sources", {
        method: "POST",
        body: payload,
      });
      trackGoal("source_created", { count: 1, method: "single" });
      setActionMessage("Источник добавлен. Проверка комментариев идет в фоне.");
      await refreshData();
      void (async () => {
        const result = await checkSourcesAfterImport([source]);
        setActionMessage(
          result.failed
            ? "Проверка источника завершилась с ошибкой"
            : "Источник проверен",
        );
        await refreshData();
      })();
    } finally {
      setActionBusy(null);
    }
  }

  async function handleCreateSourceList(refsRaw: string, title: string | null) {
    const refs = splitSourceRefs(refsRaw);
    if (!refs.length) return;

    if (refs.length === 1 && title) {
      await handleCreateSource(sourcePayloadFromRef(refs[0], title));
      return;
    }

    setActionBusy("source-create");
    setActionMessage(null);
    try {
      const response = await authedRequest<SourceBulkCreateResponse>(
        "/sources/bulk",
        {
          method: "POST",
          body: {
            refs,
            type: "unknown",
          },
        },
      );
      const importedSources = response.items.map((item) => item.source);
      trackGoal("source_created", {
        count: response.created,
        method: "bulk",
      });
      setActionMessage(
        `Источников добавлено: ${response.created}, уже были: ${response.reused}. Проверка комментариев идет в фоне.`,
      );
      await refreshData();
      void (async () => {
        const result = await checkSourcesAfterImport(importedSources);
        setActionMessage(
          result.failed
            ? `Фоновая проверка источников завершена. Проверено: ${result.checked}, с ошибкой: ${result.failed}.`
            : `Фоновая проверка источников завершена. Проверено: ${result.checked}.`,
        );
        await refreshData();
      })();
    } finally {
      setActionBusy(null);
    }
  }

  async function handleImportChannelMapSources(
    refs: string[],
    options: ChannelMapImportOptions = {},
  ) {
    const uniqueRefs = Array.from(
      new Set(refs.map((ref) => ref.trim()).filter(Boolean)),
    );
    if (!uniqueRefs.length) return [];

    setActionBusy("channel-map-import");
    setActionMessage(null);
    setDataError(null);
    options.onProgress?.({
      stage: "creating",
      processed: 0,
      total: uniqueRefs.length,
    });
    try {
      const response = await authedRequest<SourceBulkCreateResponse>(
        "/sources/bulk",
        {
          method: "POST",
          body: {
            refs: uniqueRefs,
            type: "channel",
          },
        },
      );
      let importedSources = response.items.map((item) => item.source);
      setActionMessage(
        options.verifyComments
          ? `Импортировано из базы: ${importedSources.length}. Проверка комментариев идет в фоне.`
          : `Импортировано из базы: ${importedSources.length}.`,
      );
      await refreshData();
      if (options.verifyComments) {
        void (async () => {
          const result = await checkSourcesAfterImport(
            importedSources,
            options.onProgress,
          );
          importedSources = result.sources;
          const checkedCount = importedSources.filter(
            (source) => source.comments_enabled,
          ).length;
          setActionMessage(
            result.failed
              ? `Фоновая проверка базы завершена: открыты ${checkedCount}, ошибок проверки ${result.failed}.`
              : `Фоновая проверка базы завершена: открыты ${checkedCount}.`,
          );
          await refreshData();
          options.onProgress?.({
            stage: "completed",
            processed: importedSources.length,
            total: importedSources.length,
            checked: result.checked,
            failed: result.failed,
            sources: importedSources,
          });
        })();
      }
      return importedSources;
    } finally {
      setActionBusy(null);
    }
  }

