  async function handleStartCampaignRun(campaignId: string) {
    const campaign = data.campaigns.find((item) => item.id === campaignId);
    if (!campaign) return;
    if (campaignRunPendingIds.includes(campaignId)) return;
    if (!isCampaignRunnable(campaign)) {
      setActionMessage("Кампания уже запущена или ожидает обработки");
      return;
    }
    setActionBusy(`campaign-run-${campaignId}`);
    setCampaignRunPendingIds((current) =>
      current.includes(campaignId) ? current : [...current, campaignId],
    );
    setActionMessage(null);
    setDataError(null);
    try {
      const safety = await authedRequest<CampaignSafety>(
        `/campaigns/${campaignId}/safety`,
      );
      if (!safety.can_start) {
        const blockedAccounts = safety.accounts
          .filter((account) => account.status === "blocked")
          .map(
            (account) =>
              `${account.account_label}: ${account.message || account.reason || "заблокирован"}`,
          );
        const blockedSources = (safety.sources || [])
          .filter((source) => source.status === "blocked")
          .map(
            (source) =>
              `${source.source_label}: ${source.message || source.reason || "заблокирован"}`,
          );
        const blocked = [...blockedAccounts, ...blockedSources]
          .slice(0, 3)
          .join("; ");
        setDataError(
          `Safety preflight не пройден: ${blocked || "нет доступных причин блокировки"}`,
        );
        return;
      }
      const run = await authedRequest<CampaignRun>(
        `/campaigns/${campaignId}/runs`,
        { method: "POST" },
      );
      setData((current) => ({
        ...current,
        campaigns: current.campaigns.map((item) =>
          item.id === campaignId
            ? {
                ...item,
                status: isActiveCampaignRunStatus(run.status)
                  ? run.status
                  : item.status,
                active_run_status: isActiveCampaignRunStatus(run.status)
                  ? run.status
                  : item.active_run_status,
              }
            : item,
        ),
      }));
      setActionMessage("Запуск кампании создан");
      await refreshData();
    } catch (error) {
      setDataError(errorMessage(error));
    } finally {
      setCampaignRunPendingIds((current) =>
        current.filter((id) => id !== campaignId),
      );
      setActionBusy(null);
    }
  }

