  async function handleLoadCampaignDetails(
    campaignId: string,
  ): Promise<CampaignDetails> {
    const runs = await authedRequest<CampaignRun[]>(
      `/campaigns/${campaignId}/runs`,
    );
    const latestRun = runs[0];
    const events = latestRun
      ? await authedRequest<CampaignEvent[]>(
          `/campaigns/runs/${latestRun.id}/events`,
        )
      : [];
    const runtimeLogs = latestRun
      ? await authedRequest<CampaignRuntimeLog[]>(
          `/campaigns/runs/${latestRun.id}/logs?limit=200`,
        )
      : [];
    const actions = await authedRequest<CampaignActionDetail[]>(
      `/campaigns/${campaignId}/actions`,
    );
    let report: CampaignCommentReport | null;
    try {
      report = await authedRequest<CampaignCommentReport>(
        `/campaigns/${campaignId}/comment-report`,
      );
    } catch {
      report = null;
    }
    let inviteTracking: CampaignInviteTrackingMetric | null;
    try {
      inviteTracking = await authedRequest<CampaignInviteTrackingMetric | null>(
        `/campaigns/${campaignId}/invite-tracking`,
      );
    } catch {
      inviteTracking = null;
    }
    return { runs, events, runtimeLogs, actions, report, inviteTracking };
  }

  async function handleDownloadCampaignXlsx(
    campaignId: string,
    campaignName: string,
    campaignType?: string,
  ) {
    if (!session) return;
    const reportKind =
      campaignType === "mass_reactions" ? "reaction-report" : "comment-report";
    const suffix = campaignType === "mass_reactions" ? "reactions" : "comments";
    const response = await fetch(
      `${getApiBase()}/campaigns/${campaignId}/${reportKind}.xlsx`,
      {
        headers: {
          Authorization: `Bearer ${session.token}`,
          "X-Workspace-Id": session.workspace.id,
        },
      },
    );
    if (!response.ok) {
      throw new Error(await response.text());
    }
    const blob = await response.blob();
    const url = window.URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = `${campaignName.replace(/[^\wа-яА-Я-]+/g, "-") || "campaign"}-${suffix}.xlsx`;
    document.body.appendChild(link);
    link.click();
    link.remove();
    window.URL.revokeObjectURL(url);
  }

