  async function handleCampaignAction(
    campaignId: string,
    action: "stop" | "archive" | "restore" | "delete",
  ) {
    const pendingKey = `campaign-${action}-${campaignId}`;
    if (campaignActionPendingIds.includes(pendingKey)) {
      return;
    }
    const previousCampaign = data.campaigns.find(
      (item) => item.id === campaignId,
    );
    if (!previousCampaign) {
      return;
    }
    if (
      action === "stop" &&
      !window.confirm("Остановить активный запуск кампании?")
    ) {
      return;
    }
    if (
      action === "archive" &&
      !window.confirm(
        "Отправить кампанию в архив? Она исчезнет из рабочего списка, а ее источники освободятся для новых кампаний.",
      )
    ) {
      return;
    }
    const shouldHideOptimistically = action === "archive" || action === "delete";
    if (shouldHideOptimistically) {
      optimisticHiddenCampaignIdsRef.current.add(campaignId);
      setData((current) => ({
        ...current,
        campaigns: current.campaigns.filter(
          (campaign) => campaign.id !== campaignId,
        ),
      }));
    }
    setCampaignActionPendingIds((current) =>
      current.includes(pendingKey) ? current : [...current, pendingKey],
    );
    setActionBusy(pendingKey);
    setActionMessage(null);
    try {
      let updatedCampaign: Campaign | null = null;
      if (action === "delete") {
        await authedRequest<void>(`/campaigns/${campaignId}`, {
          method: "DELETE",
        });
      } else {
        updatedCampaign = await authedRequest<Campaign>(
          `/campaigns/${campaignId}/${action}`,
          {
            method: "POST",
          },
        );
      }
      optimisticHiddenCampaignIdsRef.current.delete(campaignId);
      if (updatedCampaign) {
        setData((current) => {
          const exists = current.campaigns.some(
            (campaign) => campaign.id === campaignId,
          );
          return {
            ...current,
            campaigns: exists
              ? current.campaigns.map((campaign) =>
                  campaign.id === campaignId ? updatedCampaign : campaign,
                )
              : [updatedCampaign, ...current.campaigns],
          };
        });
      }
      setActionMessage(
        action === "archive"
          ? "Кампания отправлена в архив"
          : action === "restore"
            ? "Кампания восстановлена"
            : action === "delete"
              ? "Кампания удалена"
              : "Статус кампании обновлен",
      );
      void refreshData({ silent: true }).catch((error) => {
        setDataError(errorMessage(error));
      });
    } catch (error) {
      optimisticHiddenCampaignIdsRef.current.delete(campaignId);
      if (shouldHideOptimistically) {
        setData((current) => ({
          ...current,
          campaigns: current.campaigns.some(
            (campaign) => campaign.id === campaignId,
          )
            ? current.campaigns
            : [previousCampaign, ...current.campaigns],
        }));
      }
      setDataError(errorMessage(error));
    } finally {
      setCampaignActionPendingIds((current) =>
        current.filter((item) => item !== pendingKey),
      );
      setActionBusy((current) => (current === pendingKey ? null : current));
    }
  }

