function StatusBadge({ status }: { status: string }) {
  const variant =
    status === "active" ? "default" : status === "paused" ? "secondary" : "outline";
  return <Badge variant={variant}>{contentFactoryStatusLabel(status)}</Badge>;
}

const contentFactoryWeekDays = [
  { value: "mon", short: "Пн", label: "понедельник", defaultChecked: true },
  { value: "tue", short: "Вт", label: "вторник", defaultChecked: true },
  { value: "wed", short: "Ср", label: "среда", defaultChecked: true },
  { value: "thu", short: "Чт", label: "четверг", defaultChecked: true },
  { value: "fri", short: "Пт", label: "пятница", defaultChecked: true },
  { value: "sat", short: "Сб", label: "суббота", defaultChecked: false },
  { value: "sun", short: "Вс", label: "воскресенье", defaultChecked: false },
];

function contentFactoryStatusLabel(status: string) {
  const labels: Record<string, string> = {
    draft: "черновик настройки",
    active: "активен",
    paused: "пауза",
    archived: "архив",
  };
  return labels[status] || status;
}

function contentFactoryProcessState(actionBusy: string | null, factoryId?: string | null) {
  if (!actionBusy) return null;
  if (factoryId && actionBusy === `content-factory-run-${factoryId}`) {
    return {
      title: "Генерируем новый пост",
      description: "Завод собирает контекст, пишет текст, проверяет качество и готовит изображение.",
    };
  }
  if (actionBusy.startsWith("content-post-regenerate-image-")) {
    return {
      title: "Генерируем изображение",
      description: "Создаём новую обложку. Если у провайдера лимит, процесс может ждать до 5 минут.",
    };
  }
  if (actionBusy.startsWith("content-post-regenerate-text-")) {
    return {
      title: "Перегенерируем текст",
      description: "Пишем новый вариант поста и проверяем, чтобы он не повторял предыдущий формат.",
    };
  }
  if (actionBusy.startsWith("content-post-publish-")) {
    return {
      title: "Публикуем пост",
      description: "Проверяем готовность поста и отправляем его в Telegram.",
    };
  }
  if (actionBusy.startsWith("content-post-approve-")) {
    return {
      title: "Одобряем пост",
      description: "Фиксируем статус поста перед публикацией.",
    };
  }
  if (factoryId && actionBusy === `content-factory-update-${factoryId}`) {
    return {
      title: "Сохраняем настройки",
      description: "Обновляем параметры контент-завода.",
    };
  }
  return null;
}

function contentFactoryScheduleDays(factory: ContentFactory) {
  const raw = factory.schedule_config.publish_days;
  if (Array.isArray(raw) && raw.length > 0) {
    return raw.map(String);
  }
  return contentFactoryWeekDays
    .filter((day) => day.defaultChecked)
    .map((day) => day.value);
}

function contentFactoryDaysLabel(factory: ContentFactory) {
  const days = contentFactoryScheduleDays(factory);
  return contentFactoryWeekDays
    .filter((day) => days.includes(day.value))
    .map((day) => day.short)
    .join(", ");
}

function contentFactoryPublishWindow(factory: ContentFactory) {
  const from = String(factory.schedule_config.publish_time_from || "10:00");
  const to = String(factory.schedule_config.publish_time_to || "18:00");
  return `${from}–${to}`;
}

function contentFactoryScheduleSummary(factory: ContentFactory) {
  const postsPerDay = Number(factory.schedule_config.posts_per_day || 1);
  return `${postsPerDay}/день · ${contentFactoryPublishWindow(factory)} · ${contentFactoryDaysLabel(factory)}`;
}

function contentFactoryPlannedRuns(factory: ContentFactory) {
  const days = contentFactoryScheduleDays(factory);
  const postsPerDay = Math.max(1, Math.min(10, Number(factory.schedule_config.posts_per_day || 1)));
  const from = String(factory.schedule_config.publish_time_from || "10:00");
  const to = String(factory.schedule_config.publish_time_to || "18:00");
  const timezone = String(factory.schedule_config.timezone || "Europe/Moscow");
  const now = new Date();
  const planned: { key: string; label: string; hint: string; isNext: boolean; date: Date }[] = [];
  const dayValues = contentFactoryWeekDays.map((day) => day.value);

  if (factory.next_run_at) {
    const nextRun = new Date(factory.next_run_at);
    if (!Number.isNaN(nextRun.getTime()) && nextRun <= now && factory.status === "active") {
      planned.push({
        key: "worker-due-now",
        label: "Сейчас, ожидает worker",
        hint: "следующая проверка worker должна создать пост",
        isNext: true,
        date: now,
      });
    }
  }

  for (let offset = 0; offset < 21 && planned.length < 10; offset += 1) {
    const zonedDay = addDaysToZonedDate(now, offset, timezone);
    const dayValue = dayValues[zonedDay.weekdayIndex];
    if (!days.includes(dayValue)) continue;
    for (const time of distributeContentFactoryTimes(from, to, postsPerDay)) {
      const [hours, minutes] = time.split(":").map(Number);
      const candidate = zonedTimeToDate(zonedDay.year, zonedDay.month, zonedDay.day, hours, minutes, timezone);
      if (candidate <= now) continue;
      planned.push({
        key: `${candidate.toISOString()}-${time}`,
        label: `${formatDateInTimeZone(candidate, timezone)} · ${time}`,
        hint: planned.length === 0 ? "ближайший будущий плановый запуск" : timezone,
        isNext: planned.length === 0,
        date: candidate,
      });
      if (planned.length >= 10) break;
    }
  }
  if (planned.length === 0) {
    return [{ key: "empty", label: "Будущих запусков нет", hint: "проверьте дни и окно публикаций", isNext: false, date: now }];
  }
  return planned.sort((left, right) => left.date.getTime() - right.date.getTime()).map((slot, index) => ({ ...slot, isNext: index === 0 }));
}

function contentFactoryTodayPlan(factory: ContentFactory) {
  const days = contentFactoryScheduleDays(factory);
  const postsPerDay = Math.max(1, Math.min(10, Number(factory.schedule_config.posts_per_day || 1)));
  const from = String(factory.schedule_config.publish_time_from || "10:00");
  const to = String(factory.schedule_config.publish_time_to || "18:00");
  const timezone = String(factory.schedule_config.timezone || "Europe/Moscow");
  const now = new Date();
  const today = zonedDateParts(now, timezone);
  const dayValue = contentFactoryWeekDays[today.weekdayIndex]?.value;
  const nextRun = factory.next_run_at ? new Date(factory.next_run_at) : null;

  if (!dayValue || !days.includes(dayValue)) {
    return [
      {
        key: "no-publishing-today",
        time: "Сегодня",
        label: "выходной",
        hint: "Этот день не выбран в настройках публикаций.",
        state: "past" as const,
      },
    ];
  }

  return distributeContentFactoryTimes(from, to, postsPerDay).map((time) => {
    const [hours, minutes] = time.split(":").map(Number);
    const candidate = zonedTimeToDate(today.year, today.month, today.day, hours, minutes, timezone);
    const isNext =
      nextRun instanceof Date &&
      !Number.isNaN(nextRun.getTime()) &&
      Math.abs(nextRun.getTime() - candidate.getTime()) < 60_000;
    const isPast = candidate <= now;
    const state = isNext ? "next" : isPast ? "past" : "future";
    return {
      key: `${candidate.toISOString()}-${time}`,
      time,
      label: isNext ? "следующий запуск" : isPast ? "слот прошёл" : "запланирован",
      hint: isNext
        ? "Worker создаст пост в этот слот."
        : isPast
          ? "Если завод был активен, этот слот уже должен был быть обработан."
          : timezone,
      state,
    };
  });
}

function contentFactoryPostsTodayCount(factory: ContentFactory, posts: ContentPost[]) {
  const timezone = String(factory.schedule_config.timezone || "Europe/Moscow");
  const today = zonedDateParts(new Date(), timezone);
  return posts.filter((post) => {
    if (["rejected", "failed"].includes(post.status)) return false;
    const date = new Date(post.published_at || post.created_at);
    if (Number.isNaN(date.getTime())) return false;
    const parts = zonedDateParts(date, timezone);
    return parts.year === today.year && parts.month === today.month && parts.day === today.day;
  }).length;
}

function contentFactoryNextRunLabel(factory: ContentFactory) {
  if (factory.status !== "active") {
    return "Завод не активен, автоматические запуски не планируются.";
  }
  if (!factory.next_run_at) {
    return "Пока не рассчитан. Worker рассчитает ближайший запуск при следующем тике.";
  }
  const timezone = String(factory.schedule_config.timezone || "Europe/Moscow");
  const nextRun = new Date(factory.next_run_at);
  if (Number.isNaN(nextRun.getTime())) {
    return "Некорректное время следующего запуска.";
  }
  if (nextRun <= new Date()) {
    return "Сейчас, ожидает ближайший тик worker.";
  }
  return `${formatDateInTimeZone(nextRun, timezone)} · ${formatTimeInTimeZone(nextRun, timezone)} · ${timezone}`;
}

function distributeContentFactoryTimes(from: string, to: string, count: number) {
  const fromMinutes = timeToMinutes(from, 10 * 60);
  const toMinutes = timeToMinutes(to, 18 * 60);
  if (count <= 1 || toMinutes <= fromMinutes) {
    return [minutesToTime(fromMinutes)];
  }
  const step = (toMinutes - fromMinutes) / (count - 1);
  return Array.from({ length: count }, (_item, index) =>
    minutesToTime(Math.round(fromMinutes + step * index)),
  );
}

function timeToMinutes(value: string, fallback: number) {
  const match = /^(\d{1,2}):(\d{2})$/.exec(value);
  if (!match) return fallback;
  const hours = Math.max(0, Math.min(23, Number(match[1])));
  const minutes = Math.max(0, Math.min(59, Number(match[2])));
  return hours * 60 + minutes;
}

function minutesToTime(value: number) {
  const hours = Math.floor(value / 60);
  const minutes = value % 60;
  return `${String(hours).padStart(2, "0")}:${String(minutes).padStart(2, "0")}`;
}

function addDaysToZonedDate(date: Date, offsetDays: number, timezone: string) {
  const parts = zonedDateParts(date, timezone);
  const noon = zonedTimeToDate(parts.year, parts.month, parts.day + offsetDays, 12, 0, timezone);
  return zonedDateParts(noon, timezone);
}

function zonedDateParts(date: Date, timezone: string) {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone: timezone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    weekday: "short",
  }).formatToParts(date);
  const map = Object.fromEntries(parts.map((part) => [part.type, part.value]));
  const weekdayIndex = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"].indexOf(map.weekday || "Mon");
  return {
    year: Number(map.year),
    month: Number(map.month),
    day: Number(map.day),
    weekdayIndex: Math.max(0, weekdayIndex),
  };
}

function zonedTimeToDate(year: number, month: number, day: number, hours: number, minutes: number, timezone: string) {
  let utcDate = new Date(Date.UTC(year, month - 1, day, hours, minutes, 0));
  let offset = timezoneOffsetMs(utcDate, timezone);
  utcDate = new Date(utcDate.getTime() - offset);
  offset = timezoneOffsetMs(utcDate, timezone);
  return new Date(Date.UTC(year, month - 1, day, hours, minutes, 0) - offset);
}

function timezoneOffsetMs(date: Date, timezone: string) {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone: timezone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hour12: false,
  }).formatToParts(date);
  const map = Object.fromEntries(parts.map((part) => [part.type, part.value]));
  const asUtc = Date.UTC(Number(map.year), Number(map.month) - 1, Number(map.day), Number(map.hour), Number(map.minute), Number(map.second));
  return asUtc - date.getTime();
}

function formatDateInTimeZone(date: Date, timezone: string) {
  return date.toLocaleDateString("ru-RU", { timeZone: timezone, day: "2-digit", month: "short" });
}

function formatTimeInTimeZone(date: Date, timezone: string) {
  return date.toLocaleTimeString("ru-RU", { timeZone: timezone, hour: "2-digit", minute: "2-digit" });
}

function contentFactoryModeLabel(mode: string) {
  const labels: Record<string, string> = {
    drafts_only: "только черновики",
    approval_required: "ручное согласование",
    auto_publish: "автопубликация",
    auto_publish_safe: "безопасная автопубликация",
    auto_publish_full: "полная автопубликация",
  };
  return labels[mode] || mode;
}

function contentPostStatusLabel(status: string) {
  const labels: Record<string, string> = {
    draft: "черновик",
    needs_review: "на проверке",
    approved: "одобрен",
    scheduled: "запланирован",
    published: "опубликован",
    failed: "ошибка",
    rejected: "отклонён",
  };
  return labels[status] || status;
}

function visibleContentFactoryQualityNotes(notes: string[]) {
  const hiddenMarkers = [
    "формат слишком похож",
    "похож на недавний пост",
    "слишком похож на недавний",
    "нет конкретного пользовательского действия",
    "нет конкретного действия",
    "similar to a recent",
    "recent post",
    "no concrete user action",
    "no specific user action",
  ];
  return notes.filter((note) => {
    const lowered = String(note || "").toLowerCase();
    return lowered && !hiddenMarkers.some((marker) => lowered.includes(marker));
  });
}

function contentFactoryKnowledgeKindLabel(kind: string) {
  const labels: Record<string, string> = {
    text: "текст",
    file: "документ",
    image: "изображение",
    dynamic_site_context: "контекст сайта",
  };
  return labels[kind] || kind;
}

function contentFactoryKnowledgeIsImage(item: ContentFactoryKnowledgeItem) {
  const contentType = String(item.metadata?.content_type || "");
  return item.kind === "image" || contentType.startsWith("image/");
}

function contentFactoryRunStatusLabel(status: string) {
  const labels: Record<string, string> = {
    queued: "в очереди",
    researching: "анализ источников",
    writing: "написание",
    reviewing: "проверка",
    publishing: "публикация",
    ready: "готово",
    failed: "ошибка",
    cancelled: "отменён",
  };
  return labels[status] || status;
}

function contentFactoryRuntimeTitle(factory: ContentFactory) {
  if (factory.status === "paused") return "Завод на паузе";
  if (factory.status === "draft") return "Завод ещё не запущен";
  if (factory.status === "active") return "Завод активен";
  return "Состояние завода";
}

function contentFactoryRuntimeDescription(factory: ContentFactory) {
  if (factory.status === "paused") {
    return "Регулярная работа остановлена. Можно смотреть посты и редактировать настройки, но для продолжения нужно активировать завод.";
  }
  if (factory.status === "draft") {
    return "Настройки сохранены, но регулярная работа ещё не включена. Нажмите «Запустить завод», чтобы включить работу по расписанию, или «Сгенерировать пост» для ручного теста.";
  }
  if (factory.mode === "drafts_only") {
    return "Завод активен, но работает в режиме черновиков: посты создаются в очередь и не публикуются автоматически.";
  }
  if (factory.mode === "approval_required") {
    return "Завод активен и требует ручного согласования: сначала черновик, затем одобрение и публикация.";
  }
  return "Завод активен в режиме автопубликации. Следите за событиями, ошибками и качеством постов.";
}

function contentFactoryErrorMessage(message: string) {
  if (message.includes("TELEGRAM_PUBLISH_FAILED")) {
    const parts = message.split(":");
    const code = parts[1] || "ошибка Telegram";
    const detail = parts.slice(2).join(":").trim();
    if (code === "TELEGRAM_CONNECTION_FAILED") {
      return "Пост не опубликован: не удалось подключиться к Telegram через аккаунт-публикатор. Проверьте аккаунт и прокси или выберите другой аккаунт-публикатор.";
    }
    if (code === "SESSION_UNAUTHORIZED" || code === "SESSION_INVALID") {
      return "Пост не опубликован: сессия аккаунта-публикатора слетела. Переподключите Telegram аккаунт.";
    }
    return `Пост не опубликован: Telegram вернул ${code}${detail ? ` — ${detail}` : ""}`;
  }
  const labels: Record<string, string> = {
    CONTENT_FACTORY_TARGET_REQUIRED: "Пост не опубликован: укажите целевой канал или чат.",
    CONTENT_FACTORY_PUBLISHER_ACCOUNT_REQUIRED: "Пост не опубликован: выберите аккаунт-публикатор.",
    CONTENT_FACTORY_PUBLISHER_ACCOUNT_UNAVAILABLE: "Пост не опубликован: аккаунт-публикатор недоступен.",
    CONTENT_FACTORY_PUBLISHER_ACCOUNT_RESTRICTED: "Пост не опубликован: аккаунт-публикатор ограничен Telegram.",
    CONTENT_FACTORY_PUBLISHER_ACCOUNT_QUARANTINED: "Пост не опубликован: аккаунт-публикатор на паузе или в карантине.",
    CONTENT_FACTORY_PUBLISHER_PROXY_REQUIRED: "Пост не опубликован: аккаунту-публикатору нужен прокси.",
    CONTENT_POST_IMAGE_REQUIRED: "Пост не опубликован: изображение включено, но файл ещё не готов. Пересоздайте изображение и дождитесь завершения.",
    CONTENT_POST_CAPTION_TOO_LONG: "Пост не опубликован: текст с изображением длиннее лимита Telegram. Сократите текст и сохраните пост.",
    CONTENT_POST_NOT_PUBLISHABLE: "Пост нельзя опубликовать из текущего статуса.",
    CONTENT_POST_FINAL_STATUS: "Пост уже в финальном статусе.",
  };
  return labels[message] || message;
}

function contentPostPublishProblem(post: ContentPost): { title: string; description: string } | null {
  const problem = post.metadata?.last_publish_problem;
  if (!problem || typeof problem !== "object" || Array.isArray(problem)) {
    return null;
  }
  const data = problem as Record<string, unknown>;
  const code = typeof data.code === "string" ? data.code : "";
  const message = typeof data.message === "string" ? data.message : "";
  const at = typeof data.at === "string" ? formatDateTimeRu(data.at) : "";
  const description = message || (code ? contentFactoryErrorMessage(code) : "Пост сформирован, но не отправлен.");
  return {
    title: "Публикация не отправлена",
    description: at ? `${description} · ${at}` : description,
  };
}

function mergeContentPostLists(current: ContentPost[], incoming: ContentPost[]) {
  if (current.length === 0) return incoming;
  const currentById = new Map(current.map((post) => [post.id, post]));
  const incomingById = new Map(incoming.map((post) => [post.id, post]));
  const nextById = new Map(
    incoming.map((post) => {
      const existing = currentById.get(post.id);
      if (
        existing &&
        existing.updated_at === post.updated_at &&
        existing.status === post.status &&
        existing.image_attachment_id === post.image_attachment_id
      ) {
        return [post.id, existing] as const;
      }
      return [post.id, post] as const;
    }),
  );
  const newPosts = incoming.filter((post) => !currentById.has(post.id));
  const existingPosts = current
    .filter((post) => incomingById.has(post.id))
    .map((post) => nextById.get(post.id) || post);
  return [...newPosts, ...existingPosts];
}

function DashboardScreen({
  data,
  stats,
  access,
  onOpenLaunch,
  onOpenBilling,
  onOpenSection,
}: {
  data: AppData;
  stats: React.ComponentProps<typeof SectionCards>["stats"];
  access: AccessSummary | null;
  onOpenLaunch: () => void;
  onOpenBilling: () => void;
  onOpenSection: (section: AppSection) => void;
}) {
  const availableSources = data.sources.filter(
    (source) => !sourceIsBlacklisted(source) && source.access_status === "available",
  ).length;
  const activeCampaigns = stats.campaignsActive;
  const hasAccount = data.accounts.length > 0;
  const hasSource = data.sources.length > 0;
  const hasCampaign = data.campaigns.some(
    (campaign) => !["archived", "deleted"].includes(campaign.status),
  );
  const hasResult = data.campaigns.some(
    (campaign) => Number(campaign.sent_count || 0) > 0,
  );
  const activationSteps = [
    {
      title: "Подключить Telegram-аккаунт",
      complete: hasAccount,
      section: "accounts" as AppSection,
    },
    {
      title: "Добавить рабочий источник",
      complete: hasSource,
      section: "sources" as AppSection,
    },
    {
      title: "Создать и запустить кампанию",
      complete: hasCampaign,
      section: "neuro" as AppSection,
    },
    {
      title: "Получить первый результат и отчет",
      complete: hasResult,
      section: "neuro" as AppSection,
    },
  ];
  const activationCompleted = activationSteps.filter((step) => step.complete).length;
  const enabled = enabledFeatureSet(access);
  const paidProductCodes = new Set(
    (access?.modules || []).map((product) => product.code),
  );
  const hasPaidModules = [...enabled].some((feature) =>
    paidProductCodes.has(feature),
  );

  return (
    <>
      {!hasPaidModules && (
        <Card className="border-amber-200 bg-amber-50 text-amber-950 dark:border-amber-900/50 dark:bg-amber-950/30 dark:text-amber-50">
          <CardHeader>
            <CardTitle>Кабинет создан, платные модули пока закрыты</CardTitle>
            <CardDescription>
              Бесплатно доступны аккаунты, прокси, источники, отчеты и
              настройки. Для кампаний, AI, прогрева и парсинга подключите нужный
              модуль.
            </CardDescription>
          </CardHeader>
          <CardContent>
            <Button onClick={onOpenBilling}>
              <ShieldCheckIcon />
              Выбрать модули
            </Button>
          </CardContent>
        </Card>
      )}
      <SectionCards stats={stats} onOpenTarget={onOpenSection} />
      <div className="grid gap-4 lg:grid-cols-2">
        <Card>
          <CardHeader>
            <CardTitle>Первый рабочий результат</CardTitle>
            <CardDescription>
              {activationCompleted} из {activationSteps.length} шагов выполнено.
            </CardDescription>
            <CardAction>
              <Badge variant={hasResult ? "default" : "outline"}>
                {hasResult ? "Готово" : "Активация"}
              </Badge>
            </CardAction>
          </CardHeader>
          <CardContent className="grid gap-3">
            {activationSteps.map((step) => (
              <StatusLine
                key={step.title}
                icon={
                  step.complete ? (
                    <CheckCircle2Icon className="text-emerald-600" />
                  ) : (
                    <CircleHelpIcon />
                  )
                }
                title={step.title}
                value={step.complete ? "Выполнено" : "Перейти"}
                onClick={() => onOpenSection(step.section)}
              />
            ))}
            <Separator />
            <Button onClick={onOpenLaunch}>
              <PlayIcon />
              {hasCampaign ? "Открыть кампании" : "Создать первую кампанию"}
            </Button>
          </CardContent>
        </Card>
        <Card>
          <CardHeader>
            <CardTitle>Состояние системы</CardTitle>
            <CardDescription>
              Только реальные данные из API, без демонстрационных графиков.
            </CardDescription>
          </CardHeader>
          <CardContent className="grid gap-4">
            <StatusLine
              icon={<RadioTowerIcon />}
              title="Источники всего"
              value={String(data.sources.length)}
              onClick={() => onOpenSection("sources")}
            />
            <StatusLine
              icon={<MessageSquareTextIcon />}
              title="Доступны для чтения"
              value={String(availableSources)}
              onClick={() => onOpenSection("sources")}
            />
            <StatusLine
              icon={<FlameKindlingIcon />}
              title="Планов прогрева"
              value={String(data.warmupPlans.length)}
              onClick={() => onOpenSection("warmup")}
            />
            <StatusLine
              icon={<BotIcon />}
              title="Активных кампаний"
              value={String(activeCampaigns)}
              onClick={() => onOpenSection("neuro")}
            />
          </CardContent>
        </Card>
      </div>
      <LiveSummary data={data} onOpenSection={onOpenSection} />
    </>
  );
}

function OperationsAdminScreen({
  token,
  workspaceId,
  isDeveloperUser,
}: {
  token: string;
  workspaceId: string;
  isDeveloperUser: boolean;
}) {
  const [health, setHealth] = React.useState<OperationsHealth | null>(null);
  const [events, setEvents] = React.useState<OperationalEvent[]>([]);
  const [serverProblemEvents, setServerProblemEvents] = React.useState<
    OperationalEvent[]
  >([]);
  const [eventLimit, setEventLimit] = React.useState(300);
  const [selectedEvent, setSelectedEvent] =
    React.useState<OperationalEvent | null>(null);
  const [loading, setLoading] = React.useState(false);
  const [busyAction, setBusyAction] = React.useState<string | null>(null);
  const [error, setError] = React.useState<string | null>(null);
  const problemEvents = React.useMemo(
    () => serverProblemEvents.filter((event) => !event.resolved_at),
    [serverProblemEvents],
  );
  const problemChecks = React.useMemo(
    () => (health?.checks || []).filter((check) => check.status !== "ok"),
    [health?.checks],
  );

  const loadOperations = React.useCallback(async () => {
    if (!isDeveloperUser) return;
    setLoading(true);
    setError(null);
    try {
      const [nextHealth, nextEvents, nextProblemEvents] = await Promise.all([
        apiRequest<OperationsHealth>("/operations/health", {
          token,
          workspaceId,
        }),
        apiRequest<OperationalEvent[]>(
          `/operations/events?limit=${eventLimit}`,
          {
            token,
            workspaceId,
          },
        ),
        apiRequest<OperationalEvent[]>(
          `/operations/events?problem_only=true&unresolved_only=true&limit=${eventLimit}`,
          {
            token,
            workspaceId,
          },
        ),
      ]);
      setHealth(nextHealth);
      setEvents(nextEvents);
      setServerProblemEvents(nextProblemEvents);
    } catch (err) {
      setError(
        err instanceof Error ? err.message : "Не удалось загрузить админку",
      );
    } finally {
      setLoading(false);
    }
  }, [eventLimit, isDeveloperUser, token, workspaceId]);

  React.useEffect(() => {
    void loadOperations();
    const interval = window.setInterval(() => void loadOperations(), 30000);
    return () => window.clearInterval(interval);
  }, [loadOperations]);

  async function runAction(kind: "monitor" | "alert") {
    setBusyAction(kind);
    setError(null);
    try {
      await apiRequest(
        kind === "monitor"
          ? "/operations/monitor/run"
          : "/operations/alerts/test",
        {
          method: "POST",
          token,
          workspaceId,
        },
      );
      await loadOperations();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Действие не выполнено");
    } finally {
      setBusyAction(null);
    }
  }

  if (!isDeveloperUser) {
    return (
      <Card>
        <CardHeader>
          <CardTitle>Доступ закрыт</CardTitle>
          <CardDescription>
            Эта админка доступна только внутреннему developer-аккаунту.
          </CardDescription>
        </CardHeader>
      </Card>
    );
  }

  return (
    <div className="grid gap-4">
      {error && (
        <Alert variant="destructive">
          <XCircleIcon />
          <AlertTitle>Админка не обновилась</AlertTitle>
          <AlertDescription>{error}</AlertDescription>
        </Alert>
      )}
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div>
          <h2 className="text-2xl font-semibold tracking-normal">
            Operation Events
          </h2>
          <p className="text-muted-foreground">
            Ошибки, heartbeat фоновых процессов, алерты и состояние кампаний.
          </p>
        </div>
        <div className="flex flex-wrap gap-2">
          <Button variant="outline" onClick={loadOperations} disabled={loading}>
            <RefreshCwIcon className={cn(loading && "animate-spin")} />
            Обновить
          </Button>
          <Button
            variant="outline"
            onClick={() => runAction("alert")}
            disabled={Boolean(busyAction)}
          >
            <BellRingIcon />
            Тест алерта
          </Button>
          <Button
            onClick={() => runAction("monitor")}
            disabled={Boolean(busyAction)}
          >
            <ActivityIcon />
            Проверить сейчас
          </Button>
        </div>
      </div>

      <div className="grid gap-4 xl:grid-cols-4">
        <OperationMetricCard
          title="Статус"
          value={healthStatusLabel(health?.status)}
          tone={health?.status}
        />
        <OperationMetricCard
          title="Активных запусков"
          value={health?.counters.active_campaign_runs ?? 0}
        />
        <OperationMetricCard
          title="Зависших запусков"
          value={health?.counters.stale_campaign_runs ?? 0}
          tone={health?.counters.stale_campaign_runs ? "critical" : "ok"}
        />
        <OperationMetricCard
          title="Ошибок за сутки"
          value={`${health?.counters.error_events_24h ?? 0} / ${health?.counters.critical_events_24h ?? 0}`}
          tone={
            health?.counters.critical_events_24h
              ? "critical"
              : health?.counters.error_events_24h
                ? "warning"
                : "ok"
          }
        />
      </div>

      <Card>
        <CardHeader>
          <div className="flex flex-wrap items-start justify-between gap-3">
            <div>
              <CardTitle>Журнал событий</CardTitle>
              <CardDescription>
                Сначала проблемы, затем полный поток событий. Клик по строке
                открывает детали и подсказку.
              </CardDescription>
            </div>
            <div className="flex items-center gap-2">
              <Label
                htmlFor="operations-event-limit"
                className="text-sm text-muted-foreground"
              >
                Событий
              </Label>
              <NativeSelect
                id="operations-event-limit"
                value={String(eventLimit)}
                onChange={(event) => setEventLimit(Number(event.target.value))}
                className="h-9 w-28"
              >
                {[50, 100, 300, 1000].map((limit) => (
                  <NativeSelectOption key={limit} value={String(limit)}>
                    {limit}
                  </NativeSelectOption>
                ))}
              </NativeSelect>
            </div>
          </div>
        </CardHeader>
        <CardContent>
          <Tabs defaultValue="problems">
            <TabsList>
              <TabsTrigger value="problems">
                Проблемные события ·{" "}
                {problemEvents.length + problemChecks.length}
              </TabsTrigger>
              <TabsTrigger value="recent">
                Последние события · {events.length}
              </TabsTrigger>
              <TabsTrigger value="checks">
                Проверки · {problemChecks.length}
              </TabsTrigger>
            </TabsList>
            <TabsContent value="problems" className="mt-4 grid gap-4">
              {problemChecks.length ? (
                <div className="grid gap-3 md:grid-cols-2">
                  {problemChecks.map((check) => (
                    <div
                      key={check.key}
                      className="rounded-lg border border-red-200 bg-red-50 p-4 text-red-950"
                    >
                      <div className="flex items-center justify-between gap-3">
                        <div className="font-medium">{check.label}</div>
                        <Badge variant="destructive">
                          {healthStatusLabel(check.status)}
                        </Badge>
                      </div>
                      <p className="mt-2 text-sm">{check.message}</p>
                      {check.updated_at ? (
                        <p className="mt-2 text-xs text-red-700">
                          Обновлено: {formatDateTimeRu(check.updated_at)}
                        </p>
                      ) : null}
                      <p className="mt-3 text-sm text-red-800">
                        {operationCheckHint(check.key)}
                      </p>
                    </div>
                  ))}
                </div>
              ) : null}
              <OperationalEventsTable
                events={problemEvents}
                emptyText="Проблемных событий в загруженном диапазоне нет."
                onOpenEvent={setSelectedEvent}
              />
            </TabsContent>
            <TabsContent value="recent" className="mt-4">
              <OperationalEventsTable
                events={events}
                emptyText="Событий пока нет."
                onOpenEvent={setSelectedEvent}
              />
            </TabsContent>
            <TabsContent value="checks" className="mt-4">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Проверка</TableHead>
                    <TableHead>Статус</TableHead>
                    <TableHead>Что означает</TableHead>
                    <TableHead>Что делать</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {(health?.checks || []).map((check) => (
                    <TableRow key={check.key}>
                      <TableCell className="font-medium">
                        {check.label}
                      </TableCell>
                      <TableCell>
                        <Badge
                          variant={
                            check.status === "critical"
                              ? "destructive"
                              : "outline"
                          }
                        >
                          {healthStatusLabel(check.status)}
                        </Badge>
                      </TableCell>
                      <TableCell className="text-muted-foreground">
                        {check.message}
                      </TableCell>
                      <TableCell className="text-muted-foreground">
                        {operationCheckHint(check.key)}
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TabsContent>
          </Tabs>
        </CardContent>
      </Card>

      <div className="grid gap-4 lg:grid-cols-2">
        <Card>
          <CardHeader>
            <CardTitle>Проверки</CardTitle>
            <CardDescription>
              То, что должно быть понятно сразу, без чтения raw-логов.
            </CardDescription>
          </CardHeader>
          <CardContent className="grid gap-3">
            {(health?.checks || []).map((check) => (
              <StatusLine
                key={check.key}
                icon={<ActivityIcon />}
                title={check.label}
                value={check.message}
              />
            ))}
            {!health?.checks.length && (
              <p className="text-sm text-muted-foreground">
                Проверки загружаются.
              </p>
            )}
          </CardContent>
        </Card>
        <Card>
          <CardHeader>
            <CardTitle>Аккаунты Telegram</CardTitle>
            <CardDescription>
              Быстрый срез по рабочим и проблемным аккаунтам.
            </CardDescription>
          </CardHeader>
          <CardContent className="grid gap-3">
            <StatusLine
              icon={<ShieldCheckIcon />}
              title="Активные"
              value={String(health?.counters.telegram_accounts_active ?? 0)}
            />
            <StatusLine
              icon={<XCircleIcon />}
              title="Проблемные"
              value={String(health?.counters.telegram_accounts_problem ?? 0)}
            />
            <StatusLine
              icon={<RefreshCwIcon />}
              title="Обновлено"
              value={
                health?.generated_at
                  ? formatDateTimeRu(health.generated_at)
                  : "загрузка"
              }
            />
          </CardContent>
        </Card>
      </div>
      <OperationalEventDialog
        event={selectedEvent}
        onOpenChange={(open) => !open && setSelectedEvent(null)}
      />
    </div>
  );
}

