function healthStatusLabel(status?: OperationsHealth["status"]) {
  if (status === "critical") return "Критика";
  if (status === "warning") return "Внимание";
  if (status === "ok") return "ОК";
  return "Загрузка";
}

function operationSeverityLabel(severity: OperationalEvent["severity"]) {
  return {
    info: "Инфо",
    warning: "Внимание",
    error: "Ошибка",
    critical: "Критика",
  }[severity];
}

function operationCheckHint(key: string) {
  const hints: Record<string, string> = {
    campaign_runner:
      'Откройте проблемные события: там должен быть campaign_id/run_id. Если событий нет, нажмите "Проверить сейчас".',
    live_listener:
      "Проверьте контейнер demo-platform-live-listener и heartbeat. Если он давно молчит, новые посты не будут обрабатываться.",
    telegram_accounts:
      "Откройте раздел аккаунтов и проверьте статусы, спам-блоки, прокси и авторизацию Telegram-сессий.",
    error_budget:
      "Смотрите вкладку проблемных событий: там собраны warning/error/critical за загруженный диапазон.",
    telegram_alerts:
      "Заполните TELEGRAM_ALERT_BOT_TOKEN и TELEGRAM_ALERT_CHAT_ID, затем включите TELEGRAM_ALERTS_ENABLED=true.",
  };
  return (
    hints[key] ||
    "Откройте событие в журнале и посмотрите payload, entity_id и source."
  );
}

function operationEventHint(event: OperationalEvent) {
  const eventType = event.event_type;
  if (eventType === "campaign_run_stale") {
    return "Кампания считается запущенной, но дольше рабочего порога не обновляла heartbeat. Обычно это worker занят длинным Telegram-тиком или был перезапущен. Проверьте контейнер worker, campaign_id и run_id из payload.";
  }
  if (eventType === "campaign_run_failed") {
    return "Запуск кампании завершился ошибкой. Откройте кампанию по campaign_id/run_id, проверьте error_code и последние campaign_events.";
  }
  if (eventType === "comment_send_failed") {
    return "Комментарий не отправился в Telegram. Проверьте source_id, account_id, error_code, доступ к обсуждению и права аккаунта.";
  }
  if (eventType === "source_fetch_failed") {
    return "Источник не удалось прочитать. Проверьте доступность канала/чата для аккаунта, прокси и не ушёл ли источник в архив.";
  }
  if (
    eventType === "live_listener_failed" ||
    eventType === "live_message_processing_failed"
  ) {
    return "Проблема в live-listener. Проверьте контейнер demo-platform-live-listener, Telegram-сессию аккаунта, прокси и OpenAI proxy.";
  }
  if (event.category === "live_listener" && event.severity === "info") {
    return "Это heartbeat: live-listener жив и слушает источники. Само по себе это не ошибка.";
  }
  return "Смотрите payload: там лежат campaign_id, run_id, account_id, source_id или error_code, если они были известны в момент события.";
}

