function AccountsArchiveScreen({
  accounts,
  proxies,
  actionBusy,
  onBack,
  onPatchAccount,
  onPatchAccountProfile,
  onAccountAction,
  onLoadAccountProfile,
}: {
  accounts: TelegramAccount[];
  proxies: Proxy[];
  actionBusy: string | null;
  onBack: () => void;
  onPatchAccount: (
    accountId: string,
    payload: AccountPatchPayload,
  ) => Promise<void>;
  onPatchAccountProfile: (
    accountId: string,
    payload: AccountProfilePatchPayload,
  ) => Promise<TelegramAccountProfile>;
  onAccountAction: (
    accountId: string,
    action: "archive" | "quarantine" | "restore" | "delete",
  ) => Promise<void>;
  onLoadAccountProfile: (accountId: string) => Promise<TelegramAccountProfile>;
}) {
  const proxyById = React.useMemo(
    () => new Map(proxies.map((proxy) => [proxy.id, proxy])),
    [proxies],
  );
  const [selectedAccountId, setSelectedAccountId] = React.useState<
    string | null
  >(null);
  const [profile, setProfile] = React.useState<TelegramAccountProfile | null>(
    null,
  );
  const [profileError, setProfileError] = React.useState<string | null>(null);
  const [profileLoading, setProfileLoading] = React.useState(false);
  const selectedAccount =
    accounts.find((account) => account.id === selectedAccountId) || null;

  React.useEffect(() => {
    if (!selectedAccountId) {
      setProfile(null);
      setProfileError(null);
      return;
    }

    let cancelled = false;
    setProfileLoading(true);
    setProfile(null);
    setProfileError(null);
    void onLoadAccountProfile(selectedAccountId)
      .then((value) => {
        if (!cancelled) setProfile(value);
      })
      .catch((error) => {
        if (!cancelled) setProfileError(errorMessage(error));
      })
      .finally(() => {
        if (!cancelled) setProfileLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [onLoadAccountProfile, selectedAccountId]);

  return (
    <>
      <Card>
        <CardHeader>
          <CardTitle>Архив аккаунтов</CardTitle>
          <CardDescription>
            Здесь лежат аккаунты, которые убраны из рабочего списка и не
            выбираются в новых сценариях.
          </CardDescription>
          <CardAction>
            <Button type="button" variant="outline" onClick={onBack}>
              Вернуться к аккаунтам
            </Button>
          </CardAction>
        </CardHeader>
        <CardContent>
          {accounts.length ? (
            <Table className="w-full table-fixed">
              <colgroup>
                <col className="w-[44%]" />
                <col className="w-[130px]" />
                <col className="w-[130px]" />
                <col className="w-[420px]" />
              </colgroup>
              <TableHeader>
                <TableRow>
                  <TableHead>Аккаунт</TableHead>
                  <TableHead>Статус</TableHead>
                  <TableHead>Прокси</TableHead>
                  <TableHead className="text-right">Действия</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {accounts.map((account) => {
                  const proxy = account.proxy_id
                    ? proxyById.get(account.proxy_id)
                    : null;
                  return (
                    <TableRow
                      key={account.id}
                      className="cursor-pointer"
                      onClick={() => setSelectedAccountId(account.id)}
                    >
                      <TableCell className="min-w-0">
                        <AccountIdentity account={account} />
                      </TableCell>
                      <TableCell>
                        <Badge variant="secondary">В архиве</Badge>
                      </TableCell>
                      <TableCell>
                        <ProxyTooltipLabel proxy={proxy || null} />
                      </TableCell>
                      <TableCell>
                        <div
                          className="flex min-w-0 items-center justify-end gap-2 whitespace-nowrap"
                          onClick={(event) => event.stopPropagation()}
                        >
                          <Button
                            variant="outline"
                            size="sm"
                            className="min-w-32"
                            disabled={
                              actionBusy === `account-restore-${account.id}`
                            }
                            onClick={() =>
                              void onAccountAction(account.id, "restore")
                            }
                          >
                            <RefreshCwIcon />
                            Восстановить
                          </Button>
                          <AccountEditDialog
                            account={account}
                            proxies={proxies}
                            isBusy={actionBusy === `account-edit-${account.id}`}
                            onPatchAccount={onPatchAccount}
                            onPatchAccountProfile={onPatchAccountProfile}
                            onLoadAccountProfile={onLoadAccountProfile}
                          />
                          <Button
                            variant="ghost"
                            size="icon"
                            disabled={
                              actionBusy === `account-delete-${account.id}`
                            }
                            onClick={() =>
                              void onAccountAction(account.id, "delete")
                            }
                          >
                            <Trash2Icon />
                          </Button>
                        </div>
                      </TableCell>
                    </TableRow>
                  );
                })}
              </TableBody>
            </Table>
          ) : (
            <EmptyState
              icon={<ArchiveIcon />}
              title="Архив пуст"
              description="Когда отправите аккаунт в архив, он исчезнет из основного списка и появится здесь."
            />
          )}
        </CardContent>
      </Card>
      <AccountArchiveDetailsDialog
        account={selectedAccount}
        profile={profile}
        isLoading={profileLoading}
        error={profileError}
        open={Boolean(selectedAccount)}
        onOpenChange={(open) => {
          if (!open) setSelectedAccountId(null);
        }}
      />
    </>
  );
}

function AccountEditDialog({
  account,
  proxies,
  isBusy,
  onPatchAccount,
  onPatchAccountProfile,
  onLoadAccountProfile,
}: {
  account: TelegramAccount;
  proxies: Proxy[];
  isBusy: boolean;
  onPatchAccount: (
    accountId: string,
    payload: AccountPatchPayload,
  ) => Promise<void>;
  onPatchAccountProfile: (
    accountId: string,
    payload: AccountProfilePatchPayload,
  ) => Promise<TelegramAccountProfile>;
  onLoadAccountProfile: (accountId: string) => Promise<TelegramAccountProfile>;
}) {
  const [open, setOpen] = React.useState(false);
  const [profile, setProfile] = React.useState<TelegramAccountProfile | null>(
    null,
  );
  const [profileLoading, setProfileLoading] = React.useState(false);
  const [editError, setEditError] = React.useState<string | null>(null);
  const [profileTouchedFields, setProfileTouchedFields] = React.useState<
    string[]
  >([]);

  React.useEffect(() => {
    if (!open) return;
    let cancelled = false;
    setProfileLoading(true);
    setEditError(null);
    void onLoadAccountProfile(account.id)
      .then((value) => {
        if (!cancelled) setProfile(value);
      })
      .catch(() => {
        if (!cancelled) setProfile(null);
      })
      .finally(() => {
        if (!cancelled) setProfileLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [account.id, onLoadAccountProfile, open]);

  React.useEffect(() => {
    if (open) setProfileTouchedFields([]);
  }, [account.id, open, profile?.account_id]);

  function markProfileFieldTouched(fieldName: string) {
    setProfileTouchedFields((current) =>
      current.includes(fieldName) ? current : [...current, fieldName],
    );
  }

  function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setEditError(null);
    const form = new FormData(event.currentTarget);
    const proxyId = cleanOptionalText(form.get("proxy_id"));
    const nextUsername =
      cleanOptionalText(form.get("username"))?.replace(/^@/, "") || null;
    const profilePatch: AccountProfilePatchPayload = {};
    if (profile) {
      const firstName = String(form.get("first_name") ?? "").trim();
      const lastName = String(form.get("last_name") ?? "").trim();
      const about = String(form.get("about") ?? "").trim();
      const currentUsername =
        (profile.username || account.username || "").replace(/^@/, "") || null;

      if (
        profileTouchedFields.includes("first_name") &&
        firstName &&
        firstName !== (profile.first_name || "")
      )
        profilePatch.first_name = firstName;
      if (
        profileTouchedFields.includes("last_name") &&
        lastName !== (profile.last_name || "")
      )
        profilePatch.last_name = lastName;
      if (
        profileTouchedFields.includes("username") &&
        nextUsername !== currentUsername
      )
        profilePatch.username = nextUsername;
      if (
        profileTouchedFields.includes("about") &&
        about !== (profile.about || profile.bio || "")
      )
        profilePatch.about = about;
    }
    const accountPatch: AccountPatchPayload = {
      display_name: cleanOptionalText(form.get("display_name")),
      proxy_id: proxyId,
      proxy_required: Boolean(form.get("proxy_required")),
      status: String(form.get("status") || account.status),
      origin: (cleanOptionalText(form.get("origin")) as TelegramAccount["origin"]) || null,
      claimed_age_days: numberOrNull(form.get("claimed_age_days")),
      real_age_days: numberOrNull(form.get("real_age_days")),
      incubator_mode: Boolean(form.get("incubator_mode")),
      incubator_until_at: cleanOptionalText(form.get("incubator_until_at")),
    };
    const warmupTrustLevel = String(form.get("warmup_trust_level") || "current");
    if (warmupTrustLevel !== "current") {
      const warmupPreset = accountWarmupPresetPayload(warmupTrustLevel);
      accountPatch.warmup_status = warmupPreset.warmup_status;
      accountPatch.warmup_score = warmupPreset.warmup_score;
    }
    if (profileTouchedFields.includes("username")) {
      accountPatch.username = nextUsername;
    }
    setOpen(false);
    void (async () => {
      try {
        await onPatchAccount(account.id, accountPatch);
        if (Object.keys(profilePatch).length) {
          const updatedProfile = await onPatchAccountProfile(
            account.id,
            profilePatch,
          );
          setProfile(updatedProfile);
        }
      } catch (error) {
        window.alert(errorMessage(error));
      }
    })();
  }

  const warmupTrustDefault =
    account.warmup_score >= 80 ||
    ["completed", "succeeded", "ready"].includes(account.warmup_status)
      ? "trusted"
      : account.warmup_status === "validated"
        ? "validated"
        : ["warming", "running", "scheduled"].includes(account.warmup_status)
          ? "warming"
          : "not_started";

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button variant="outline" size="sm" className="min-w-32">
          <Edit3Icon />
          Редактировать
        </Button>
      </DialogTrigger>
      <DialogContent className="flex max-h-[min(92dvh,780px)] w-[min(calc(100vw-1rem),820px)] !max-w-[820px] flex-col gap-0 overflow-hidden p-0 sm:!max-w-[820px]">
        <form
          key={profile?.account_id || `${account.id}-loading`}
          className="flex min-h-0 flex-1 flex-col"
          onSubmit={(event) => void handleSubmit(event)}
        >
          <DialogHeader className="shrink-0 border-b px-5 py-4">
            <DialogTitle>Редактировать аккаунт</DialogTitle>
            <DialogDescription>
              Основные данные, статус и сетевой профиль аккаунта.
            </DialogDescription>
          </DialogHeader>
          <FieldGroup className="min-h-0 flex-1 gap-3 overflow-y-auto px-5 py-4">
            {editError && (
              <Alert variant="destructive">
                <AlertTitle>Не удалось сохранить</AlertTitle>
                <AlertDescription>{editError}</AlertDescription>
              </Alert>
            )}
            <div className="grid gap-3 md:grid-cols-2">
              <Field>
                <FieldLabel htmlFor={`account-name-${account.id}`}>
                  Название
                </FieldLabel>
                <Input
                  id={`account-name-${account.id}`}
                  name="display_name"
                  defaultValue={account.display_name || ""}
                  disabled={profileLoading}
                />
              </Field>
              <Field>
                <FieldLabel htmlFor={`account-username-${account.id}`}>
                  Username
                </FieldLabel>
                <Input
                  id={`account-username-${account.id}`}
                  name="username"
                  defaultValue={profile?.username || account.username || ""}
                  disabled={profileLoading || !profile}
                  onChange={() => markProfileFieldTouched("username")}
                />
              </Field>
            </div>
            <div className="grid gap-3 md:grid-cols-2">
              <Field>
                <FieldLabel htmlFor={`account-first-name-${account.id}`}>
                  Имя в Telegram
                </FieldLabel>
                <Input
                  id={`account-first-name-${account.id}`}
                  name="first_name"
                  defaultValue={profile?.first_name || ""}
                  disabled={profileLoading || !profile}
                  onChange={() => markProfileFieldTouched("first_name")}
                />
              </Field>
              <Field>
                <FieldLabel htmlFor={`account-last-name-${account.id}`}>
                  Фамилия в Telegram
                </FieldLabel>
                <Input
                  id={`account-last-name-${account.id}`}
                  name="last_name"
                  defaultValue={profile?.last_name || ""}
                  disabled={profileLoading || !profile}
                  onChange={() => markProfileFieldTouched("last_name")}
                />
              </Field>
            </div>
            <Field>
              <FieldLabel htmlFor={`account-about-${account.id}`}>
                Описание профиля
              </FieldLabel>
              <Textarea
                id={`account-about-${account.id}`}
                name="about"
                className="min-h-20"
                defaultValue={profile?.about || profile?.bio || ""}
                disabled={profileLoading || !profile}
                onChange={() => markProfileFieldTouched("about")}
              />
            </Field>
            <div className="grid gap-3 md:grid-cols-3">
              <Field>
                <FieldLabel htmlFor={`account-status-${account.id}`}>
                  Статус
                </FieldLabel>
                <NativeSelect
                  id={`account-status-${account.id}`}
                  name="status"
                  defaultValue={account.status}
                  disabled={profileLoading}
                >
                  <NativeSelectOption value="new">Новый</NativeSelectOption>
                  <NativeSelectOption value="active">
                    Активен
                  </NativeSelectOption>
                  <NativeSelectOption value="warming">
                    Прогревается
                  </NativeSelectOption>
                  <NativeSelectOption value="incubator">
                    Инкубатор
                  </NativeSelectOption>
                  <NativeSelectOption value="archived">
                    Архив
                  </NativeSelectOption>
                </NativeSelect>
              </Field>
              <Field>
                <HelpLabel
                  htmlFor={`account-warmup-trust-${account.id}`}
                  tip="Доверенный / личный выставляет прогрев 100/100. Реальные Telegram-ограничения остаются отдельным статусом и не скрываются."
                >
                  Прогрев / доверие
                </HelpLabel>
                <NativeSelect
                  id={`account-warmup-trust-${account.id}`}
                  name="warmup_trust_level"
                  defaultValue={warmupTrustDefault}
                  disabled={profileLoading}
                >
                  <NativeSelectOption value="not_started">
                    Нужен прогрев
                  </NativeSelectOption>
                  <NativeSelectOption value="validated">
                    Проверен
                  </NativeSelectOption>
                  <NativeSelectOption value="warming">
                    Прогревается
                  </NativeSelectOption>
                  <NativeSelectOption value="trusted">
                    Доверенный / личный
                  </NativeSelectOption>
                </NativeSelect>
              </Field>
              <Field>
                <FieldLabel htmlFor={`account-proxy-${account.id}`}>
                  Прокси
                </FieldLabel>
                <NativeSelect
                  id={`account-proxy-${account.id}`}
                  name="proxy_id"
                  defaultValue={account.proxy_id || ""}
                  disabled={profileLoading}
                >
                  <NativeSelectOption value="">Без прокси — прямое подключение</NativeSelectOption>
                  {proxies.map((proxy) => (
                    <NativeSelectOption key={proxy.id} value={proxy.id}>
                      {proxySelectLabel(proxy)}
                    </NativeSelectOption>
                  ))}
                </NativeSelect>
                <label className="mt-2 flex items-center gap-2 text-sm">
                  <Checkbox
                    name="proxy_required"
                    defaultChecked={account.proxy_required}
                    disabled={profileLoading}
                  />
                  Требовать прокси
                </label>
              </Field>
            </div>
            <div className="grid gap-3 sm:grid-cols-2">
              <Field>
                <FieldLabel htmlFor={`account-origin-${account.id}`}>
                  Происхождение
                </FieldLabel>
                <NativeSelect
                  id={`account-origin-${account.id}`}
                  name="origin"
                  defaultValue={account.origin || ""}
                  disabled={profileLoading}
                >
                  <NativeSelectOption value="">Не указано</NativeSelectOption>
                  <NativeSelectOption value="manual_phone_registered">
                    Ручная регистрация
                  </NativeSelectOption>
                  <NativeSelectOption value="sms_service_manual">
                    SMS + ручная история
                  </NativeSelectOption>
                  <NativeSelectOption value="market_session">
                    Маркет-сессия
                  </NativeSelectOption>
                  <NativeSelectOption value="tdata">TData</NativeSelectOption>
                </NativeSelect>
              </Field>
              <Field>
                <FieldLabel htmlFor={`account-claimed-age-${account.id}`}>
                  Заявленный возраст, дней
                </FieldLabel>
                <Input
                  id={`account-claimed-age-${account.id}`}
                  name="claimed_age_days"
                  type="number"
                  min={0}
                  max={3650}
                  defaultValue={stringFromUnknown(account.claimed_age_days)}
                  disabled={profileLoading}
                />
              </Field>
              <Field>
                <FieldLabel htmlFor={`account-real-age-${account.id}`}>
                  Реальный возраст, дней
                </FieldLabel>
                <Input
                  id={`account-real-age-${account.id}`}
                  name="real_age_days"
                  type="number"
                  min={0}
                  max={3650}
                  defaultValue={stringFromUnknown(account.real_age_days)}
                  disabled={profileLoading}
                />
              </Field>
              <Field>
                <FieldLabel htmlFor={`account-incubator-until-${account.id}`}>
                  Инкубатор до
                </FieldLabel>
                <Input
                  id={`account-incubator-until-${account.id}`}
                  name="incubator_until_at"
                  type="date"
                  defaultValue={(account.incubator_until_at || "").slice(0, 10)}
                  disabled={profileLoading}
                />
              </Field>
            </div>
            <Field>
              <label className="flex items-center gap-2 text-sm">
                <input
                  name="incubator_mode"
                  type="checkbox"
                  className="size-4"
                  defaultChecked={Boolean(account.incubator_mode)}
                  disabled={profileLoading}
                />
                Держать в инкубаторе и не допускать в кампании
                <InlineHelp tip="Инкубатор физически блокирует участие аккаунта в кампаниях, но оставляет проверки и мягкий прогрев." />
              </label>
            </Field>
          </FieldGroup>
          <DialogFooter className="shrink-0 border-t px-5 py-4">
            <Button
              type="button"
              variant="outline"
              onClick={() => setOpen(false)}
            >
              Отмена
            </Button>
            <Button type="submit" disabled={isBusy || profileLoading}>
              Сохранить
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

function AccountProfileActions({
  account,
  accounts,
  profile,
  profileLoading,
  isCloneBusy,
  isTwoFaBusy,
  onCloneAccountProfile,
  onUpdateAccountTwoFa,
  onLoadAccountProfilePhotos,
  onDeleteAccountProfilePhoto,
  onRequestAccountLoginCode,
  onProfileUpdated,
}: {
  account: TelegramAccount;
  accounts: TelegramAccount[];
  profile: TelegramAccountProfile | null;
  profileLoading: boolean;
  isCloneBusy: boolean;
  isTwoFaBusy: boolean;
  onCloneAccountProfile: (
    accountId: string,
    payload: TelegramAccountCloneProfilePayload,
  ) => Promise<TelegramAccountCloneProfileResponse>;
  onUpdateAccountTwoFa: (
    accountId: string,
    payload: AccountTwoFaPayload,
  ) => Promise<AccountTwoFaResponse>;
  onLoadAccountProfilePhotos: (
    accountId: string,
  ) => Promise<TelegramAccountProfilePhotosResponse>;
  onDeleteAccountProfilePhoto: (
    accountId: string,
    photoId: string,
  ) => Promise<TelegramAccountProfilePhotosResponse>;
  onRequestAccountLoginCode: (
    accountId: string,
  ) => Promise<TelegramAccountLoginCodeResponse>;
  onProfileUpdated: (profile: TelegramAccountProfile) => void;
}) {
  const [cloneOpen, setCloneOpen] = React.useState(false);
  const [twoFaOpen, setTwoFaOpen] = React.useState(false);
  const [cloneError, setCloneError] = React.useState<string | null>(null);
  const [twoFaError, setTwoFaError] = React.useState<string | null>(null);
  const [photos, setPhotos] = React.useState<
    TelegramAccountProfilePhotosResponse["photos"]
  >([]);
  const [photosLoading, setPhotosLoading] = React.useState(false);
  const [photosError, setPhotosError] = React.useState<string | null>(null);
  const [photoDeleteId, setPhotoDeleteId] = React.useState<string | null>(null);
  const [loginCodeBusy, setLoginCodeBusy] = React.useState(false);
  const [loginCodeMessage, setLoginCodeMessage] = React.useState<string | null>(
    null,
  );
  const [loginCodeError, setLoginCodeError] = React.useState<string | null>(
    null,
  );
  const sourceAccounts = React.useMemo(
    () => accounts.filter((item) => item.id !== account.id),
    [account.id, accounts],
  );

  const loadPhotos = React.useCallback(async () => {
    setPhotosLoading(true);
    setPhotosError(null);
    try {
      const response = await onLoadAccountProfilePhotos(account.id);
      setPhotos(response.photos);
    } catch (error) {
      setPhotosError(errorMessage(error));
    } finally {
      setPhotosLoading(false);
    }
  }, [account.id, onLoadAccountProfilePhotos]);

  React.useEffect(() => {
    let cancelled = false;
    setPhotos([]);
    setPhotosError(null);
    setPhotosLoading(true);
    void onLoadAccountProfilePhotos(account.id)
      .then((response) => {
        if (!cancelled) setPhotos(response.photos);
      })
      .catch((error) => {
        if (!cancelled) setPhotosError(errorMessage(error));
      })
      .finally(() => {
        if (!cancelled) setPhotosLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [account.id, onLoadAccountProfilePhotos]);

  async function handleCloneSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setCloneError(null);
    const formElement = event.currentTarget;
    const form = new FormData(formElement);
    const sourceRef = String(form.get("source_ref") || "").trim();
    const sourceAccountId = String(form.get("source_account_id") || "");
    if (!sourceRef && !sourceAccountId) {
      setCloneError("Укажите ссылку или выберите аккаунт-источник.");
      return;
    }
    try {
      const result = await onCloneAccountProfile(account.id, {
        source_ref: sourceRef || null,
        source_account_id: sourceAccountId || null,
        copy_name: form.get("copy_name") === "on",
        copy_bio: form.get("copy_bio") === "on",
        copy_photo: form.get("copy_photo") === "on",
        copy_stories: form.get("copy_stories") === "on",
        pin_stories: form.get("pin_stories") === "on",
        delete_old_stories: form.get("delete_old_stories") === "on",
        story_limit: clampNumber(form.get("story_limit"), 1, 20, 3),
      });
      onProfileUpdated(result.profile);
      if (result.warnings.length) {
        window.alert(result.warnings.join("\n"));
      }
      formElement.reset();
      setCloneOpen(false);
    } catch (error) {
      setCloneError(errorMessage(error));
    }
  }

  async function handleTwoFaSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setTwoFaError(null);
    const formElement = event.currentTarget;
    const form = new FormData(formElement);
    try {
      await onUpdateAccountTwoFa(account.id, {
        current_password: cleanOptionalText(form.get("current_password")),
        new_password: cleanOptionalText(form.get("new_password")),
        hint: cleanOptionalText(form.get("hint")),
        confirmation_text: String(form.get("confirmation_text") || "").trim(),
      });
      formElement.reset();
      setTwoFaOpen(false);
    } catch (error) {
      setTwoFaError(errorMessage(error));
    }
  }

  async function handleDeletePhoto(photoId: string) {
    if (!window.confirm("Удалить эту фотографию профиля из Telegram?")) {
      return;
    }
    setPhotoDeleteId(photoId);
    setPhotosError(null);
    try {
      const response = await onDeleteAccountProfilePhoto(account.id, photoId);
      setPhotos(response.photos);
    } catch (error) {
      setPhotosError(errorMessage(error));
    } finally {
      setPhotoDeleteId(null);
    }
  }

  async function handleRequestLoginCode() {
    setLoginCodeBusy(true);
    setLoginCodeMessage(null);
    setLoginCodeError(null);
    try {
      const response = await onRequestAccountLoginCode(account.id);
      setLoginCodeMessage(
        response.login_code
          ? `Код входа: ${response.login_code}`
          : response.message,
      );
    } catch (error) {
      setLoginCodeError(errorMessage(error));
    } finally {
      setLoginCodeBusy(false);
    }
  }

  return (
    <div className="grid gap-3 rounded-lg border p-3">
      <div className="flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between">
        <div className="min-w-0">
          <div className="font-medium">Действия профиля</div>
          <div className="text-muted-foreground text-sm">
            Фото, профиль, сторис и пароль аккаунта.
          </div>
        </div>
        <div className="grid gap-2 sm:grid-cols-2">
          <Button
            type="button"
            variant="outline"
            disabled={profileLoading || loginCodeBusy}
            onClick={() => void handleRequestLoginCode()}
          >
            {loginCodeBusy ? (
              <Loader2Icon className="size-4 animate-spin" />
            ) : (
              <SendIcon />
            )}
            Код входа
          </Button>
          <Dialog open={cloneOpen} onOpenChange={setCloneOpen}>
            <DialogTrigger asChild>
              <Button type="button" variant="outline" disabled={profileLoading}>
                <UserRoundIcon />
                Поставить профиль
              </Button>
            </DialogTrigger>
            <DialogContent className="w-[min(92vw,860px)] !max-w-[860px] sm:!max-w-[860px]">
              <form onSubmit={(event) => void handleCloneSubmit(event)}>
                <DialogHeader>
                  <DialogTitle>Поставить профиль</DialogTitle>
                  <DialogDescription>
                    Скопируйте имя, описание, фото и сторис из ссылки или
                    другого аккаунта.
                  </DialogDescription>
                </DialogHeader>
                <FieldGroup className="py-4">
                  <ModalError
                    error={cloneError}
                    title="Не удалось поставить профиль"
                  />
                  <div className="grid gap-3 md:grid-cols-2">
                    <Field>
                      <HelpLabel
                        htmlFor={`clone-profile-ref-${account.id}`}
                        tip="Поддерживаются @username, t.me/... и ссылка на профиль."
                      >
                        Источник ссылкой
                      </HelpLabel>
                      <Input
                        id={`clone-profile-ref-${account.id}`}
                        name="source_ref"
                        placeholder="@username или t.me/profile"
                      />
                    </Field>
                    <Field>
                      <HelpLabel
                        htmlFor={`clone-profile-account-${account.id}`}
                        tip="Можно взять профиль с импортированного аккаунта."
                      >
                        Источник из аккаунтов
                      </HelpLabel>
                      <NativeSelect
                        id={`clone-profile-account-${account.id}`}
                        name="source_account_id"
                        defaultValue=""
                      >
                        <NativeSelectOption value="">
                          Не выбран
                        </NativeSelectOption>
                        {sourceAccounts.map((item) => (
                          <NativeSelectOption key={item.id} value={item.id}>
                            {accountName(item)}
                          </NativeSelectOption>
                        ))}
                      </NativeSelect>
                    </Field>
                  </div>
                  <div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-4">
                    <label className="flex items-center gap-2 rounded-md border p-3 text-sm">
                      <Checkbox name="copy_name" defaultChecked />
                      Имя
                    </label>
                    <label className="flex items-center gap-2 rounded-md border p-3 text-sm">
                      <Checkbox name="copy_bio" defaultChecked />
                      Описание
                    </label>
                    <label className="flex items-center gap-2 rounded-md border p-3 text-sm">
                      <Checkbox name="copy_photo" defaultChecked />
                      Фото
                    </label>
                    <label className="flex items-center gap-2 rounded-md border p-3 text-sm">
                      <Checkbox name="copy_stories" />
                      Сторис
                    </label>
                  </div>
                  <div className="grid gap-3 md:grid-cols-3">
                    <Field>
                      <HelpLabel
                        htmlFor={`clone-profile-stories-${account.id}`}
                        tip="Используется только при копировании сторис."
                      >
                        Сторис, шт.
                      </HelpLabel>
                      <Input
                        id={`clone-profile-stories-${account.id}`}
                        name="story_limit"
                        type="number"
                        min={1}
                        max={20}
                        defaultValue={3}
                      />
                    </Field>
                    <label className="flex items-center gap-2 rounded-md border p-3 text-sm">
                      <Checkbox name="pin_stories" />
                      Закрепить сторис
                    </label>
                    <label className="flex items-center gap-2 rounded-md border p-3 text-sm">
                      <Checkbox name="delete_old_stories" />
                      Удалить старые
                    </label>
                  </div>
                </FieldGroup>
                <DialogFooter>
                  <Button
                    type="button"
                    variant="outline"
                    onClick={() => setCloneOpen(false)}
                  >
                    Отмена
                  </Button>
                  <Button type="submit" disabled={isCloneBusy}>
                    {isCloneBusy ? (
                      <Loader2Icon className="size-4 animate-spin" />
                    ) : (
                      <UserRoundIcon />
                    )}
                    Поставить профиль
                  </Button>
                </DialogFooter>
              </form>
            </DialogContent>
          </Dialog>
          <Dialog open={twoFaOpen} onOpenChange={setTwoFaOpen}>
            <DialogTrigger asChild>
              <Button
                type="button"
                variant="outline"
                disabled={profileLoading || profile?.can_edit_security === false}
              >
                <ShieldCheckIcon />
                Пароль / 2FA
              </Button>
            </DialogTrigger>
            <DialogContent className="w-[min(92vw,720px)] !max-w-[720px] sm:!max-w-[720px]">
              <form onSubmit={(event) => void handleTwoFaSubmit(event)}>
                <DialogHeader>
                  <DialogTitle>Пароль / 2FA</DialogTitle>
                  <DialogDescription>
                    Введите новый пароль для включения или смены 2FA. Оставьте
                    новый пароль пустым, чтобы отключить 2FA.
                  </DialogDescription>
                </DialogHeader>
                <FieldGroup className="py-4">
                  <ModalError
                    error={twoFaError}
                    title="Не удалось обновить пароль / 2FA"
                  />
                  <div className="grid gap-3 md:grid-cols-2">
                    <Field>
                      <FieldLabel htmlFor={`twofa-current-${account.id}`}>
                        Текущий пароль
                      </FieldLabel>
                      <Input
                        id={`twofa-current-${account.id}`}
                        name="current_password"
                        type="password"
                        autoComplete="current-password"
                      />
                    </Field>
                    <Field>
                      <FieldLabel htmlFor={`twofa-new-${account.id}`}>
                        Новый пароль
                      </FieldLabel>
                      <Input
                        id={`twofa-new-${account.id}`}
                        name="new_password"
                        type="password"
                        autoComplete="new-password"
                      />
                    </Field>
                  </div>
                  <Field>
                    <FieldLabel htmlFor={`twofa-hint-${account.id}`}>
                      Подсказка
                    </FieldLabel>
                    <Input id={`twofa-hint-${account.id}`} name="hint" />
                  </Field>
                  <Field>
                    <HelpLabel
                      htmlFor={`twofa-confirm-${account.id}`}
                      tip="Защита от случайного изменения пароля аккаунта."
                    >
                      Подтверждение
                    </HelpLabel>
                    <Input
                      id={`twofa-confirm-${account.id}`}
                      name="confirmation_text"
                      placeholder="CHANGE 2FA"
                      autoComplete="off"
                    />
                  </Field>
                </FieldGroup>
                <DialogFooter>
                  <Button
                    type="button"
                    variant="outline"
                    onClick={() => setTwoFaOpen(false)}
                  >
                    Отмена
                  </Button>
                  <Button type="submit" disabled={isTwoFaBusy}>
                    {isTwoFaBusy ? (
                      <Loader2Icon className="size-4 animate-spin" />
                    ) : (
                      <ShieldCheckIcon />
                    )}
                    Сохранить 2FA
                  </Button>
                </DialogFooter>
              </form>
            </DialogContent>
          </Dialog>
        </div>
      </div>
      {loginCodeMessage ? (
        <Alert>
          <CheckCircle2Icon className="size-4" />
          <AlertTitle>Код найден</AlertTitle>
          <AlertDescription>{loginCodeMessage}</AlertDescription>
        </Alert>
      ) : null}
      {loginCodeError ? (
        <ModalError error={loginCodeError} title="Не удалось получить код" />
      ) : null}
      <div className="grid gap-2 rounded-md border bg-muted/10 p-3">
        <div className="flex items-center justify-between gap-2">
          <div className="min-w-0">
            <div className="font-medium">Фотографии в Telegram</div>
            <div className="text-muted-foreground text-sm">
              Удаление конкретной старой или текущей фотографии профиля.
            </div>
          </div>
          <Button
            type="button"
            variant="outline"
            size="sm"
            disabled={photosLoading}
            onClick={() => void loadPhotos()}
          >
            {photosLoading ? (
              <Loader2Icon className="size-4 animate-spin" />
            ) : (
              <RefreshCwIcon />
            )}
            Обновить
          </Button>
        </div>
        {photosError ? (
          <ModalError error={photosError} title="Не удалось загрузить фотографии" />
        ) : null}
        {photosLoading && !photos.length ? (
          <div className="flex items-center gap-2 text-sm text-muted-foreground">
            <Loader2Icon className="size-4 animate-spin" />
            Загружаю фотографии профиля
          </div>
        ) : photos.length ? (
          <div className="grid grid-cols-[repeat(auto-fill,minmax(88px,1fr))] gap-2">
            {photos.map((photo, index) => (
              <div
                key={photo.photo_id}
                className="group relative overflow-hidden rounded-md border bg-background"
              >
                {photo.photo_data_url ? (
                  <img
                    src={photo.photo_data_url}
                    alt=""
                    className="aspect-square w-full object-cover"
                  />
                ) : (
                  <div className="flex aspect-square w-full items-center justify-center bg-muted text-sm text-muted-foreground">
                    #{index + 1}
                  </div>
                )}
                <div className="absolute left-1 top-1">
                  <Badge variant={photo.is_current ? "default" : "secondary"}>
                    {photo.is_current ? "Основная" : `Фото ${index + 1}`}
                  </Badge>
                </div>
                <Button
                  type="button"
                  variant="destructive"
                  size="icon"
                  className="absolute bottom-1 right-1 size-8 opacity-95"
                  disabled={photoDeleteId === photo.photo_id}
                  onClick={() => void handleDeletePhoto(photo.photo_id)}
                  aria-label="Удалить фотографию"
                >
                  {photoDeleteId === photo.photo_id ? (
                    <Loader2Icon className="size-4 animate-spin" />
                  ) : (
                    <Trash2Icon />
                  )}
                </Button>
              </div>
            ))}
          </div>
        ) : (
          <div className="rounded-md border border-dashed p-3 text-sm text-muted-foreground">
            Telegram не вернул сохраненных фотографий профиля.
          </div>
        )}
      </div>
    </div>
  );
}

function AvatarPresetInline({
  account,
  profile,
  isBusy,
  onUploadAvatar,
}: {
  account: TelegramAccount;
  profile: TelegramAccountProfile | null;
  isBusy: boolean;
  onUploadAvatar: (
    accountId: string,
    file: Blob,
    fileName: string,
  ) => Promise<void>;
}) {
  const [presetId, setPresetId] = React.useState("");
  const selectedPreset =
    avatarPresets.find((preset) => preset.id === presetId) || null;
  const currentPhotoSrc =
    profile?.photo_data_url || account.profile_photo_data_url || null;
  const [previewSrc, setPreviewSrc] = React.useState<string>(
    currentPhotoSrc || "",
  );
  const [previewSource, setPreviewSource] = React.useState<
    "empty" | "profile" | "preset" | "upload"
  >(
    currentPhotoSrc ? "profile" : "empty",
  );
  const fileInputId = `avatar-file-${account.id}`;

  // Changing the account resets an edited preview; photo refreshes are handled below.
  const currentPhotoRef = React.useRef(currentPhotoSrc);
  React.useEffect(() => {
    currentPhotoRef.current = currentPhotoSrc;
  }, [currentPhotoSrc]);

  React.useEffect(() => {
    const nextPhotoSrc = currentPhotoRef.current;
    setPreviewSrc(nextPhotoSrc || "");
    setPreviewSource(nextPhotoSrc ? "profile" : "empty");
    setPresetId("");
  }, [account.id]);

  React.useEffect(() => {
    if (previewSource === "preset" || previewSource === "upload") return;
    setPreviewSrc(currentPhotoSrc || "");
    setPreviewSource(currentPhotoSrc ? "profile" : "empty");
  }, [currentPhotoSrc, previewSource]);

  React.useEffect(() => {
    const loadedImages: HTMLImageElement[] = [];
    for (const preset of avatarPresets) {
      const image = new Image();
      image.decoding = "async";
      image.src = preset.thumb;
      loadedImages.push(image);
    }
    return () => {
      loadedImages.length = 0;
    };
  }, []);

  function handleFileChange(event: React.ChangeEvent<HTMLInputElement>) {
    const file = event.currentTarget.files?.[0];
    if (!file) return;
    const previousPreview = previewSrc;
    const previousSource = previewSource;
    const objectUrl = URL.createObjectURL(file);
    setPreviewSrc(objectUrl);
    setPreviewSource("upload");
    void onUploadAvatar(account.id, file, file.name)
      .catch((error: unknown) => {
        setPreviewSrc(previousPreview);
        setPreviewSource(previousSource);
        window.alert(errorMessage(error));
      })
      .finally(() => URL.revokeObjectURL(objectUrl));
    event.currentTarget.value = "";
  }

  async function handlePresetUpload() {
    if (!selectedPreset) return;
    const previousPreview = previewSrc;
    const previousSource = previewSource;
    setPreviewSrc(selectedPreset.src);
    setPreviewSource("preset");
    try {
      const response = await fetch(selectedPreset.src);
      if (!response.ok) throw new Error("Не удалось загрузить пресет");
      const blob = await response.blob();
      await onUploadAvatar(account.id, blob, `demo-platform-${selectedPreset.id}.jpg`);
    } catch (error) {
      setPreviewSrc(previousPreview);
      setPreviewSource(previousSource);
      window.alert(errorMessage(error));
    }
  }

  return (
    <div className="rounded-lg border p-3">
      <div className="grid gap-3 sm:grid-cols-[128px_minmax(0,1fr)] sm:items-start">
        <div className="flex items-center gap-3 sm:block">
          {previewSrc ? (
            <img
              src={previewSrc}
              alt=""
              className="size-16 rounded-lg object-cover sm:size-24"
            />
          ) : (
            <div className="flex size-16 items-center justify-center rounded-lg bg-muted text-lg font-semibold text-muted-foreground sm:size-24">
              {initials(accountName(account))}
            </div>
          )}
          <div className="min-w-0 sm:mt-2">
            <div className="font-medium">Фото профиля</div>
            <div className="text-sm text-muted-foreground">
              Пресет или свое фото
            </div>
          </div>
        </div>
        <Field>
          <div className="grid max-h-40 grid-cols-[repeat(auto-fill,48px)] justify-start gap-2 overflow-y-auto rounded-lg border bg-muted/10 p-2 sm:max-h-44">
            {avatarPresets.map((preset, index) => {
              const selected = preset.id === presetId;
              return (
                <button
                  key={preset.id}
                  type="button"
                  className={cn(
                    "relative size-12 overflow-hidden rounded-md border bg-background transition hover:border-foreground/40 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
                    selected && "border-primary ring-2 ring-primary/30",
                  )}
                  title={preset.label}
                  aria-label={`Выбрать ${preset.label}`}
                  aria-pressed={selected}
                  onClick={() => {
                    setPresetId(preset.id);
                    setPreviewSrc(preset.src);
                    setPreviewSource("preset");
                  }}
                >
                  <img
                    src={preset.thumb}
                    alt=""
                    className="size-full object-cover"
                    decoding="async"
                    fetchPriority={index < 24 ? "high" : "auto"}
                    loading={index < 24 ? "eager" : "lazy"}
                  />
                  {selected ? (
                    <span className="absolute right-1 top-1 flex size-5 items-center justify-center rounded-full bg-primary text-primary-foreground shadow-sm">
                      <CheckIcon className="size-3" />
                    </span>
                  ) : null}
                </button>
              );
            })}
          </div>
          <div className="flex flex-wrap items-center gap-2">
            <Button
              type="button"
              variant="outline"
              size="sm"
              disabled={isBusy || !selectedPreset}
              onClick={() => void handlePresetUpload()}
            >
              <UploadIcon />
              Пресет
            </Button>
            <label
              htmlFor={fileInputId}
              className={cn(
                buttonVariants({ variant: "outline", size: "sm" }),
                isBusy && "pointer-events-none opacity-50",
              )}
            >
              <UploadIcon />
              Свое фото
            </label>
            {presetId ? (
              <Button
                type="button"
                variant="ghost"
                size="sm"
                onClick={() => {
                  setPresetId("");
                  setPreviewSrc(currentPhotoSrc || "");
                  setPreviewSource(currentPhotoSrc ? "profile" : "empty");
                }}
              >
                Снять выбор
              </Button>
            ) : null}
          </div>
          <Input
            id={fileInputId}
            className="sr-only"
            type="file"
            accept="image/jpeg,image/png,image/webp"
            disabled={isBusy}
            onChange={handleFileChange}
          />
        </Field>
      </div>
    </div>
  );
}

function AccountDetailsDialog({
  onLoadSafetyState,
  onResumeSafety,
  onAdmitSafety,
  account,
  accounts,
  profile,
  isLoading,
  error,
  open,
  actionBusy,
  onLoadAccountHealthEvents,
  onLoadAccountProfilePhotos,
  onDeleteAccountProfilePhoto,
  onRequestAccountLoginCode,
  onUploadAvatar,
  onCloneAccountProfile,
  onUpdateAccountTwoFa,
  onProfileUpdated,
  onOpenChange,
}: {
  account: TelegramAccount | null;
  accounts: TelegramAccount[];
  profile: TelegramAccountProfile | null;
  isLoading: boolean;
  error: string | null;
  open: boolean;
  actionBusy: string | null;
  onLoadAccountHealthEvents: (accountId: string) => Promise<AccountHealthEvent[]>;
  onLoadAccountProfilePhotos: (
    accountId: string,
  ) => Promise<TelegramAccountProfilePhotosResponse>;
  onDeleteAccountProfilePhoto: (
    accountId: string,
    photoId: string,
  ) => Promise<TelegramAccountProfilePhotosResponse>;
  onRequestAccountLoginCode: (
    accountId: string,
  ) => Promise<TelegramAccountLoginCodeResponse>;
  onUploadAvatar: (
    accountId: string,
    file: Blob,
    fileName: string,
  ) => Promise<void>;
  onCloneAccountProfile: (
    accountId: string,
    payload: TelegramAccountCloneProfilePayload,
  ) => Promise<TelegramAccountCloneProfileResponse>;
  onUpdateAccountTwoFa: (
    accountId: string,
    payload: AccountTwoFaPayload,
  ) => Promise<AccountTwoFaResponse>;
  onProfileUpdated: (profile: TelegramAccountProfile) => void;
  onOpenChange: (open: boolean) => void;
} & TelegramSafetyActions) {
  const [events, setEvents] = React.useState<AccountHealthEvent[]>([]);
  const [eventsLoading, setEventsLoading] = React.useState(false);
  const [eventsError, setEventsError] = React.useState<string | null>(null);

  const loadEvents = React.useCallback(async () => {
    if (!account) return;
    setEventsLoading(true);
    setEventsError(null);
    try {
      const response = await onLoadAccountHealthEvents(account.id);
      setEvents(response);
    } catch (eventError) {
      setEventsError(errorMessage(eventError));
    } finally {
      setEventsLoading(false);
    }
  }, [account, onLoadAccountHealthEvents]);

  React.useEffect(() => {
    if (!open || !account) {
      setEvents([]);
      setEventsError(null);
      return;
    }
    void loadEvents();
    const intervalId = window.setInterval(() => void loadEvents(), 7000);
    return () => window.clearInterval(intervalId);
  }, [account, loadEvents, open]);

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="flex max-h-[calc(100dvh-2rem)] w-[min(calc(100vw-1rem),1180px)] !max-w-[1180px] flex-col gap-0 overflow-hidden p-0 sm:!max-w-[1180px]">
        <DialogHeader className="shrink-0 border-b px-5 py-4">
          <DialogTitle className="pr-10 text-xl">
            {account ? accountName(account) : "Аккаунт"}
          </DialogTitle>
          <DialogDescription className="pr-10">
            Профиль, безопасность, фоновые процессы и журнал действий аккаунта.
          </DialogDescription>
        </DialogHeader>
        <div className="min-h-0 flex-1 overflow-y-auto px-5 py-4">
          {account ? (
            <div className="grid gap-4">
              <div className="grid gap-4 xl:grid-cols-[minmax(280px,0.8fr)_minmax(0,1.2fr)]">
                <div className="rounded-lg border p-4">
                  <div className="flex items-start gap-3">
                    {profile?.photo_data_url || account.profile_photo_data_url ? (
                      <img
                        src={profile?.photo_data_url || account.profile_photo_data_url || ""}
                        alt=""
                        className="size-16 rounded-lg object-cover"
                      />
                    ) : (
                      <div className="flex size-16 items-center justify-center rounded-lg bg-muted text-lg font-semibold">
                        {initials(profile?.display_name || accountName(account))}
                      </div>
                    )}
                    <div className="min-w-0 flex-1">
                      <div className="truncate text-lg font-semibold">
                        {profile?.display_name || accountName(account)}
                      </div>
                      <div className="truncate text-sm text-muted-foreground">
                        {profile?.username ? `@${profile.username}` : accountHandle(account)}
                      </div>
                      <div className="mt-2 flex flex-wrap gap-2">
                        <AccountStatusBadge account={account} aiProfileStatus={null} />
                        <Badge variant="outline">health {account.health_score}</Badge>
                        <Badge variant="outline">{accountWarmupLabel(account)}</Badge>
                      </div>
                    </div>
                  </div>
                  {isLoading ? (
                    <div className="mt-4 flex items-center gap-2 text-sm text-muted-foreground">
                      <Loader2Icon className="size-4 animate-spin" />
                      Загружаю профиль
                    </div>
                  ) : null}
                  {error ? (
                    <Alert variant="destructive" className="mt-4">
                      <AlertTitle>Профиль не загружен</AlertTitle>
                      <AlertDescription>{error}</AlertDescription>
                    </Alert>
                  ) : null}
                </div>
                <div className="grid gap-2 text-sm sm:grid-cols-2 xl:grid-cols-3">
                  <ProfileLine label="Имя" value={profile?.first_name} />
                  <ProfileLine label="Фамилия" value={profile?.last_name} />
                  <ProfileLine
                    label="Username"
                    value={profile?.username ? `@${profile.username}` : account.username}
                  />
                  <ProfileLine label="Телефон" value={profile?.phone || account.phone} />
                  <ProfileLine label="Статус" value={statusLabel(account.status)} />
                  <ProfileLine
                    label="Ограничения"
                    value={accountRestrictionLabel(account) || "Не проверено"}
                  />
                  <ProfileLine
                    label="Проверено"
                    value={
                      account.restriction_checked_at
                        ? formatDateTimeRu(account.restriction_checked_at)
                        : "Не проверено"
                    }
                  />
                  <ProfileLine label="Происхождение" value={accountOriginLabel(account.origin)} />
                  <ProfileLine
                    label="Возраст"
                    value={
                      account.real_age_days != null
                        ? `${account.real_age_days} дней`
                        : account.claimed_age_days != null
                          ? `${account.claimed_age_days} дней заявлено`
                          : null
                    }
                  />
                  <div className="rounded-lg border p-3 sm:col-span-2 xl:col-span-3">
                    <div className="text-xs text-muted-foreground">Описание</div>
                    <div className="mt-1 break-words font-medium">
                      {profile?.about || profile?.bio || "Не указано"}
                    </div>
                  </div>
                </div>
              </div>
              <AvatarPresetInline
                account={account}
                profile={profile}
                isBusy={actionBusy === `avatar-${account.id}` || isLoading}
                onUploadAvatar={onUploadAvatar}
              />
              <AccountProfileActions
                account={account}
                accounts={accounts}
                profile={profile}
                profileLoading={isLoading}
                isCloneBusy={actionBusy === `account-profile-${account.id}`}
                isTwoFaBusy={actionBusy === `account-2fa-${account.id}`}
                onCloneAccountProfile={onCloneAccountProfile}
                onUpdateAccountTwoFa={onUpdateAccountTwoFa}
                onLoadAccountProfilePhotos={onLoadAccountProfilePhotos}
                onDeleteAccountProfilePhoto={onDeleteAccountProfilePhoto}
                onRequestAccountLoginCode={onRequestAccountLoginCode}
                onProfileUpdated={onProfileUpdated}
              />
              <TelegramSafetyPanel
                key={account.id}
                accountId={account.id}
                onLoadSafetyState={onLoadSafetyState}
                onResumeSafety={onResumeSafety}
                onAdmitSafety={onAdmitSafety}
              />
              <AccountHealthTerminal
                events={events}
                isLoading={eventsLoading}
                error={eventsError}
                onRefresh={() => void loadEvents()}
              />
            </div>
          ) : null}
        </div>
      </DialogContent>
    </Dialog>
  );
}

function AccountHealthTerminal({
  events,
  isLoading,
  error,
  onRefresh,
}: {
  events: AccountHealthEvent[];
  isLoading: boolean;
  error: string | null;
  onRefresh: () => void;
}) {
  const terminalRef = React.useRef<HTMLDivElement | null>(null);
  const rows = React.useMemo(
    () =>
      [...events]
        .sort((a, b) => Date.parse(a.created_at) - Date.parse(b.created_at))
        .slice(-220),
    [events],
  );

  React.useEffect(() => {
    const element = terminalRef.current;
    if (!element) return;
    element.scrollTop = element.scrollHeight;
  }, [rows.length]);

  return (
    <Card className="min-w-0 overflow-hidden border-border/80 bg-background shadow-sm">
      <CardHeader className="border-b bg-background">
        <div className="flex flex-wrap items-center justify-between gap-3">
          <div className="min-w-0">
            <CardTitle className="flex items-center gap-2 text-base">
              <span className="flex size-7 items-center justify-center rounded-md border bg-muted/40 text-foreground">
                <TerminalIcon className="size-4" />
              </span>
              Live terminal
              <Badge variant="outline" className="gap-1 rounded-full bg-emerald-50 text-emerald-700">
                <span className="size-2 rounded-full bg-emerald-500 shadow-[0_0_0_3px_rgba(16,185,129,0.12)]" />
                {rows.length}
              </Badge>
            </CardTitle>
            <CardDescription>
              Фоновые процессы аккаунта: вступления, профиль, сторис, проверки и ошибки.
            </CardDescription>
          </div>
          <Button type="button" variant="outline" size="sm" disabled={isLoading} onClick={onRefresh}>
            {isLoading ? <Loader2Icon className="size-4 animate-spin" /> : <RefreshCwIcon />}
            Обновить
          </Button>
        </div>
      </CardHeader>
      <CardContent className="bg-muted/20 p-3">
        {error ? <ModalError error={error} title="Не удалось загрузить журнал" /> : null}
        <div
          ref={terminalRef}
          className="h-[360px] overflow-auto rounded-lg border bg-background font-mono text-[13px] leading-6 text-foreground shadow-inner"
        >
          {rows.map((event) => (
            <div
              key={event.id}
              className="grid min-w-[760px] grid-cols-[18px_74px_90px_minmax(190px,260px)_minmax(0,1fr)] gap-x-3 border-b px-3 py-2 last:border-0 hover:bg-muted/30"
              title={event.event_type}
            >
              <span className="text-muted-foreground">&gt;</span>
              <span className="whitespace-nowrap text-muted-foreground">
                {formatTimeOnlyRu(event.created_at)}
              </span>
              <span className={cn("uppercase", campaignTerminalLevelClass(event.severity))}>
                {eventLevelLabel(event.severity)}
              </span>
              <span className="truncate text-violet-700">
                {accountEventTypeLabel(event.event_type)}
              </span>
              <span className="whitespace-pre-wrap break-normal font-medium text-foreground">
                {event.message}
              </span>
            </div>
          ))}
          {!rows.length ? (
            <div className="flex h-full items-center justify-center px-6 text-center text-sm text-muted-foreground">
              Фоновых событий пока нет. Когда аккаунт начнет вступать в чаты,
              копировать профиль, сторис или проходить проверки, строки появятся здесь.
            </div>
          ) : null}
        </div>
      </CardContent>
    </Card>
  );
}

