function AccountImportDialog({
  proxies,
  isBusy,
  onImportAccount,
  onImportSessionFileAccount,
  onImportSessionArchiveAccount,
  onStartPhoneLogin,
  onConfirmPhoneCode,
  onConfirmPhonePassword,
}: {
  proxies: Proxy[];
  isBusy: boolean;
  onImportAccount: (payload: AccountImportPayload) => Promise<void>;
  onImportSessionFileAccount: (
    payload: AccountSessionFileImportPayload,
  ) => Promise<void>;
  onImportSessionArchiveAccount: (
    payload: AccountSessionArchiveImportPayload,
  ) => Promise<void>;
  onStartPhoneLogin: (
    payload: PhoneLoginStartPayload,
  ) => Promise<PhoneLoginStartResponse>;
  onConfirmPhoneCode: (
    authToken: string,
    code: string,
  ) => Promise<PhoneLoginCompleteResponse>;
  onConfirmPhonePassword: (
    authToken: string,
    password: string,
  ) => Promise<PhoneLoginCompleteResponse>;
}) {
  const [open, setOpen] = React.useState(false);
  const [phoneToken, setPhoneToken] = React.useState<string | null>(null);
  const [phoneStep, setPhoneStep] = React.useState<
    "phone" | "code" | "password"
  >("phone");
  const [phoneMessage, setPhoneMessage] = React.useState<string | null>(null);
  const [phoneError, setPhoneError] = React.useState<string | null>(null);
  const [phoneBusy, setPhoneBusy] = React.useState(false);
  const [submitError, setSubmitError] = React.useState<string | null>(null);
  const phoneCodeInputRef = React.useRef<HTMLInputElement | null>(null);
  const phoneFlowRequestRef = React.useRef(0);

  React.useEffect(() => {
    if (phoneStep !== "code") return;
    window.setTimeout(() => phoneCodeInputRef.current?.focus(), 50);
  }, [phoneStep]);

  function resetPhoneFlow() {
    phoneFlowRequestRef.current += 1;
    setPhoneToken(null);
    setPhoneStep("phone");
    setPhoneMessage(null);
    setPhoneError(null);
    setPhoneBusy(false);
    setSubmitError(null);
  }

  async function handleFileImportSubmit(
    event: React.FormEvent<HTMLFormElement>,
  ) {
    event.preventDefault();
    setSubmitError(null);
    const formElement = event.currentTarget;
    const form = new FormData(formElement);
    const file = form.get("account_import_file");
    if (!(file instanceof File) || !file.size) {
      setSubmitError("Выберите файл аккаунта.");
      return;
    }
    const displayName = cleanOptionalText(form.get("file_display_name"));
    const proxyId = cleanOptionalText(form.get("file_proxy_id"));
    const newProxyRaw = cleanOptionalText(form.get("file_new_proxy_raw"));
    const proxyIds = form
      .getAll("file_proxy_ids")
      .map(String)
      .filter(Boolean);
    const newProxyRawText =
      cleanOptionalText(form.get("file_new_proxy_raw_text")) || newProxyRaw;
    const autoAssignFreeProxies = Boolean(form.get("file_auto_assign_free_proxies"));
    const warmupPreset = accountWarmupPresetPayload(form.get("file_warmup_trust_level"));
    const newProxyMaxAccounts = Math.max(
      1,
      Math.min(100, Number(form.get("file_new_proxy_max_accounts") || 1)),
    );
    if (!proxyId && !proxyIds.length && !newProxyRawText && !autoAssignFreeProxies) {
      setSubmitError("Выберите прокси, включите распределение свободных прокси или вставьте новый прокси строкой.");
      return;
    }

    const fileName = file.name.toLowerCase();
    try {
      if (fileName.endsWith(".session")) {
        await onImportSessionFileAccount({
          telethon_session: file,
          display_name: displayName,
          proxy_id: proxyId,
          new_proxy_raw: newProxyRaw,
          proxy_required: true,
          ...warmupPreset,
        });
      } else if (
        fileName.endsWith(".zip") ||
        fileName.endsWith(".tar") ||
        fileName.endsWith(".tgz") ||
        fileName.endsWith(".tar.gz") ||
        fileName.endsWith(".gz")
      ) {
        await onImportSessionArchiveAccount({
          sessions_archive: file,
          proxy_id: proxyId || proxyIds[0],
          proxy_ids: proxyIds,
          new_proxy_raw_text: newProxyRawText,
          new_proxy_max_accounts: newProxyMaxAccounts,
          auto_assign_free_proxies: autoAssignFreeProxies,
          proxy_required: true,
          ...warmupPreset,
        });
      } else {
        const sessionBlob = (await file.text()).trim();
        if (!sessionBlob) {
          setSubmitError("Файл пустой. Выберите .session, архив или текстовый файл с session string.");
          return;
        }
        await onImportAccount({
          session_blob: sessionBlob,
          display_name: displayName,
          proxy_id: proxyId,
          new_proxy_raw: newProxyRaw,
          proxy_required: true,
          ...warmupPreset,
        });
      }
      formElement.reset();
      resetPhoneFlow();
      setOpen(false);
    } catch (error) {
      setSubmitError(errorMessage(error));
    }
  }

  async function handlePhoneStart(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setPhoneError(null);
    const form = new FormData(event.currentTarget);
    const requestId = phoneFlowRequestRef.current + 1;
    phoneFlowRequestRef.current = requestId;
    try {
      const proxyId = cleanOptionalText(form.get("phone_proxy_id"));
      const newProxyRaw = cleanOptionalText(form.get("phone_new_proxy_raw"));
      const warmupPreset = accountWarmupPresetPayload(form.get("phone_warmup_trust_level"));
      if (!proxyId && !newProxyRaw) {
        setPhoneError("Выберите существующий прокси или вставьте новый прокси строкой.");
        return;
      }
      setPhoneBusy(true);
      setPhoneMessage("Подключаюсь к Telegram через прокси. Обычно это занимает до 40 секунд.");
      const response = await onStartPhoneLogin({
        phone: String(form.get("phone_login_phone") || "").trim(),
        display_name:
          cleanOptionalText(form.get("phone_login_display_name")) ||
          String(form.get("phone_login_phone") || "").trim(),
        proxy_id: proxyId,
        new_proxy_raw: newProxyRaw,
        new_proxy_max_accounts: 1,
        proxy_required: true,
        ...warmupPreset,
      });
      if (phoneFlowRequestRef.current !== requestId) return;
      setPhoneToken(response.auth_token);
      setPhoneStep("code");
      setPhoneMessage(`Код отправлен в Telegram на ${response.phone}. Если Telegram прислал несколько кодов, вводите последний.`);
    } catch (error) {
      if (phoneFlowRequestRef.current !== requestId) return;
      setPhoneError(errorMessage(error));
    } finally {
      if (phoneFlowRequestRef.current === requestId) {
        setPhoneBusy(false);
      }
    }
  }

  async function handlePhoneCode(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!phoneToken) return;
    setPhoneError(null);
    setPhoneBusy(true);
    const form = new FormData(event.currentTarget);
    try {
      const response = await onConfirmPhoneCode(
        phoneToken,
        String(form.get("phone_login_code") || "").trim(),
      );
      if (response.status === "password_required" && response.auth_token) {
        setPhoneToken(response.auth_token);
        setPhoneStep("password");
        setPhoneMessage(
          response.message || "Введите облачный пароль Telegram.",
        );
        return;
      }
      resetPhoneFlow();
      setOpen(false);
    } catch (error) {
      setPhoneError(errorMessage(error));
    } finally {
      setPhoneBusy(false);
    }
  }

  async function handlePhonePassword(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!phoneToken) return;
    setPhoneError(null);
    setPhoneBusy(true);
    const form = new FormData(event.currentTarget);
    try {
      await onConfirmPhonePassword(
        phoneToken,
        String(form.get("phone_login_password") || ""),
      );
      resetPhoneFlow();
      setOpen(false);
    } catch (error) {
      setPhoneError(errorMessage(error));
    } finally {
      setPhoneBusy(false);
    }
  }

  return (
    <Dialog
      open={open}
      onOpenChange={(value) => {
        setOpen(value);
        if (!value) resetPhoneFlow();
      }}
    >
      <DialogTrigger asChild>
        <Button>
          <PlusIcon />
          Добавить аккаунт
        </Button>
      </DialogTrigger>
      <DialogContent className="flex max-h-[calc(100dvh-2rem)] w-[min(calc(100vw-1.5rem),820px)] !max-w-[820px] flex-col gap-0 overflow-hidden p-0 sm:!max-w-[820px] md:w-[min(calc(100vw-4rem),820px)]">
        <DialogHeader className="shrink-0 border-b px-5 py-4">
          <DialogTitle className="pr-10 text-xl">
            Добавить Telegram аккаунт
          </DialogTitle>
          <DialogDescription className="pr-10">
            Войдите по номеру телефона или импортируйте готовый файл аккаунта.
          </DialogDescription>
        </DialogHeader>
        <div className="modal-scroll-body min-h-0 overflow-y-auto px-5 py-4">
          <ModalError error={submitError} title="Не удалось добавить аккаунт" />
          <Tabs defaultValue="phone" className="grid gap-4">
            <TabsList className="grid h-auto grid-cols-2 gap-1 rounded-lg bg-muted p-1">
              <TabsTrigger value="phone">Телефон</TabsTrigger>
              <TabsTrigger value="file">Файл</TabsTrigger>
            </TabsList>

            <TabsContent value="phone" className="mt-0">
	              <div className="rounded-lg border p-3">
	                <div className="mb-3 flex items-center gap-2 font-medium">
	                  По номеру телефона
	                  <InlineHelp tip="Номер, код из Telegram или SMS, затем 2FA пароль если он включен." />
	                </div>
                <div className="mb-3 grid gap-2 sm:grid-cols-3">
                  <PhoneLoginStepBadge active={phoneStep === "phone"} done={phoneStep !== "phone"}>
                    1. Телефон
                  </PhoneLoginStepBadge>
                  <PhoneLoginStepBadge active={phoneStep === "code"} done={phoneStep === "password"}>
                    2. Код
                  </PhoneLoginStepBadge>
                  <PhoneLoginStepBadge active={phoneStep === "password"} done={false}>
                    3. 2FA
                  </PhoneLoginStepBadge>
                </div>
                {phoneStep === "phone" && (
                  <form
                    onSubmit={(event) => void handlePhoneStart(event)}
                    className="grid gap-3"
                  >
	                    <div className="grid gap-3 md:grid-cols-[1fr_1fr_220px]">
                      <Field>
                        <HelpLabel
                          htmlFor="phone-login-phone"
                          tip="Номер Telegram аккаунта в международном формате. На него Telegram отправит код входа."
                        >
                          Телефон
                        </HelpLabel>
                        <Input
                          id="phone-login-phone"
                          name="phone_login_phone"
                          placeholder="+15550101000"
                          required
                        />
                      </Field>
	                      <Field>
	                        <FieldLabel htmlFor="phone-login-display-name">
	                          Название
                        </FieldLabel>
                        <Input
                          id="phone-login-display-name"
                          name="phone_login_display_name"
	                          placeholder="Рабочий аккаунт"
	                        />
	                      </Field>
	                      <Field>
	                        <HelpLabel
	                          htmlFor="phone-warmup-trust"
	                          tip="Можно сразу отметить личный или доверенный аккаунт: система сохранит прогрев 100/100. Реальные ограничения Telegram всё равно будут показываться отдельно."
	                        >
	                          Прогрев / доверие
	                        </HelpLabel>
	                        <NativeSelect
	                          id="phone-warmup-trust"
	                          name="phone_warmup_trust_level"
	                          defaultValue="not_started"
	                        >
	                          <NativeSelectOption value="not_started">
	                            Нужен прогрев
	                          </NativeSelectOption>
	                          <NativeSelectOption value="validated">
	                            Проверен
	                          </NativeSelectOption>
	                          <NativeSelectOption value="warming">
	                            Прогревается
	                          </NativeSelectOption>
	                          <NativeSelectOption value="trusted">
	                            Доверенный / личный
	                          </NativeSelectOption>
	                        </NativeSelect>
	                      </Field>
	                    </div>
                    <div className="grid gap-3 sm:grid-cols-2">
                      <Field>
                        <HelpLabel
                          htmlFor="phone-login-proxy"
                          tip="Прокси будет использован уже на этапе отправки кода и затем сохранится за аккаунтом."
                        >
                          Прокси
                        </HelpLabel>
                        <NativeSelect
                          id="phone-login-proxy"
                          name="phone_proxy_id"
                          className="w-full"
                        >
                          <NativeSelectOption value="">
                            Выберите прокси
                          </NativeSelectOption>
                          {proxies.map((proxy) => (
                            <NativeSelectOption key={proxy.id} value={proxy.id}>
                              {proxySelectLabel(proxy)}
                            </NativeSelectOption>
                          ))}
                        </NativeSelect>
                      </Field>
                      <Field>
                        <HelpLabel
                          htmlFor="phone-new-proxy"
                          tip="Если прокси еще не добавлен, вставьте одну строку: host:port, host:port:user:pass или socks5://user:pass@host:port."
                        >
                          Новый прокси строкой
                        </HelpLabel>
                        <Input
                          id="phone-new-proxy"
                          name="phone_new_proxy_raw"
                          placeholder="socks5://user:pass@1.2.3.4:1080"
                        />
                      </Field>
                    </div>
                    <div className="flex gap-2">
	                    <Button type="submit" disabled={phoneBusy}>
	                      {phoneBusy ? "Подключаюсь..." : "Получить код"}
                    </Button>
                      {phoneBusy && (
                        <Button
                          type="button"
                          variant="outline"
                          onClick={resetPhoneFlow}
                        >
                          Начать заново
                        </Button>
                      )}
                    </div>
                  </form>
                )}
                {phoneStep === "code" && (
                  <form
                    onSubmit={(event) => void handlePhoneCode(event)}
                    className="grid gap-3"
                  >
                    <Field>
                      <HelpLabel
                        htmlFor="phone-login-code"
                        tip="Введите код, который Telegram прислал в приложение или SMS."
                      >
                        Код Telegram
                      </HelpLabel>
                      <Input
                        ref={phoneCodeInputRef}
                        id="phone-login-code"
                        name="phone_login_code"
                        inputMode="numeric"
                        autoComplete="one-time-code"
                        required
                      />
                    </Field>
                    <div className="flex gap-2">
                      <Button
                        type="button"
                        variant="outline"
                        onClick={resetPhoneFlow}
                      >
                        Начать заново
                      </Button>
                      <Button type="submit" disabled={phoneBusy || isBusy}>
                        Подтвердить код
                      </Button>
                    </div>
                  </form>
                )}
                {phoneStep === "password" && (
                  <form
                    onSubmit={(event) => void handlePhonePassword(event)}
                    className="grid gap-3"
                  >
                    <Field>
                      <HelpLabel
                        htmlFor="phone-login-password"
                        tip="Облачный пароль Telegram, если на аккаунте включена двухфакторная защита."
                      >
                        Пароль 2FA
                      </HelpLabel>
                      <Input
                        id="phone-login-password"
                        name="phone_login_password"
                        type="password"
                        required
                      />
                    </Field>
                    <div className="flex gap-2">
                      <Button
                        type="button"
                        variant="outline"
                        onClick={resetPhoneFlow}
                      >
                        Начать заново
                      </Button>
                      <Button type="submit" disabled={phoneBusy || isBusy}>
                        Завершить вход
                      </Button>
                    </div>
                  </form>
                )}
                {phoneMessage && (
                  <p className="mt-3 rounded-md border bg-muted/40 px-3 py-2 text-sm">
                    {phoneMessage}
                  </p>
                )}
                {phoneError && (
                  <p className="mt-3 rounded-md border border-destructive/40 bg-destructive/10 px-3 py-2 text-sm text-destructive">
                    {phoneError}
                  </p>
                )}
              </div>
            </TabsContent>

            <TabsContent value="file" className="mt-0">
              <form
                onSubmit={(event) => void handleFileImportSubmit(event)}
	                className="rounded-lg border p-3"
	              >
	                <div className="mb-3 flex items-center gap-2 font-medium">
	                  Импорт готового файла
	                  <InlineHelp tip="Выберите .session, архив с .session/tdata или текстовый файл с session string. Система сама выберет нужный способ импорта." />
	                </div>
	                <FieldGroup className="gap-3">
	                  <div className="grid gap-3 md:grid-cols-[minmax(220px,1fr)_minmax(180px,0.8fr)_220px]">
	                    <Field>
	                    <HelpLabel
	                      htmlFor="account-import-file"
                      tip="Поддерживаются одиночные .session, архивы .zip/.tar/.tgz/.tar.gz с .session или tdata, а также текстовые файлы с session string."
                    >
                      Файл аккаунта
                    </HelpLabel>
                    <Input
                      id="account-import-file"
                      name="account_import_file"
	                      type="file"
	                      required
	                    />
	                    </Field>
	                    <Field>
	                      <FieldLabel htmlFor="file-display-name">Название</FieldLabel>
	                      <Input
	                        id="file-display-name"
	                        name="file_display_name"
	                        placeholder="Рабочий аккаунт"
	                      />
	                    </Field>
	                    <Field>
	                      <HelpLabel
	                        htmlFor="file-warmup-trust"
	                        tip="Можно сразу отметить личный или доверенный аккаунт: система сохранит прогрев 100/100. Реальные ограничения Telegram всё равно будут показываться отдельно."
	                      >
	                        Прогрев / доверие
	                      </HelpLabel>
	                      <NativeSelect
	                        id="file-warmup-trust"
	                        name="file_warmup_trust_level"
	                        defaultValue="not_started"
	                      >
	                        <NativeSelectOption value="not_started">
	                          Нужен прогрев
	                        </NativeSelectOption>
	                        <NativeSelectOption value="validated">
	                          Проверен
	                        </NativeSelectOption>
	                        <NativeSelectOption value="warming">
	                          Прогревается
	                        </NativeSelectOption>
	                        <NativeSelectOption value="trusted">
	                          Доверенный / личный
	                        </NativeSelectOption>
	                      </NativeSelect>
	                    </Field>
	                  </div>
                  <div className="grid gap-3 sm:grid-cols-2">
                    <Field>
                      <HelpLabel
                        htmlFor="file-proxy"
                        tip="Прокси будет привязан к импортированному аккаунту и использоваться для его Telegram-действий."
                      >
                        Прокси
                      </HelpLabel>
                      <NativeSelect
                        id="file-proxy"
                        name="file_proxy_id"
                        className="w-full"
                      >
                        <NativeSelectOption value="">
                          Выберите прокси
                        </NativeSelectOption>
                        {proxies.map((proxy) => (
                          <NativeSelectOption key={proxy.id} value={proxy.id}>
                            {proxySelectLabel(proxy)}
                          </NativeSelectOption>
                        ))}
                      </NativeSelect>
                    </Field>
                    <Field>
                      <HelpLabel
                        htmlFor="file-new-proxy"
                        tip="Если прокси еще не добавлен, вставьте одну строку: host:port, host:port:user:pass или socks5://user:pass@host:port."
                      >
                        Новый прокси строкой
                      </HelpLabel>
                      <Input
                        id="file-new-proxy"
                        name="file_new_proxy_raw"
                        placeholder="socks5://user:pass@1.2.3.4:1080"
                      />
                    </Field>
                  </div>
                  <details className="rounded-md border bg-muted/30 p-3">
                    <summary className="cursor-pointer text-sm font-medium">
                      Пачка аккаунтов и распределение прокси
                    </summary>
                    <div className="mt-3 grid gap-3">
                      <Field>
                        <HelpLabel
                          tip="Для архива можно выбрать несколько прокси: аккаунты распределятся по кругу. Для одиночного .session достаточно одного прокси выше."
                        >
                          Несколько прокси для архива
                        </HelpLabel>
                        <div className="grid max-h-40 gap-1 overflow-y-auto rounded-md border bg-background p-2">
                          {proxies.map((proxy) => (
                            <label
                              key={proxy.id}
                              className="flex min-w-0 items-center gap-2 rounded px-2 py-1.5 text-sm hover:bg-muted"
                            >
                              <Checkbox name="file_proxy_ids" value={proxy.id} />
                              <span className="min-w-0 flex-1 truncate">
                                {proxySelectLabel(proxy)}
                              </span>
                            </label>
                          ))}
                          {!proxies.length && (
                            <span className="px-2 py-2 text-sm text-muted-foreground">
                              Прокси пока нет.
                            </span>
                          )}
                        </div>
                      </Field>
                      <label className="flex items-center gap-2 rounded-md border bg-background px-3 py-2 text-sm">
                        <input
                          name="file_auto_assign_free_proxies"
                          type="checkbox"
                          className="size-4"
                        />
                        Распределить все свободные прокси автоматически
                        <InlineHelp tip="Система возьмет прокси, где количество назначенных аккаунтов меньше max_accounts." />
                      </label>
                      <Field>
                        <HelpLabel
                          htmlFor="file-new-proxies"
                          tip="Для архивов можно вставить пачку новых прокси: по одному на строку. Они будут созданы и распределены по аккаунтам."
                        >
                          Новые прокси строками
                        </HelpLabel>
                        <Textarea
                          id="file-new-proxies"
                          name="file_new_proxy_raw_text"
                          className="min-h-20"
                          placeholder={"1.2.3.4:1080:user:pass\nsocks5://user:pass@5.6.7.8:1080"}
                        />
                      </Field>
                      <Field>
                        <HelpLabel
                          htmlFor="file-new-proxy-max-accounts"
                          tip="Лимит применяется только к новым прокси, которые вы вставили строками в этом импорте."
                        >
                          Аккаунтов на новый прокси
                        </HelpLabel>
                        <Input
                          id="file-new-proxy-max-accounts"
                          name="file_new_proxy_max_accounts"
                          type="number"
                          min={1}
                          max={100}
                          defaultValue={1}
                        />
                      </Field>
                    </div>
                  </details>
	                  <Button type="submit" variant="outline" disabled={isBusy}>
                    Импортировать файл
                  </Button>
                </FieldGroup>
              </form>
            </TabsContent>
          </Tabs>
        </div>
      </DialogContent>
    </Dialog>
  );
}

function PhoneLoginStepBadge({
  active,
  done,
  children,
}: {
  active: boolean;
  done: boolean;
  children: React.ReactNode;
}) {
  return (
    <div
      className={cn(
        "rounded-md border px-3 py-2 text-sm font-medium",
        active && "border-foreground bg-background text-foreground",
        done && "border-emerald-200 bg-emerald-50 text-emerald-700",
        !active && !done && "bg-muted/30 text-muted-foreground",
      )}
    >
      {children}
    </div>
  );
}

const accountMarketModules = [
  { value: "module.neurocommenting", label: "AI-комментарии" },
  { value: "module.neurochatting", label: "AI-чат" },
  { value: "module.neurodialogs", label: "AI диалоги" },
  { value: "module.mass_reactions", label: "AI реакции" },
  { value: "module.message_broadcast", label: "Рассылки" },
  { value: "module.parsing.dialogs", label: "Парсинг" },
  { value: "module.content_factory", label: "Контент-завод" },
];

function AccountMarketScreen({
  offers,
  requests,
  accounts,
  proxies,
  actionBusy,
  isAdmin,
  onCreate,
  onUpdate,
  onStatus,
  onRequest,
  onUpdateRequest,
  onOpenAccounts,
  onOpenProxies,
}: {
  offers: AccountMarketOffer[];
  requests: AccountMarketRequest[];
  accounts: TelegramAccount[];
  proxies: Proxy[];
  actionBusy: string | null;
  isAdmin: boolean;
  onCreate: (payload: AccountMarketOfferCreatePayload) => Promise<void>;
  onUpdate: (
    offerId: string,
    payload: Partial<AccountMarketOfferCreatePayload> & { status?: string },
  ) => Promise<void>;
  onStatus: (offerId: string, status: string) => Promise<void>;
  onRequest: (offerId: string, payload: AccountMarketRequestCreatePayload) => Promise<void>;
  onUpdateRequest: (
    requestId: string,
    payload: { status?: string; admin_note?: string | null },
  ) => Promise<void>;
  onOpenAccounts: () => void;
  onOpenProxies: () => void;
}) {
  const [query, setQuery] = React.useState("");
  const [typeFilter, setTypeFilter] = React.useState("all");
  const [moduleFilter, setModuleFilter] = React.useState("all");
  const [statusFilter, setStatusFilter] = React.useState(isAdmin ? "all" : "published");
  const [sort, setSort] = React.useState("recommended");
  const visibleOffers = React.useMemo(() => {
    const normalizedQuery = query.trim().toLowerCase();
    const filtered = offers.filter((offer) => {
      if (typeFilter !== "all" && offer.offer_type !== typeFilter) return false;
      if (statusFilter !== "all" && offer.status !== statusFilter) return false;
      if (moduleFilter !== "all" && !offer.module_codes.includes(moduleFilter)) return false;
      if (!normalizedQuery) return true;
      return [
        offer.title,
        offer.description,
        offer.account_label,
        offer.proxy_label,
        offer.warmup_profile,
        offer.quality_label,
        ...offer.tags,
        ...offer.target_segments,
      ]
        .filter(Boolean)
        .join(" ")
        .toLowerCase()
        .includes(normalizedQuery);
    });
    return [...filtered].sort((left, right) => accountMarketSortValue(left, right, sort));
  }, [moduleFilter, offers, query, sort, statusFilter, typeFilter]);
  const publishedCount = offers.filter((offer) => offer.status === "published").length;
  const readyCount = offers.filter((offer) => offer.ready_to_run && offer.stock_count > 0).length;
  const bundleCount = offers.filter((offer) => offer.offer_type === "bundle").length;
  const activeRequestCount = requests.filter((request) => !["completed", "cancelled"].includes(request.status)).length;
  return (
    <div className="grid gap-4">
      <div className="flex flex-wrap items-start justify-between gap-3">
        <div>
          <h2 className="text-2xl font-semibold tracking-normal">Маркет аккаунтов</h2>
          <p className="max-w-3xl text-muted-foreground">
            Готовые Telegram-аккаунты, прокси и сборки под конкретные модули: купил, подключил, запустил без ожидания прогрева.
          </p>
        </div>
        {isAdmin ? (
          <AccountMarketOfferDialog
            accounts={accounts}
            proxies={proxies}
            busy={actionBusy === "account-market-create"}
            onSubmit={onCreate}
          />
        ) : null}
      </div>

      <div className="grid gap-3 md:grid-cols-4">
        <MetricCard title="Опубликовано" value={String(publishedCount)} />
        <MetricCard title="Готово к запуску" value={String(readyCount)} />
        <MetricCard title="Сборок account+proxy" value={String(bundleCount)} />
        <MetricCard title="Активных заявок" value={String(activeRequestCount)} />
      </div>

      <Card>
        <CardHeader>
          <div className="grid gap-3 xl:grid-cols-[minmax(240px,1fr)_170px_190px_160px_170px_auto]">
            <Input
              value={query}
              onChange={(event) => setQuery(event.currentTarget.value)}
              placeholder="Поиск: модуль, прогрев, цель, username"
            />
            <NativeSelect value={typeFilter} onChange={(event) => setTypeFilter(event.currentTarget.value)}>
              <NativeSelectOption value="all">Все типы</NativeSelectOption>
              <NativeSelectOption value="bundle">Сборки</NativeSelectOption>
              <NativeSelectOption value="account">Аккаунты</NativeSelectOption>
              <NativeSelectOption value="proxy">Прокси</NativeSelectOption>
            </NativeSelect>
            <NativeSelect value={moduleFilter} onChange={(event) => setModuleFilter(event.currentTarget.value)}>
              <NativeSelectOption value="all">Все модули</NativeSelectOption>
              {accountMarketModules.map((module) => (
                <NativeSelectOption key={module.value} value={module.value}>
                  {module.label}
                </NativeSelectOption>
              ))}
            </NativeSelect>
            <NativeSelect value={statusFilter} onChange={(event) => setStatusFilter(event.currentTarget.value)}>
              <NativeSelectOption value="all">Все статусы</NativeSelectOption>
              <NativeSelectOption value="published">В продаже</NativeSelectOption>
              {isAdmin ? (
                <>
                  <NativeSelectOption value="draft">Черновик</NativeSelectOption>
                  <NativeSelectOption value="reserved">Резерв</NativeSelectOption>
                  <NativeSelectOption value="sold">Продано</NativeSelectOption>
                  <NativeSelectOption value="archived">Архив</NativeSelectOption>
                </>
              ) : null}
            </NativeSelect>
            <NativeSelect value={sort} onChange={(event) => setSort(event.currentTarget.value)}>
              <NativeSelectOption value="recommended">Рекомендуемые</NativeSelectOption>
              <NativeSelectOption value="newest">Новые</NativeSelectOption>
              <NativeSelectOption value="price_asc">Цена ↑</NativeSelectOption>
              <NativeSelectOption value="price_desc">Цена ↓</NativeSelectOption>
              <NativeSelectOption value="warmup_desc">Прогрев</NativeSelectOption>
              <NativeSelectOption value="health_desc">Здоровье</NativeSelectOption>
            </NativeSelect>
            <Button type="button" variant="outline" onClick={() => {
              setQuery("");
              setTypeFilter("all");
              setModuleFilter("all");
              setStatusFilter(isAdmin ? "all" : "published");
              setSort("recommended");
            }}>
              Сброс
            </Button>
          </div>
        </CardHeader>
      </Card>

      {!offers.length ? (
        <Card>
          <CardContent className="py-10">
            <Empty>
              <EmptyHeader>
                <EmptyMedia>
                  <PackageCheckIcon className="size-8" />
                </EmptyMedia>
                <EmptyTitle>Маркет пока пуст</EmptyTitle>
                <EmptyDescription>
                  Добавьте аккаунты и прокси, затем опубликуйте первую готовую сборку.
                </EmptyDescription>
              </EmptyHeader>
              {isAdmin ? (
                <EmptyContent>
                  <div className="flex flex-wrap justify-center gap-2">
                    <Button variant="outline" onClick={onOpenAccounts}>Открыть аккаунты</Button>
                    <Button variant="outline" onClick={onOpenProxies}>Открыть прокси</Button>
                  </div>
                </EmptyContent>
              ) : null}
            </Empty>
          </CardContent>
        </Card>
      ) : visibleOffers.length ? (
        <div className="grid gap-3 xl:grid-cols-2">
          {visibleOffers.map((offer) => (
            <AccountMarketOfferCard
              key={offer.id}
              offer={offer}
              accounts={accounts}
              proxies={proxies}
              actionBusy={actionBusy}
              isAdmin={isAdmin && offer.can_manage}
              onUpdate={onUpdate}
              onStatus={onStatus}
              onRequest={onRequest}
            />
          ))}
        </div>
      ) : (
        <Card>
          <CardContent className="py-8 text-sm text-muted-foreground">
            По выбранным фильтрам офферов нет.
          </CardContent>
        </Card>
      )}

      {requests.length ? (
        <AccountMarketRequestsPanel
          requests={requests}
          isAdmin={isAdmin}
          actionBusy={actionBusy}
          onUpdateRequest={onUpdateRequest}
        />
      ) : null}
    </div>
  );
}

function AccountMarketOfferCard({
  offer,
  accounts,
  proxies,
  actionBusy,
  isAdmin,
  onUpdate,
  onStatus,
  onRequest,
}: {
  offer: AccountMarketOffer;
  accounts: TelegramAccount[];
  proxies: Proxy[];
  actionBusy: string | null;
  isAdmin: boolean;
  onUpdate: (
    offerId: string,
    payload: Partial<AccountMarketOfferCreatePayload> & { status?: string },
  ) => Promise<void>;
  onStatus: (offerId: string, status: string) => Promise<void>;
  onRequest: (offerId: string, payload: AccountMarketRequestCreatePayload) => Promise<void>;
}) {
  return (
    <Card className="min-w-0">
      <CardHeader>
        <div className="flex flex-wrap items-start justify-between gap-3">
          <div className="min-w-0">
            <div className="mb-2 flex flex-wrap gap-2">
              <Badge variant={offer.status === "published" ? "default" : "secondary"}>{accountMarketStatusLabel(offer.status)}</Badge>
              <Badge variant="outline">{accountMarketTypeLabel(offer.offer_type)}</Badge>
              {offer.ready_to_run ? <Badge variant="outline">готов к запуску</Badge> : null}
            </div>
            <CardTitle className="truncate text-lg">{offer.title}</CardTitle>
            <CardDescription className="line-clamp-2">{offer.description || "Описание не заполнено"}</CardDescription>
          </div>
          <div className="text-right">
            <div className="text-2xl font-semibold">{formatRub(offer.price_rub)}</div>
            <div className="text-xs text-muted-foreground">остаток {offer.stock_count}</div>
          </div>
        </div>
      </CardHeader>
      <CardContent className="grid gap-3">
        <div className="grid gap-2 md:grid-cols-2">
          <MarketInfo label="Аккаунт" value={offer.account_label || "не включен"} />
          <MarketInfo label="Прокси" value={offer.proxy_label || "не включен"} />
          <MarketInfo label="Прогрев" value={offer.warmup_profile || "-"} />
          <MarketInfo label="Гео" value={[offer.country, offer.proxy_country].filter(Boolean).join(" / ") || "-"} />
          <MarketInfo label="Warmup score" value={stringFromUnknown(offer.warmup_score, "-")} />
          <MarketInfo label="Health" value={stringFromUnknown(offer.health_score, "-")} />
        </div>
        <div className="flex flex-wrap gap-2">
          {offer.module_codes.map((module) => (
            <Badge key={module} variant="secondary">{accountMarketModuleLabel(module)}</Badge>
          ))}
          {offer.tags.map((tag) => (
            <Badge key={tag} variant="outline">{tag}</Badge>
          ))}
        </div>
        <div className="flex flex-wrap justify-between gap-2 border-t pt-3">
          <AccountMarketRequestDialog
            offer={offer}
            busy={actionBusy === `account-market-request-${offer.id}`}
            onSubmit={(payload) => onRequest(offer.id, payload)}
          />
          {isAdmin ? (
            <div className="flex flex-wrap gap-2">
              <AccountMarketOfferDialog
                accounts={accounts}
                proxies={proxies}
                offer={offer}
                busy={actionBusy === `account-market-edit-${offer.id}`}
                onSubmit={(payload) => onUpdate(offer.id, payload)}
              />
              {["draft", "published", "reserved", "sold", "archived"].map((status) => (
                <Button
                  key={status}
                  type="button"
                  size="sm"
                  variant={offer.status === status ? "default" : "outline"}
                  disabled={actionBusy === `account-market-${status}-${offer.id}`}
                  onClick={() => void onStatus(offer.id, status)}
                >
                  {accountMarketStatusLabel(status)}
                </Button>
              ))}
            </div>
          ) : null}
        </div>
      </CardContent>
    </Card>
  );
}

function AccountMarketRequestDialog({
  offer,
  busy,
  onSubmit,
}: {
  offer: AccountMarketOffer;
  busy: boolean;
  onSubmit: (payload: AccountMarketRequestCreatePayload) => Promise<void>;
}) {
  const [open, setOpen] = React.useState(false);
  const [error, setError] = React.useState<string | null>(null);
  const [provider, setProvider] = React.useState<"yookassa" | "nowpayments">("yookassa");
  async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setError(null);
    const form = new FormData(event.currentTarget);
    try {
      await onSubmit({
        contact: cleanOptionalText(form.get("contact")),
        message: cleanOptionalText(form.get("message")),
        quantity: clampNumber(form.get("quantity"), 1, 100, 1),
        module_code: cleanOptionalText(form.get("module_code")),
        provider,
      });
      setOpen(false);
    } catch (nextError) {
      setError(errorMessage(nextError));
    }
  }
  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button size="sm" disabled={offer.status !== "published" || offer.stock_count <= 0}>
          Купить
        </Button>
      </DialogTrigger>
      <DialogContent className="sm:max-w-lg">
        <form onSubmit={(event) => void handleSubmit(event)} className="grid gap-4">
          <DialogHeader>
            <DialogTitle>Оплата сборки</DialogTitle>
            <DialogDescription>{offer.title} · {formatRub(offer.price_rub)}</DialogDescription>
          </DialogHeader>
          {error && <ModalError error={error} title="Не удалось открыть оплату" />}
          <Field>
            <FieldLabel htmlFor={`market-request-contact-${offer.id}`}>Контакт для связи</FieldLabel>
            <Input id={`market-request-contact-${offer.id}`} name="contact" placeholder="@telegram или email" />
          </Field>
          <div className="grid gap-3 sm:grid-cols-2">
            <Field>
              <FieldLabel htmlFor={`market-request-quantity-${offer.id}`}>Количество</FieldLabel>
              <Input id={`market-request-quantity-${offer.id}`} name="quantity" type="number" min={1} max={100} defaultValue={1} />
            </Field>
            <Field>
              <FieldLabel htmlFor={`market-request-module-${offer.id}`}>Модуль</FieldLabel>
              <NativeSelect id={`market-request-module-${offer.id}`} name="module_code" defaultValue={offer.module_codes[0] || ""}>
                <NativeSelectOption value="">Не важно</NativeSelectOption>
                {offer.module_codes.map((module) => (
                  <NativeSelectOption key={module} value={module}>{accountMarketModuleLabel(module)}</NativeSelectOption>
                ))}
              </NativeSelect>
            </Field>
          </div>
          <Field>
            <FieldLabel htmlFor={`market-request-message-${offer.id}`}>Комментарий</FieldLabel>
            <Textarea
              id={`market-request-message-${offer.id}`}
              name="message"
              rows={4}
              placeholder="Под какую задачу нужна сборка, сроки, желаемое гео..."
            />
          </Field>
          <div className="grid gap-2">
            <FieldLabel>Способ оплаты</FieldLabel>
            <div className="grid gap-2 sm:grid-cols-2">
              <Button
                type="button"
                variant={provider === "yookassa" ? "default" : "outline"}
                onClick={() => setProvider("yookassa")}
              >
                ЮKassa / СБП
              </Button>
              <Button
                type="button"
                variant={provider === "nowpayments" ? "default" : "outline"}
                onClick={() => setProvider("nowpayments")}
              >
                Crypto invoice
              </Button>
            </div>
          </div>
          <DialogFooter>
            <Button type="button" variant="outline" onClick={() => setOpen(false)}>Отмена</Button>
            <Button type="submit" disabled={busy}>
              {busy && <Loader2Icon className="animate-spin" />}
              Перейти к оплате
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

function AccountMarketRequestsPanel({
  requests,
  isAdmin,
  actionBusy,
  onUpdateRequest,
}: {
  requests: AccountMarketRequest[];
  isAdmin: boolean;
  actionBusy: string | null;
  onUpdateRequest: (
    requestId: string,
    payload: { status?: string; admin_note?: string | null },
  ) => Promise<void>;
}) {
  return (
    <Card>
      <CardHeader>
        <CardTitle>{isAdmin ? "Заявки маркета" : "Мои заявки"}</CardTitle>
        <CardDescription>
          {isAdmin
            ? "Следите за оплатами маркета и выдачей аккаунтов после подтверждения платежа."
            : "История покупок готовых аккаунтов и сборок."}
        </CardDescription>
      </CardHeader>
      <CardContent className="overflow-x-auto">
        <Table className="min-w-[860px]">
          <TableHeader>
            <TableRow>
              <TableHead>Оффер</TableHead>
              <TableHead>Статус</TableHead>
              <TableHead>Контакт</TableHead>
              <TableHead>Кол-во</TableHead>
              <TableHead>Оплата</TableHead>
              <TableHead>Комментарий</TableHead>
              <TableHead className="text-right">Действие</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {requests.map((request) => (
              <TableRow key={request.id}>
                <TableCell>
                  <div className="font-medium">{request.offer?.title || stringFromUnknown(request.snapshot.title, "Оффер")}</div>
                  <div className="text-xs text-muted-foreground">{formatDateTimeRu(request.created_at)}</div>
                  {request.delivered_at ? (
                    <div className="mt-1 text-xs text-emerald-600">
                      Передано: {formatDateTimeRu(request.delivered_at)}
                    </div>
                  ) : null}
                </TableCell>
                <TableCell><Badge variant="outline">{accountMarketRequestStatusLabel(request.status)}</Badge></TableCell>
                <TableCell className="max-w-44 truncate">{request.contact || "-"}</TableCell>
                <TableCell>{request.quantity}</TableCell>
                <TableCell>
                  <div className="text-sm">{request.amount_rub ? formatRub(request.amount_rub) : "-"}</div>
                  <div className="text-xs text-muted-foreground">
                    {request.provider ? accountMarketProviderLabel(request.provider) : "-"}
                  </div>
                  {request.paid_at ? (
                    <div className="text-xs text-emerald-600">{formatDateTimeRu(request.paid_at)}</div>
                  ) : null}
                </TableCell>
                <TableCell className="max-w-72 truncate">{request.message || "-"}</TableCell>
                <TableCell>
                  <div className="flex justify-end gap-2">
                    {isAdmin ? (
                      ["contacted", "reserved", "completed", "cancelled"].map((status) => (
                        <Button
                          key={status}
                          type="button"
                          size="sm"
                          variant={request.status === status ? "default" : "outline"}
                          disabled={actionBusy === `account-market-request-edit-${request.id}`}
                          onClick={() => {
                            if (
                              status === "completed" &&
                              !window.confirm(
                                "Закрыть заявку и передать аккаунт/прокси в workspace покупателя?",
                              )
                            ) {
                              return;
                            }
                            void onUpdateRequest(request.id, { status });
                          }}
                        >
                          {accountMarketRequestStatusLabel(status)}
                        </Button>
                      ))
                    ) : (
                      <span className="text-sm text-muted-foreground">{request.admin_note || "Ожидает обработки"}</span>
                    )}
                  </div>
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </CardContent>
    </Card>
  );
}

function AccountMarketOfferDialog({
  accounts,
  proxies,
  offer,
  busy,
  onSubmit,
}: {
  accounts: TelegramAccount[];
  proxies: Proxy[];
  offer?: AccountMarketOffer;
  busy: boolean;
  onSubmit: (payload: AccountMarketOfferCreatePayload) => Promise<void>;
}) {
  const [open, setOpen] = React.useState(false);
  const [error, setError] = React.useState<string | null>(null);
  async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setError(null);
    const form = new FormData(event.currentTarget);
    const payload: AccountMarketOfferCreatePayload = {
      offer_type: String(form.get("offer_type") || "bundle") as "account" | "proxy" | "bundle",
      title: String(form.get("title") || "").trim(),
      description: cleanOptionalText(form.get("description")),
      account_id: cleanOptionalText(form.get("account_id")),
      proxy_id: cleanOptionalText(form.get("proxy_id")),
      price_rub: Number(form.get("price_rub") || 0),
      module_codes: form.getAll("module_codes").map(String).filter(Boolean),
      target_segments: splitTextareaValues(form.get("target_segments")),
      tags: splitTextareaValues(form.get("tags")),
      warmup_profile: cleanOptionalText(form.get("warmup_profile")),
      warmup_days: numberOrNull(form.get("warmup_days")),
      warmup_score: numberOrNull(form.get("warmup_score")),
      health_score: numberOrNull(form.get("health_score")),
      quality_label: cleanOptionalText(form.get("quality_label")),
      country: cleanOptionalText(form.get("country"))?.toUpperCase() || null,
      proxy_country: cleanOptionalText(form.get("proxy_country"))?.toUpperCase() || null,
      proxy_class: cleanOptionalText(form.get("proxy_class")),
      includes_proxy: Boolean(form.get("includes_proxy")),
      ready_to_run: Boolean(form.get("ready_to_run")),
      stock_count: Number(form.get("stock_count") || 1),
      sort_rank: Number(form.get("sort_rank") || 100),
      metadata_json: {},
    };
    if (!payload.title) {
      setError("Название обязательно.");
      return;
    }
    try {
      await onSubmit(payload);
      setOpen(false);
    } catch (nextError) {
      setError(errorMessage(nextError));
    }
  }
  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button size="sm" variant={offer ? "outline" : "default"}>
          {offer ? <Edit3Icon /> : <PlusIcon />}
          {offer ? "Изменить" : "Добавить оффер"}
        </Button>
      </DialogTrigger>
      <DialogContent className="max-h-[calc(100dvh-2rem)] w-[min(calc(100vw-1.5rem),980px)] !max-w-[980px] overflow-y-auto">
        <form onSubmit={(event) => void handleSubmit(event)} className="grid gap-4">
          <DialogHeader>
            <DialogTitle>{offer ? "Редактировать оффер" : "Новый оффер маркета"}</DialogTitle>
            <DialogDescription>Опубликуйте аккаунт, прокси или готовую сборку под конкретный модуль.</DialogDescription>
          </DialogHeader>
          {error && <ModalError error={error} title="Не удалось сохранить оффер" />}
          <div className="grid gap-3 md:grid-cols-2">
            <Field>
              <FieldLabel htmlFor="market-offer-title">Название</FieldLabel>
              <Input id="market-offer-title" name="title" defaultValue={offer?.title || ""} required />
            </Field>
            <Field>
              <FieldLabel htmlFor="market-offer-price">Цена, RUB</FieldLabel>
              <Input id="market-offer-price" name="price_rub" type="number" min={0} defaultValue={offer?.price_rub || 0} />
            </Field>
            <Field>
              <FieldLabel htmlFor="market-offer-type">Тип</FieldLabel>
              <NativeSelect id="market-offer-type" name="offer_type" defaultValue={offer?.offer_type || "bundle"}>
                <NativeSelectOption value="bundle">Аккаунт + прокси</NativeSelectOption>
                <NativeSelectOption value="account">Только аккаунт</NativeSelectOption>
                <NativeSelectOption value="proxy">Только прокси</NativeSelectOption>
              </NativeSelect>
            </Field>
            <Field>
              <FieldLabel htmlFor="market-offer-quality">Качество</FieldLabel>
              <Input id="market-offer-quality" name="quality_label" defaultValue={offer?.quality_label || ""} placeholder="trusted, premium, fresh" />
            </Field>
            <Field>
              <FieldLabel htmlFor="market-offer-account">Аккаунт из менеджера</FieldLabel>
              <NativeSelect id="market-offer-account" name="account_id" defaultValue={offer?.account_id || ""}>
                <NativeSelectOption value="">Без аккаунта</NativeSelectOption>
                {accounts.map((account) => (
                  <NativeSelectOption key={account.id} value={account.id}>
                    {accountDisplayLabel(account)}
                  </NativeSelectOption>
                ))}
              </NativeSelect>
            </Field>
            <Field>
              <FieldLabel htmlFor="market-offer-proxy">Прокси</FieldLabel>
              <NativeSelect id="market-offer-proxy" name="proxy_id" defaultValue={offer?.proxy_id || ""}>
                <NativeSelectOption value="">Без прокси</NativeSelectOption>
                {proxies.map((proxy) => (
                  <NativeSelectOption key={proxy.id} value={proxy.id}>
                    {proxy.type}://{proxy.host}:{proxy.port}
                  </NativeSelectOption>
                ))}
              </NativeSelect>
            </Field>
          </div>
          <Field>
            <FieldLabel>Модули</FieldLabel>
            <div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-3">
              {accountMarketModules.map((module) => (
                <label key={module.value} className="flex items-center gap-2 rounded-md border px-3 py-2 text-sm">
                  <Checkbox name="module_codes" value={module.value} defaultChecked={offer?.module_codes.includes(module.value)} />
                  {module.label}
                </label>
              ))}
            </div>
          </Field>
          <div className="grid gap-3 md:grid-cols-4">
            <Field>
              <FieldLabel htmlFor="market-warmup-profile">Прогрев</FieldLabel>
              <Input id="market-warmup-profile" name="warmup_profile" defaultValue={offer?.warmup_profile || ""} />
            </Field>
            <Field>
              <FieldLabel htmlFor="market-warmup-days">Дней</FieldLabel>
              <Input id="market-warmup-days" name="warmup_days" type="number" min={0} defaultValue={stringFromUnknown(offer?.warmup_days)} />
            </Field>
            <Field>
              <FieldLabel htmlFor="market-warmup-score">Warmup</FieldLabel>
              <Input id="market-warmup-score" name="warmup_score" type="number" min={0} max={100} defaultValue={stringFromUnknown(offer?.warmup_score)} />
            </Field>
            <Field>
              <FieldLabel htmlFor="market-health-score">Health</FieldLabel>
              <Input id="market-health-score" name="health_score" type="number" min={0} max={100} defaultValue={stringFromUnknown(offer?.health_score)} />
            </Field>
            <Field>
              <FieldLabel htmlFor="market-country">Гео аккаунта</FieldLabel>
              <Input id="market-country" name="country" maxLength={8} defaultValue={offer?.country || ""} placeholder="RU" />
            </Field>
            <Field>
              <FieldLabel htmlFor="market-proxy-country">Гео прокси</FieldLabel>
              <Input id="market-proxy-country" name="proxy_country" maxLength={8} defaultValue={offer?.proxy_country || ""} placeholder="DE" />
            </Field>
            <Field>
              <FieldLabel htmlFor="market-stock">Остаток</FieldLabel>
              <Input id="market-stock" name="stock_count" type="number" min={0} defaultValue={offer?.stock_count || 1} />
            </Field>
            <Field>
              <FieldLabel htmlFor="market-sort-rank">Приоритет</FieldLabel>
              <Input id="market-sort-rank" name="sort_rank" type="number" min={0} defaultValue={offer?.sort_rank || 100} />
            </Field>
          </div>
          <div className="grid gap-3 md:grid-cols-2">
            <Field>
              <FieldLabel htmlFor="market-targets">Цели</FieldLabel>
              <Textarea id="market-targets" name="target_segments" defaultValue={offer?.target_segments.join("\n") || ""} placeholder="лидогенерация&#10;комментарии по каналам" />
            </Field>
            <Field>
              <FieldLabel htmlFor="market-tags">Теги</FieldLabel>
              <Textarea id="market-tags" name="tags" defaultValue={offer?.tags.join("\n") || ""} placeholder="прогретый&#10;с прокси&#10;premium" />
            </Field>
          </div>
          <Field>
            <FieldLabel htmlFor="market-description">Описание</FieldLabel>
            <Textarea id="market-description" name="description" rows={4} defaultValue={offer?.description || ""} />
          </Field>
          <div className="flex flex-wrap gap-4">
            <label className="flex items-center gap-2 text-sm">
              <Checkbox name="includes_proxy" defaultChecked={offer?.includes_proxy ?? true} />
              Прокси включен
            </label>
            <label className="flex items-center gap-2 text-sm">
              <Checkbox name="ready_to_run" defaultChecked={offer?.ready_to_run ?? true} />
              Готов к запуску
            </label>
          </div>
          <DialogFooter>
            <Button type="button" variant="outline" onClick={() => setOpen(false)}>Отмена</Button>
            <Button type="submit" disabled={busy}>
              {busy && <Loader2Icon className="animate-spin" />}
              Сохранить
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

function MarketInfo({ label, value }: { label: string; value: React.ReactNode }) {
  return (
    <div className="min-w-0 rounded-md bg-muted/30 px-3 py-2">
      <div className="text-xs text-muted-foreground">{label}</div>
      <div className="truncate text-sm font-medium">{value}</div>
    </div>
  );
}

function accountMarketSortValue(left: AccountMarketOffer, right: AccountMarketOffer, sort: string) {
  if (sort === "newest") return new Date(right.created_at).getTime() - new Date(left.created_at).getTime();
  if (sort === "price_asc") return left.price_rub - right.price_rub;
  if (sort === "price_desc") return right.price_rub - left.price_rub;
  if (sort === "warmup_desc") return Number(right.warmup_score || 0) - Number(left.warmup_score || 0);
  if (sort === "health_desc") return Number(right.health_score || 0) - Number(left.health_score || 0);
  return (left.sort_rank || 100) - (right.sort_rank || 100);
}

function accountMarketStatusLabel(status: string) {
  const labels: Record<string, string> = {
    draft: "Черновик",
    published: "В продаже",
    reserved: "Резерв",
    sold: "Продано",
    archived: "Архив",
  };
  return labels[status] || status;
}

function accountMarketRequestStatusLabel(status: string) {
  const labels: Record<string, string> = {
    new: "Новая",
    payment_pending: "Ожидает оплату",
    paid: "Оплачена",
    contacted: "В работе",
    reserved: "Резерв",
    completed: "Закрыта",
    cancelled: "Отмена",
  };
  return labels[status] || status;
}

function accountMarketProviderLabel(provider: string) {
  const labels: Record<string, string> = {
    yookassa: "ЮKassa / СБП",
    nowpayments: "Crypto invoice",
  };
  return labels[provider] || provider;
}

function accountMarketTypeLabel(type: string) {
  const labels: Record<string, string> = {
    account: "Аккаунт",
    proxy: "Прокси",
    bundle: "Аккаунт + прокси",
  };
  return labels[type] || type;
}

function accountMarketModuleLabel(module: string) {
  return accountMarketModules.find((item) => item.value === module)?.label || module;
}

function formatRub(value: number) {
  return new Intl.NumberFormat("ru-RU", {
    style: "currency",
    currency: "RUB",
    maximumFractionDigits: 0,
  }).format(value || 0);
}

function ProxiesScreen({
  proxies,
  proxyUsage,
  actionBusy,
  onCreateProxy,
  onUpdateProxy,
  onBulkCheckProxies,
  onCheckProxy,
  onDeleteProxy,
  onBulkDeleteProxies,
  onDetachOverloadedProxyAccounts,
}: {
  proxies: Proxy[];
  proxyUsage: Record<string, ProxyUsage>;
  actionBusy: string | null;
  onCreateProxy: (payload: ProxyCreatePayload) => Promise<void>;
  onUpdateProxy: (proxyId: string, payload: ProxyUpdatePayload) => Promise<void>;
  onBulkCheckProxies: (
    payload: ProxyBulkCheckPayload,
  ) => Promise<ProxyBulkCheckResponse>;
  onCheckProxy: (proxyId: string) => Promise<void>;
  onDeleteProxy: (proxyId: string) => Promise<void>;
  onBulkDeleteProxies: (proxyIds: string[]) => Promise<void>;
  onDetachOverloadedProxyAccounts: (proxyIds: string[]) => Promise<void>;
}) {
  const [rawText, setRawText] = React.useState("");
  const [defaultType, setDefaultType] = React.useState<"http" | "socks5">(
    "socks5",
  );
  const [provider, setProvider] = React.useState("");
  const [proxyClass, setProxyClass] = React.useState("static_residential");
  const [exclusivity, setExclusivity] = React.useState("dedicated");
  const [maxAccounts, setMaxAccounts] = React.useState(1);
  const [note, setNote] = React.useState("");
  const [bulkError, setBulkError] = React.useState<string | null>(null);
  const [bulkResult, setBulkResult] =
    React.useState<ProxyBulkCheckResponse | null>(null);
  const [bulkResultSignature, setBulkResultSignature] = React.useState("");
  const [selectedProxyIds, setSelectedProxyIds] = React.useState<string[]>([]);
  const [showOverloadedOnly, setShowOverloadedOnly] = React.useState(false);
  const isChecking = actionBusy === "proxy-bulk-check";
  const isImporting = actionBusy === "proxy-bulk-import";
  const isBulkDeleting = actionBusy === "proxy-bulk-delete";
  const isDetachingOverload = actionBusy === "proxy-detach-overloaded";
  const rawSignature = React.useMemo(
    () => proxyBulkSignature(rawText),
    [rawText],
  );
  const hasCheckedCurrentInput = Boolean(
    bulkResult && bulkResultSignature === rawSignature && bulkResult.valid > 0,
  );
  const overloadedProxyIds = React.useMemo(
    () =>
      proxies
        .filter((proxy) => proxyIsOverloaded(proxy, proxyUsage[proxy.id]))
        .map((proxy) => proxy.id),
    [proxies, proxyUsage],
  );
  const visibleProxies = React.useMemo(
    () =>
      showOverloadedOnly
        ? proxies.filter((proxy) => overloadedProxyIds.includes(proxy.id))
        : proxies,
    [overloadedProxyIds, proxies, showOverloadedOnly],
  );
  const visibleProxyIds = React.useMemo(
    () => visibleProxies.map((proxy) => proxy.id),
    [visibleProxies],
  );
  const selectedProxySet = React.useMemo(
    () => new Set(selectedProxyIds),
    [selectedProxyIds],
  );
  const allVisibleSelected =
    visibleProxyIds.length > 0 &&
    visibleProxyIds.every((proxyId) => selectedProxySet.has(proxyId));
  const someVisibleSelected = visibleProxyIds.some((proxyId) =>
    selectedProxySet.has(proxyId),
  );
  const selectedOverloadedProxyIds = selectedProxyIds.filter((proxyId) =>
    overloadedProxyIds.includes(proxyId),
  );

  React.useEffect(() => {
    const visibleIds = new Set(proxies.map((proxy) => proxy.id));
    setSelectedProxyIds((current) =>
      current.filter((proxyId) => visibleIds.has(proxyId)),
    );
  }, [proxies]);

  function toggleProxySelection(proxyId: string, checked: boolean) {
    setSelectedProxyIds((current) => {
      if (checked) {
        return current.includes(proxyId) ? current : [...current, proxyId];
      }
      return current.filter((item) => item !== proxyId);
    });
  }

  function toggleAllVisibleProxies(checked: boolean) {
    setSelectedProxyIds(checked ? visibleProxyIds : []);
  }

  async function deleteSelectedProxies() {
    await onBulkDeleteProxies(selectedProxyIds);
    setSelectedProxyIds([]);
  }

  async function detachSelectedOverloadedProxyAccounts() {
    await onDetachOverloadedProxyAccounts(selectedOverloadedProxyIds);
    setSelectedProxyIds([]);
  }

  async function handleFile(event: React.ChangeEvent<HTMLInputElement>) {
    const file = event.currentTarget.files?.[0];
    if (!file) return;
    setBulkError(null);
    try {
      const content = await file.text();
      setRawText((current) =>
        [current.trim(), content.trim()].filter(Boolean).join("\n"),
      );
    } catch {
      setBulkError("Не удалось прочитать файл с прокси.");
    } finally {
      event.currentTarget.value = "";
    }
  }

  async function submitBulk(saveValid: boolean) {
    setBulkError(null);
    const signature = proxyBulkSignature(rawText);
    setBulkResult({
      total: 0,
      parsed: 0,
      valid: 0,
      saved: 0,
      items: parseProxyBulkPreview(rawText, defaultType),
    });
    setBulkResultSignature(signature);
    try {
      const result = await onBulkCheckProxies({
        raw_text: rawText,
        default_type: defaultType,
        provider: cleanOptionalText(provider),
        proxy_class: cleanOptionalText(proxyClass),
        exclusivity: cleanOptionalText(exclusivity),
        max_accounts: maxAccounts,
        note: cleanOptionalText(note),
        save_valid: saveValid,
        check_telegram: true,
      });
      setBulkResult(result);
      setBulkResultSignature(signature);
    } catch (error) {
      setBulkError(errorMessage(error));
    }
  }

  async function importSingleProxy(item: ProxyBulkCheckItem, index: number) {
    if (!item.raw || item.status !== "succeeded" || item.proxy_id) return;
    setBulkError(null);
    setBulkResult((current) => {
      if (!current) return current;
      return {
        ...current,
        items: current.items.map((candidate, candidateIndex) =>
          candidateIndex === index
            ? { ...candidate, status: "saving" }
            : candidate,
        ),
      };
    });
    try {
      const result = await onBulkCheckProxies({
        raw_text: item.raw,
        default_type: defaultType,
        provider: cleanOptionalText(provider),
        proxy_class: cleanOptionalText(proxyClass),
        exclusivity: cleanOptionalText(exclusivity),
        max_accounts: maxAccounts,
        note: cleanOptionalText(note),
        save_valid: true,
        check_telegram: true,
      });
      const savedItem = result.items[0];
      setBulkResult((current) => {
        if (!current) return result;
        return {
          ...current,
          saved: current.saved + result.saved,
          items: current.items.map((candidate, candidateIndex) =>
            candidateIndex === index && savedItem ? savedItem : candidate,
          ),
        };
      });
    } catch (error) {
      setBulkError(errorMessage(error));
      setBulkResult((current) => {
        if (!current) return current;
        return {
          ...current,
          items: current.items.map((candidate, candidateIndex) =>
            candidateIndex === index
              ? { ...candidate, status: "succeeded" }
              : candidate,
          ),
        };
      });
    }
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle>Прокси</CardTitle>
        <CardDescription>
          Bulk-загрузка, проверка Telegram-доступности и привязка к аккаунтам.
        </CardDescription>
        <CardAction>
          <ProxyCreateDialog
            isBusy={actionBusy === "proxy-create"}
            onCreateProxy={onCreateProxy}
          />
        </CardAction>
      </CardHeader>
      <CardContent className="space-y-6">
        <div className="grid items-start gap-4 rounded-md border p-4 lg:grid-cols-[minmax(0,1fr)_360px]">
          <div className="flex min-w-0 flex-col gap-3">
            <div>
              <div className="font-medium">Загрузка и проверка прокси</div>
              <div className="text-sm text-muted-foreground">
                Вставь список строками, через запятую или загрузи .txt файл.
                Поддерживаются `host:port:user:pass`, `host:port`,
                `socks5://user:pass@host:port`.
              </div>
            </div>
            <Textarea
              value={rawText}
              onChange={(event) => setRawText(event.target.value)}
              className="min-h-[22rem] resize-y font-mono text-sm"
              placeholder={
                "192.0.2.10:5803:login:password\nsocks5://login:password@198.51.100.20:6370"
              }
            />
            <ModalError error={bulkError} title="Не удалось проверить прокси" />
          </div>
          <div className="flex min-w-0 flex-col gap-3">
            <Field>
              <FieldLabel htmlFor="proxy-bulk-file">Файл с прокси</FieldLabel>
              <Input
                id="proxy-bulk-file"
                type="file"
                accept=".txt,.csv"
                onChange={handleFile}
              />
            </Field>
            <div className="grid grid-cols-2 gap-3">
              <Field>
                <FieldLabel htmlFor="proxy-bulk-type">
                  Тип по умолчанию
                </FieldLabel>
                <NativeSelect
                  id="proxy-bulk-type"
                  value={defaultType}
                  onChange={(event) =>
                    setDefaultType(event.target.value as "http" | "socks5")
                  }
                >
                  <NativeSelectOption value="socks5">SOCKS5</NativeSelectOption>
                  <NativeSelectOption value="http">HTTP</NativeSelectOption>
                </NativeSelect>
              </Field>
              <Field>
                <FieldLabel htmlFor="proxy-bulk-limit">
                  Лимит аккаунтов
                </FieldLabel>
                <Input
                  id="proxy-bulk-limit"
                  type="number"
                  min={1}
                  max={100}
                  value={maxAccounts}
                  onChange={(event) =>
                    setMaxAccounts(Number(event.target.value || 1))
                  }
                />
              </Field>
            </div>
            <Field>
              <FieldLabel htmlFor="proxy-bulk-provider">Провайдер</FieldLabel>
              <Input
                id="proxy-bulk-provider"
                value={provider}
                placeholder="Webshare"
                onChange={(event) => setProvider(event.target.value)}
              />
            </Field>
            <div className="grid grid-cols-2 gap-3">
              <Field>
                <FieldLabel htmlFor="proxy-bulk-class">Класс</FieldLabel>
                <NativeSelect
                  id="proxy-bulk-class"
                  value={proxyClass}
                  onChange={(event) => setProxyClass(event.target.value)}
                >
                  <NativeSelectOption value="static_residential">
                    Статический residential
                  </NativeSelectOption>
                  <NativeSelectOption value="isp">ISP</NativeSelectOption>
                  <NativeSelectOption value="datacenter">
                    Датацентр
                  </NativeSelectOption>
                  <NativeSelectOption value="mobile">Мобильный</NativeSelectOption>
                  <NativeSelectOption value="rotating_residential">
                    Ротационный residential
                  </NativeSelectOption>
                  <NativeSelectOption value="unknown">Не указан</NativeSelectOption>
                </NativeSelect>
              </Field>
              <Field>
                <FieldLabel htmlFor="proxy-bulk-exclusivity">
                  Эксклюзивность
                </FieldLabel>
                <NativeSelect
                  id="proxy-bulk-exclusivity"
                  value={exclusivity}
                  onChange={(event) => setExclusivity(event.target.value)}
                >
                  <NativeSelectOption value="dedicated">Выделенный</NativeSelectOption>
                  <NativeSelectOption value="private_1_2">Приватный 1-2</NativeSelectOption>
                  <NativeSelectOption value="shared">Общий</NativeSelectOption>
                  <NativeSelectOption value="unknown">Не указана</NativeSelectOption>
                </NativeSelect>
              </Field>
            </div>
            <Field>
              <FieldLabel htmlFor="proxy-bulk-note">Заметка</FieldLabel>
              <Input
                id="proxy-bulk-note"
                value={note}
                placeholder="US номера, май 2026"
                onChange={(event) => setNote(event.target.value)}
              />
            </Field>
            <div className="grid gap-2">
              <Button
                type="button"
                variant="outline"
                disabled={!rawText.trim() || isChecking || isImporting}
                onClick={() => void submitBulk(false)}
              >
                <RefreshCwIcon />
                Проверить
              </Button>
              <Button
                type="button"
                disabled={!rawText.trim() || isChecking || isImporting}
                onClick={() => void submitBulk(true)}
              >
                <UploadIcon />
                {hasCheckedCurrentInput
                  ? "Загрузить проверенные"
                  : "Проверить и загрузить"}
              </Button>
            </div>
          </div>
        </div>
        {bulkResult && (
          <div className="rounded-md border">
            <div className="flex flex-wrap items-center justify-between gap-3 border-b p-4">
              <div>
                <div className="font-medium">Результаты проверки прокси</div>
                <div className="text-sm text-muted-foreground">
                  Распознано {bulkResult.parsed || bulkResult.items.length} ·
                  валидных {bulkResult.valid} · загружено {bulkResult.saved}
                </div>
              </div>
            </div>
            <div className="max-h-[420px] overflow-auto">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Прокси</TableHead>
                    <TableHead>Статус</TableHead>
                    <TableHead>Доступен для Telegram</TableHead>
                    <TableHead>Задержка</TableHead>
                    <TableHead>Гео</TableHead>
                    <TableHead className="text-right">Действие</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {bulkResult.items.map((item, index) => (
                    <TableRow key={`${item.raw}-${index}`}>
                      <TableCell className="font-mono text-sm">
                        {item.host && item.port
                          ? `${item.type}://${item.host}:${item.port}`
                          : item.raw}
                      </TableCell>
                      <TableCell>
                        <ProxyCheckStatusBadge status={item.status} />
                      </TableCell>
                      <TableCell>
                        {proxyTelegramAvailabilityLabel(item)}
                      </TableCell>
                      <TableCell>
                        {item.telegram_latency_ms || item.latency_ms
                          ? `${item.telegram_latency_ms || item.latency_ms} ms`
                          : "—"}
                      </TableCell>
                      <TableCell>
                        <GeoLabel country={item.country} />
                      </TableCell>
                      <TableCell className="text-right">
                        {item.error_message && item.status !== "checking" ? (
                          <span className="text-sm text-muted-foreground">
                            {item.error_message}
                          </span>
                        ) : (
                          <Button
                            type="button"
                            size="sm"
                            variant={item.proxy_id ? "outline" : "default"}
                            disabled={
                              item.status !== "succeeded" ||
                              Boolean(item.proxy_id) ||
                              isChecking ||
                              isImporting
                            }
                            onClick={() => void importSingleProxy(item, index)}
                          >
                            {item.status === "saving" ? (
                              <Loader2Icon className="animate-spin" />
                            ) : (
                              <UploadIcon />
                            )}
                            {item.proxy_id ? "Загружен" : "Загрузить"}
                          </Button>
                        )}
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          </div>
        )}
        {proxies.length ? (
          <div className="space-y-3">
            <div className="flex flex-wrap items-center justify-between gap-2">
              <div className="text-sm text-muted-foreground">
                Выбрано: {selectedProxyIds.length}
                {overloadedProxyIds.length
                  ? ` · перегружено: ${overloadedProxyIds.length}`
                  : ""}
              </div>
              <div className="flex flex-wrap items-center gap-2">
                <Button
                  type="button"
                  variant={showOverloadedOnly ? "default" : "outline"}
                  size="sm"
                  disabled={!overloadedProxyIds.length}
                  onClick={() => {
                    setShowOverloadedOnly((value) => !value);
                    setSelectedProxyIds([]);
                  }}
                >
                  <ShieldCheckIcon />
                  Только перегруз
                </Button>
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  disabled={!overloadedProxyIds.length}
                  onClick={() => setSelectedProxyIds(overloadedProxyIds)}
                >
                  Выбрать перегруз
                </Button>
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  disabled={!selectedOverloadedProxyIds.length || isDetachingOverload}
                  onClick={() => void detachSelectedOverloadedProxyAccounts()}
                >
                  {isDetachingOverload ? (
                    <Loader2Icon className="size-4 animate-spin" />
                  ) : (
                    <NetworkIcon />
                  )}
                  Снять лишние аккаунты
                  {selectedOverloadedProxyIds.length
                    ? ` · ${selectedOverloadedProxyIds.length}`
                    : ""}
                </Button>
                <Button
                  type="button"
                  variant="destructive"
                  size="sm"
                  disabled={!selectedProxyIds.length || isBulkDeleting}
                  onClick={() => void deleteSelectedProxies()}
                >
                  {isBulkDeleting ? (
                    <Loader2Icon className="size-4 animate-spin" />
                  ) : (
                    <Trash2Icon />
                  )}
                  Удалить выбранные
                  {selectedProxyIds.length ? ` · ${selectedProxyIds.length}` : ""}
                </Button>
              </div>
            </div>
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead className="w-10">
                    <Checkbox
                      checked={
                        allVisibleSelected
                          ? true
                          : someVisibleSelected
                            ? "indeterminate"
                            : false
                      }
                      aria-label="Выбрать все прокси"
                      onCheckedChange={(checked) =>
                        toggleAllVisibleProxies(checked === true)
                      }
                    />
                  </TableHead>
                  <TableHead className="w-[40%]">Адрес</TableHead>
                  <TableHead className="w-20">Гео</TableHead>
                  <TableHead className="w-[230px]">Статус</TableHead>
                  <TableHead className="w-[150px]">Задержка</TableHead>
                  <TableHead className="w-[160px]">Использование</TableHead>
                  <TableHead className="w-[170px] text-right">Действия</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {visibleProxies.map((proxy) => {
                  const usage = proxyUsage[proxy.id];
                  const selected = selectedProxySet.has(proxy.id);
                  const overloaded = proxyIsOverloaded(proxy, usage);
                  return (
                    <ProxyEditDialog
                      key={proxy.id}
                      proxy={proxy}
                      isBusy={actionBusy === `proxy-edit-${proxy.id}`}
                      onUpdateProxy={(payload) => onUpdateProxy(proxy.id, payload)}
                      trigger={
                        <TableRow
                          data-state={selected ? "selected" : undefined}
                          className="cursor-pointer"
                        >
                          <TableCell>
                            <span onClick={(event) => event.stopPropagation()}>
                              <Checkbox
                                checked={selected}
                                aria-label={`Выбрать прокси ${proxyAddressLabel(proxy)}`}
                                onCheckedChange={(checked) =>
                                  toggleProxySelection(proxy.id, checked === true)
                                }
                              />
                            </span>
                          </TableCell>
                          <TableCell className="max-w-[520px]">
                            <div className="font-medium">
                              {proxyAddressLabel(proxy)}
                            </div>
                            <div className="text-sm text-muted-foreground">
                              {[proxy.provider, proxy.note].filter(Boolean).join(" / ") ||
                                "Без заметки"}
                            </div>
                            <div className="mt-1 flex flex-wrap gap-1">
                              <Badge variant="outline">
                                {proxyClassLabel(proxy.proxy_class)}
                              </Badge>
                              <Badge variant="outline">
                                {proxyExclusivityLabel(proxy.exclusivity)}
                              </Badge>
                            </div>
                          </TableCell>
                          <TableCell>
                            <div className="grid gap-1">
                              <GeoLabel country={proxy.country} />
                              {proxy.city_state ? (
                                <span className="text-xs text-muted-foreground">
                                  {proxy.city_state}
                                </span>
                              ) : null}
                            </div>
                          </TableCell>
                          <TableCell>
                            <div className="flex flex-wrap gap-1">
                              <Badge variant="outline">
                                {statusLabel(proxy.status)}
                              </Badge>
                              <ProxyConnectivityBadge status={proxy.telegram_connectivity_status} />
                            </div>
                          </TableCell>
                          <TableCell className="text-sm">
                            {proxyPingText(proxy)}
                          </TableCell>
                          <TableCell className="text-sm text-muted-foreground">
                            <div className="flex flex-wrap items-center gap-2">
                              <span>
                                {usage
                                  ? `${usage.account_count}/${proxy.max_accounts} аккаунтов`
                                  : proxyAccountUsageText(proxy)}
                              </span>
                              {overloaded ? (
                                <Badge
                                  variant="outline"
                                  className="border-red-200 bg-red-50 text-red-700"
                                >
                                  Перегруз
                                </Badge>
                              ) : null}
                            </div>
                          </TableCell>
                          <TableCell className="w-[170px] text-right">
                            <div
                              className="flex items-center justify-end gap-1"
                              onClick={(event) => event.stopPropagation()}
                            >
                              <Button
                                variant="outline"
                                size="sm"
                                className="shrink-0"
                                disabled={actionBusy === `proxy-check-${proxy.id}`}
                                onClick={() => void onCheckProxy(proxy.id)}
                              >
                                <RefreshCwIcon />
                                Проверить
                              </Button>
                              <Button
                                variant="ghost"
                                size="icon"
                                className="size-8 shrink-0"
                                disabled={actionBusy === `proxy-delete-${proxy.id}`}
                                onClick={() => void onDeleteProxy(proxy.id)}
                              >
                                <Trash2Icon />
                              </Button>
                            </div>
                          </TableCell>
                        </TableRow>
                      }
                    />
                  );
                })}
              </TableBody>
            </Table>
          </div>
        ) : (
          <EmptyState
            icon={<NetworkIcon />}
            title="Прокси еще не добавлены"
            description="Создайте HTTP или SOCKS5 профиль для дальнейшей привязки."
          />
        )}
      </CardContent>
    </Card>
  );
}

function proxyBulkSignature(rawText: string) {
  return rawText
    .replace(/\r/g, "\n")
    .split(/[\n,;]+/)
    .map((line) => line.trim())
    .filter(Boolean)
    .join("\n");
}

function parseProxyBulkPreview(
  rawText: string,
  defaultType: "http" | "socks5",
) {
  const items = proxyBulkSignature(rawText)
    .split("\n")
    .filter(Boolean)
    .slice(0, 1000)
    .map((raw): ProxyBulkCheckItem => {
      const parsed = parseProxyPreviewLine(raw, defaultType);
      return {
        raw,
        type: parsed.type,
        host: parsed.host,
        port: parsed.port,
        username: parsed.username,
        country: null,
        status: parsed.host && parsed.port ? "checking" : "invalid",
        latency_ms: null,
        telegram_ok: null,
        telegram_latency_ms: null,
        error_code: parsed.host && parsed.port ? null : "PROXY_PARSE_FAILED",
        error_message:
          parsed.host && parsed.port ? null : "Не удалось распознать прокси",
        proxy_id: null,
      };
    });
  return items;
}

function parseProxyPreviewLine(raw: string, defaultType: "http" | "socks5") {
  let value = raw.trim();
  let type: "http" | "socks5" | null = defaultType;
  let username: string | null = null;
  let host: string | null = null;
  let port: number | null = null;

  if (value.includes("://")) {
    try {
      const parsed = new URL(value);
      type = parsed.protocol.replace(":", "") as "http" | "socks5";
      host = parsed.hostname || null;
      port = parsed.port ? Number(parsed.port) : null;
      username = parsed.username || null;
    } catch {
      type = null;
    }
  } else {
    value = value.replace(/^@/, "");
    const parts = value.split(":");
    if (parts.length === 2 || parts.length >= 4) {
      host = parts[0] || null;
      port = Number(parts[1]);
      username = parts[2] || null;
    }
  }

  if (!Number.isFinite(port || NaN)) {
    port = null;
  }
  return { type, host, port, username };
}

function ProxyCheckStatusBadge({ status }: { status: string }) {
  if (status === "checking" || status === "saving") {
    return (
      <Badge variant="outline" className="gap-1">
        <Loader2Icon className="size-3 animate-spin" />
        {status === "saving" ? "Загружаем" : "Проверяем"}
      </Badge>
    );
  }
  return (
    <Badge variant={status === "succeeded" ? "default" : "destructive"}>
      {status === "succeeded" ? "Работает" : "Ошибка"}
    </Badge>
  );
}

function proxyTelegramAvailabilityLabel(item: ProxyBulkCheckItem) {
  if (item.status === "checking" || item.status === "saving")
    return "Проверяем";
  if (item.telegram_ok === true) {
    const telegramLatency = item.telegram_latency_ms || item.latency_ms || 0;
    if (telegramLatency >= 1500) {
      return (
        <Badge
          variant="outline"
          className="border-amber-200 bg-amber-50 text-amber-700"
        >
          Медленно
        </Badge>
      );
    }
    return "Да";
  }
  if (item.telegram_ok === false) return "Нет";
  return "—";
}

