function isSourceChecking(source: Source) {
  return source.access_status === "pending_check";
}

function buildSourceSafetySummary(sources: Source[]): SourceSafetySummary {
  const summary: SourceSafetySummary = {
    total: sources.length,
    safe: 0,
    medium: 0,
    high: 0,
    critical: 0,
    unknown: 0,
    invalid: 0,
    archived: 0,
    blacklisted: 0,
    comments_closed: 0,
    private: 0,
    join_request: 0,
    write_forbidden: 0,
    not_found: 0,
    not_channel: 0,
  };
  for (const source of sources) {
    const risk = sourceRiskLevel(source);
    summary[risk] += 1;
    if (source.access_status === "archived") summary.archived += 1;
    if (sourceIsBlacklisted(source)) summary.blacklisted += 1;
    if (source.access_status.startsWith("invalid") || source.source_metadata?.invalid === true) {
      summary.invalid += 1;
    }
    const reason = stringFromUnknown(source.source_metadata?.invalid_reason, "");
    if (reason === "source_comments_not_available" || source.access_status === "invalid_comments_closed") {
      summary.comments_closed += 1;
    } else if (reason === "source_not_accessible" || source.access_status === "invalid_private") {
      summary.private += 1;
    } else if (reason === "discussion_join_approval_required" || source.access_status === "invalid_join_request") {
      summary.join_request += 1;
    } else if (reason === "account_cannot_write_comments" || source.access_status === "invalid_write_forbidden") {
      summary.write_forbidden += 1;
    } else if (reason === "source_not_found" || source.access_status === "invalid_not_found") {
      summary.not_found += 1;
    } else if (reason === "source_not_channel" || source.access_status === "invalid_not_channel") {
      summary.not_channel += 1;
    }
  }
  return summary;
}

function sourceRiskLevel(source: Source): "safe" | "medium" | "high" | "critical" | "unknown" {
  const apiRisk = stringFromUnknown(source.source_risk_level, "");
  if (apiRisk === "low") return "safe";
  if (["medium", "high", "critical", "unknown"].includes(apiRisk)) {
    return apiRisk as "medium" | "high" | "critical" | "unknown";
  }
  if (sourceIsBlacklisted(source)) return "critical";
  if (isInvalidSourceForQuickCleanup(source)) return "critical";
  if (source.access_status === "pending_check" || source.access_status === "unknown") return "unknown";
  if (source.access_status === "failed") return "high";
  if (source.type === "channel" && source.comments_enabled) return "safe";
  return "medium";
}

function SourceSafetySummaryStrip({ summary }: { summary: SourceSafetySummary }) {
  return (
    <div className="grid gap-2 rounded-md border bg-muted/20 p-3 sm:grid-cols-2 lg:grid-cols-6">
      <SourceSafetyMetric
        label="Готовы"
        value={summary.safe}
        tone="ok"
        tip="Источники доступны, комментарии открыты, явных блокеров нет."
      />
      <SourceSafetyMetric
        label="Не проверены"
        value={summary.unknown}
        tone="warn"
        tip="Статус источника пока неясен. Откройте базу каналов и запустите проверку комментариев."
      />
      <SourceSafetyMetric
        label="Невалидны"
        value={summary.invalid}
        tone="danger"
        tip="Источник недоступен, заблокирован, архивирован или не подходит для комментариев."
      />
      <SourceSafetyMetric
        label="Черный список"
        value={summary.blacklisted}
        tone="danger"
        tip="Эти источники исключены из импортов, селекторов и запусков кампаний."
      />
      <SourceSafetyMetric
        label="Комментарии закрыты"
        value={summary.comments_closed}
        tone="danger"
        tip="В этих каналах нельзя оставить комментарий. Уберите их из кампаний или замените источники."
      />
      <SourceSafetyMetric
        label="Приватные / заявка"
        value={summary.join_request + summary.private}
        tone="danger"
        tip="Канал приватный или требует вступления по заявке. Сначала дайте аккаунтам доступ или уберите источник."
      />
    </div>
  );
}

function SourceSafetyMetric({
  label,
  value,
  tone,
  tip,
  active = false,
  onClick,
}: {
  label: string;
  value: number;
  tone: "ok" | "warn" | "danger";
  tip?: string;
  active?: boolean;
  onClick?: () => void;
}) {
  const labelNode = (
    <span className="min-w-0 truncate text-xs font-medium leading-tight text-muted-foreground">
      {label}
    </span>
  );
  const content = (
    <div className="flex min-w-0 items-center gap-1.5">
      <div
        className={cn(
          "shrink-0 text-base font-semibold leading-none tabular-nums",
          tone === "ok" && "text-emerald-700",
          tone === "warn" && "text-amber-700",
          tone === "danger" && "text-red-700",
        )}
      >
        {value}
      </div>
      {tip ? (
        <Tooltip>
          <TooltipTrigger asChild>
            <span
              className="inline-flex min-w-0 cursor-help"
              onClick={(event) => event.stopPropagation()}
            >
              {labelNode}
            </span>
          </TooltipTrigger>
          <TooltipContent className="max-w-80 whitespace-pre-wrap text-left">
            {tip}
          </TooltipContent>
        </Tooltip>
      ) : (
        labelNode
      )}
    </div>
  );
  if (onClick) {
    return (
      <button
        type="button"
        className={cn(
          "rounded-md border px-2.5 py-1.5 text-left transition hover:bg-muted/50",
          active
            ? "border-foreground bg-background shadow-sm"
            : "border-border/60 bg-background/70",
        )}
        onClick={onClick}
      >
        {content}
      </button>
    );
  }
  return (
    <div className="rounded-md border border-border/60 bg-background/70 px-2.5 py-1.5">
      {content}
    </div>
  );
}

function sourceNeedsCommentCheck(source: Source) {
  return !sourceIsBlacklisted(source) && !["available", "archived"].includes(source.access_status);
}

function isInvalidSourceForQuickCleanup(source: Source) {
  if (isSourceChecking(source)) return false;
  if (sourceIsBlacklisted(source)) return false;
  if (sourceIsManuallyAvailableForContent(source)) return false;
  if (
    ["failed", "blocked", "archived"].includes(source.access_status) ||
    source.access_status.startsWith("invalid")
  )
    return true;
  return source.type === "channel" && source.comments_enabled === false;
}

function sourceIsManuallyAvailableForContent(source: Source) {
  return (
    source.access_status === "available" &&
    source.comments_enabled === false &&
    source.source_metadata?.manual_status_override === true
  );
}

function SourceCommentsBadge({ source }: { source: Source }) {
  if (source.comments_enabled) {
    return <Badge variant="default">Комментарии открыты</Badge>;
  }
  if (sourceIsManuallyAvailableForContent(source)) {
    return <Badge variant="secondary">Для контента</Badge>;
  }
  if (isSourceChecking(source)) {
    return <Badge variant="outline">Проверяется</Badge>;
  }
  if (source.access_status.startsWith("invalid")) {
    return <Badge variant="destructive">{sourceInvalidLabel(source)}</Badge>;
  }
  if (source.type === "channel") {
    return <Badge variant="destructive">Комментарии закрыты</Badge>;
  }
  return <Badge variant="outline">Не подтверждены</Badge>;
}

function SourceSafetyBadge({ source }: { source: Source }) {
  const risk = sourceRiskLevel(source);
  if (sourceIsBlacklisted(source)) {
    return <Badge variant="destructive">Черный список</Badge>;
  }
  if (source.safe_for_new_accounts) {
    return <Badge variant="default">Безопасно для новых</Badge>;
  }
  if (source.safe_for_trusted_accounts) {
    return <Badge variant="secondary">Только доверенные</Badge>;
  }
  if (risk === "critical") {
    return <Badge variant="destructive">Нельзя запускать</Badge>;
  }
  if (risk === "high") {
    return <Badge variant="destructive">Высокий риск</Badge>;
  }
  if (risk === "unknown") {
    return <Badge variant="outline">Нужно проверить</Badge>;
  }
  return <Badge variant="outline">Проверить вручную</Badge>;
}

function sourceAccessSelectValue(source: Source) {
  if (source.access_status === "available") {
    return source.comments_enabled ? "available_comments" : "available_content";
  }
  return source.access_status || "pending_check";
}

function sourceAccessPatchFromValue(value: string): SourcePatchPayload {
  if (value === "available_content") {
    return { access_status: "available", comments_enabled: false };
  }
  if (value === "available_comments") {
    return { access_status: "available", comments_enabled: true };
  }
  if (value === "pending_check") {
    return { access_status: "pending_check", comments_enabled: false };
  }
  return { access_status: value };
}

function SourceAccessSelect({
  source,
  disabled,
  onUpdateSource,
}: {
  source: Source;
  disabled: boolean;
  onUpdateSource: (sourceId: string, payload: SourcePatchPayload) => Promise<void>;
}) {
  return (
    <NativeSelect
      className="h-9 w-[210px]"
      value={sourceAccessSelectValue(source)}
      disabled={disabled || sourceIsBlacklisted(source)}
      aria-label={`Статус источника ${source.title || sourceRef(source)}`}
      onChange={(event) =>
        void onUpdateSource(source.id, sourceAccessPatchFromValue(event.target.value))
      }
    >
      <NativeSelectOption value="available_content">
        Доступен для контента
      </NativeSelectOption>
      <NativeSelectOption value="available_comments">
        Комментарии открыты
      </NativeSelectOption>
      <NativeSelectOption value="pending_check">Ожидает проверки</NativeSelectOption>
      <NativeSelectOption value="invalid_comments_closed">
        Комментарии закрыты
      </NativeSelectOption>
      <NativeSelectOption value="invalid_private">Приватный</NativeSelectOption>
      <NativeSelectOption value="invalid_join_request">Нужна заявка</NativeSelectOption>
      <NativeSelectOption value="invalid_account_banned">
        Аккаунт забанен
      </NativeSelectOption>
      <NativeSelectOption value="invalid_write_forbidden">Запрет записи</NativeSelectOption>
      <NativeSelectOption value="invalid_not_found">Не найден</NativeSelectOption>
      <NativeSelectOption value="invalid_not_channel">Не канал</NativeSelectOption>
      <NativeSelectOption value="failed">Ошибка</NativeSelectOption>
      <NativeSelectOption value="archived">Архив</NativeSelectOption>
    </NativeSelect>
  );
}

function SourcesScreen({
  sources,
  sourceFolders,
}: {
  sources: Source[];
  sourceFolders: SourceFolder[];
}) {
  const foldersWithSources = React.useMemo(() => {
    return sourceFolders
      .map((folder) => {
        const folderSources = sources
          .filter(
            (source) =>
              source.folder_id === folder.id &&
              !sourceIsBlacklisted(source) &&
              source.access_status !== "archived",
          )
          .sort((left, right) =>
            sourceDisplayName(left).localeCompare(sourceDisplayName(right), "ru"),
          );
        return { folder, sources: folderSources };
      })
      .filter((item) => item.sources.length > 0);
  }, [sourceFolders, sources]);

  function folderRefs(folderSources: Source[]) {
    return folderSources.map(sourceRef).filter(Boolean).join("\n");
  }

  async function copyFolderSources(folderName: string, folderSources: Source[]) {
    const refs = folderRefs(folderSources);
    if (!refs) return;
    await navigator.clipboard.writeText(refs);
    window.alert(`Скопировано источников из «${folderName}»: ${folderSources.length}`);
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle>Источники</CardTitle>
        <CardDescription>
          Папки для быстрого экспорта списков. Рабочие источники кампаний
          задаются прямо в модалке запуска или редактирования кампании.
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-4">
        {foldersWithSources.length ? (
          <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">
            {foldersWithSources.map(({ folder, sources: folderSources }) => (
              <div key={folder.id} className="grid gap-3 rounded-lg border p-4">
                <div className="flex min-w-0 items-start justify-between gap-3">
                  <div className="min-w-0">
                    <div className="truncate font-medium" title={folder.name}>
                      {folder.name}
                    </div>
                    <div className="text-sm text-muted-foreground">
                      {folderSources.length} источников
                    </div>
                  </div>
                  <Button
                    type="button"
                    variant="outline"
                    size="sm"
                    onClick={() => void copyFolderSources(folder.name, folderSources)}
                  >
                    <DownloadIcon className="size-4" />
                    Копировать
                  </Button>
                </div>
                <Textarea
                  value={folderRefs(folderSources)}
                  readOnly
                  className="h-40 resize-none font-mono text-xs"
                />
              </div>
            ))}
          </div>
        ) : (
          <EmptyState
            icon={<RadioTowerIcon />}
            title="Папок с источниками пока нет"
            description="Списки для кампаний теперь можно вставлять напрямую при создании или редактировании кампании."
          />
        )}
      </CardContent>
    </Card>
  );
}

function ChannelMapScreen({
  actionBusy,
  existingSources,
  onImportSources,
}: {
  actionBusy: string | null;
  existingSources: Source[];
  onImportSources: (
    refs: string[],
    options?: ChannelMapImportOptions,
  ) => Promise<Source[]>;
}) {
  const [selectedRefs, setSelectedRefs] = React.useState<string[]>([]);

  async function handleImportSelected() {
    if (!selectedRefs.length) {
      window.alert("Выберите минимум один канал.");
      return;
    }
    await onImportSources(selectedRefs, { verifyComments: true });
    setSelectedRefs([]);
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle>База каналов</CardTitle>
        <CardDescription>
          Каталог Telegram-каналов по тематикам. Выберите нишу, найдите каналы и
          импортируйте их в источники.
        </CardDescription>
        <CardAction>
          <Button
            disabled={
              !selectedRefs.length || actionBusy === "channel-map-import"
            }
            onClick={() => void handleImportSelected()}
          >
            {actionBusy === "channel-map-import" ? (
              <Loader2Icon className="animate-spin" />
            ) : (
              <PlusIcon />
            )}
            {actionBusy === "channel-map-import"
              ? "Идет импорт"
              : "Импортировать выбранные"}
          </Button>
        </CardAction>
      </CardHeader>
      <CardContent>
        <ChannelMapPicker
          selectedRefs={selectedRefs}
          onSelectedRefsChange={setSelectedRefs}
          existingSources={existingSources}
        />
      </CardContent>
    </Card>
  );
}

function ChannelMapPicker({
  selectedRefs,
  onSelectedRefsChange,
  existingSources,
  compact = false,
}: {
  selectedRefs: string[];
  onSelectedRefsChange: (refs: string[]) => void;
  existingSources: Source[];
  compact?: boolean;
}) {
  const [summary, setSummary] = React.useState<ChannelMapSummary | null>(null);
  const [query, setQuery] = React.useState("");
  const [channels, setChannels] = React.useState<ChannelMapChannel[]>([]);
  const [total, setTotal] = React.useState(0);
  const [page, setPage] = React.useState(1);
  const [loadingChannels, setLoadingChannels] = React.useState(false);
  const [error, setError] = React.useState<string | null>(null);
  const pickerRootRef = React.useRef<HTMLDivElement | null>(null);

  React.useEffect(() => {
    let alive = true;
    channelMapRequest<ChannelMapSummary>("/summary")
      .then((item) => {
        if (alive) setSummary(item);
      })
      .catch(() => {
        if (alive) setSummary(null);
      });
    return () => {
      alive = false;
    };
  }, []);

  React.useEffect(() => {
    setPage(1);
  }, [query, compact]);

  React.useEffect(() => {
    const trimmedQuery = query.trim();
    const pageSize = compact ? 30 : 100;
    const offset = (page - 1) * pageSize;

    let alive = true;
    const timeout = window.setTimeout(() => {
      let path = `/channels?level=macro&limit=${pageSize}&offset=${offset}`;
      if (trimmedQuery) path += `&q=${encodeURIComponent(trimmedQuery)}`;
      setLoadingChannels(true);
      setError(null);
      channelMapRequest<ChannelMapChannelsResponse>(path)
        .then((response) => {
          if (!alive) return;
          setChannels(response.items);
          setTotal(response.total);
          if (!summary && response.atlas_total) {
            setSummary({
              total_channels: response.atlas_total,
              macro_categories: 0,
              micro_categories: 0,
            });
          }
        })
        .catch((err) => {
          if (alive) setError(errorMessage(err));
        })
        .finally(() => {
          if (alive) setLoadingChannels(false);
        });
    }, 250);
    return () => {
      alive = false;
      window.clearTimeout(timeout);
    };
  }, [query, compact, summary, page]);

  function toggleRef(ref: string) {
    onSelectedRefsChange(
      selectedRefs.includes(ref)
        ? selectedRefs.filter((item) => item !== ref)
        : [...selectedRefs, ref],
    );
  }

  function selectCurrentPage() {
    if (!channels.length) return;
    const nextRefs = new Set(selectedRefs);
    channels.forEach((channel) => nextRefs.add(channel.ref));
    onSelectedRefsChange(Array.from(nextRefs));
  }

  function goToPage(nextPage: number) {
    const clampedPage = Math.max(1, Math.min(totalPages, nextPage));
    if (clampedPage === page) return;
    setPage(clampedPage);
    window.requestAnimationFrame(() => {
      pickerRootRef.current?.scrollIntoView({
        behavior: "smooth",
        block: "start",
      });
    });
  }

  const importedRefs = new Set(existingSources.map(sourceComparableRef));
  const pageSize = compact ? 30 : 100;
  const totalPages = Math.max(1, Math.ceil(total / pageSize));
  const visibleFrom = channels.length ? (page - 1) * pageSize + 1 : 0;
  const visibleTo = channels.length ? visibleFrom + channels.length - 1 : 0;
  const selectedOnPage = channels.filter((channel) =>
    selectedRefs.includes(channel.ref),
  ).length;
  const allCurrentPageSelected =
    channels.length > 0 && selectedOnPage === channels.length;

  React.useEffect(() => {
    if (page > totalPages) setPage(totalPages);
  }, [page, totalPages]);

  return (
    <div ref={pickerRootRef} className="grid gap-4">
      <div className="grid gap-3">
        <Field>
          <FieldLabel>Поиск</FieldLabel>
          <Input
            value={query}
            onChange={(event) => setQuery(event.target.value)}
            placeholder="Название, username или ниша"
          />
        </Field>
      </div>
      {error && !loadingChannels && (
        <Alert variant="destructive">
          <AlertTitle>База каналов недоступна</AlertTitle>
          <AlertDescription>{error}</AlertDescription>
        </Alert>
      )}
      <div className="flex flex-wrap items-center justify-between gap-2 text-sm text-muted-foreground">
        <span>
          {loadingChannels
            ? "Загружаю каналы..."
            : `Показано: ${visibleFrom}-${visibleTo} из ${formatCompactNumber(total)}`}
          {summary?.total_channels
            ? ` · всего в базе: ${formatCompactNumber(summary.total_channels)}`
            : ""}
        </span>
        <div className="flex flex-wrap items-center gap-2">
          <span>
            Выбрано: {selectedRefs.length}
            {channels.length ? ` · на странице: ${selectedOnPage}` : ""}
          </span>
          <Button
            type="button"
            variant="outline"
            size="sm"
            onClick={selectCurrentPage}
            disabled={
              loadingChannels || !channels.length || allCurrentPageSelected
            }
          >
            {allCurrentPageSelected ? "Страница выбрана" : "Выбрать все на странице"}
          </Button>
        </div>
      </div>
      <div
        className={`grid gap-2 overflow-auto rounded-md border p-2 ${compact ? "max-h-72" : "max-h-[620px]"}`}
      >
        {channels.map((channel) => {
          const isSelected = selectedRefs.includes(channel.ref);
          const alreadyImported = importedRefs.has(comparableRef(channel.ref));
          return (
            <label
              key={channel.channel_id}
              className="flex min-w-0 cursor-pointer items-center gap-3 rounded-md px-2 py-2 hover:bg-muted/60"
            >
              <Checkbox
                checked={isSelected}
                onCheckedChange={() => toggleRef(channel.ref)}
              />
              {channel.avatar_url ? (
                <img
                  src={channel.avatar_url}
                  alt={channel.title}
                  className="size-9 shrink-0 rounded-full object-cover"
                />
              ) : (
                <div className="flex size-9 shrink-0 items-center justify-center rounded-full bg-muted text-xs font-semibold">
                  {initials(channel.title)}
                </div>
              )}
              <span className="min-w-0 flex-1">
                <span
                  className="block truncate font-medium"
                  title={channel.title}
                >
                  {channel.title}
                </span>
                <span className="block truncate text-sm text-muted-foreground">
                  {channel.username ? `@${channel.username}` : channel.ref} ·{" "}
                  {formatCompactNumber(channel.participants_count)} подписчиков
                </span>
              </span>
              <span className="hidden max-w-60 truncate text-sm text-muted-foreground md:block">
                {channel.sub_cluster_label || channel.cluster_label}
              </span>
              {alreadyImported && (
                <Badge variant="secondary">В источниках</Badge>
              )}
            </label>
          );
        })}
        {!channels.length && !loadingChannels && (
          <EmptyState
            icon={<MapIcon />}
            title="Каналы не найдены"
            description="Измените поисковый запрос."
          />
        )}
      </div>
      <div className="flex flex-wrap items-center justify-between gap-2">
        <div className="text-sm text-muted-foreground">
          Страница {page} из {totalPages}
        </div>
        <div className="flex items-center gap-2">
          <Button
            type="button"
            variant="outline"
            size="sm"
            onClick={() => goToPage(1)}
            disabled={page <= 1 || loadingChannels}
          >
            Первая
          </Button>
          <Button
            type="button"
            variant="outline"
            size="sm"
            onClick={() => goToPage(page - 1)}
            disabled={page <= 1 || loadingChannels}
          >
            Назад
          </Button>
          <Button
            type="button"
            variant="outline"
            size="sm"
            onClick={() => goToPage(page + 1)}
            disabled={page >= totalPages || loadingChannels}
          >
            Вперед
          </Button>
          <Button
            type="button"
            variant="outline"
            size="sm"
            onClick={() => goToPage(totalPages)}
            disabled={page >= totalPages || loadingChannels}
          >
            Последняя
          </Button>
        </div>
      </div>
    </div>
  );
}

function SourceDialog({
  isBusy,
  onCreateSourceList,
}: {
  isBusy: boolean;
  onCreateSourceList: (refsRaw: string, title: string | null) => Promise<void>;
}) {
  const [open, setOpen] = React.useState(false);
  const [submitError, setSubmitError] = React.useState<string | null>(null);

  async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setSubmitError(null);
    const formElement = event.currentTarget;
    const form = new FormData(formElement);
    try {
      await onCreateSourceList(
        String(form.get("refs") || ""),
        cleanOptionalText(form.get("title")),
      );
      formElement.reset();
      setOpen(false);
    } catch (error) {
      setSubmitError(errorMessage(error));
    }
  }

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button>
          <PlusIcon />
          Добавить источник
        </Button>
      </DialogTrigger>
      <DialogContent className="sm:max-w-2xl">
        <form onSubmit={(event) => void handleSubmit(event)}>
          <DialogHeader>
            <DialogTitle>Новый источник</DialogTitle>
            <DialogDescription>
              Добавьте один источник или список. После сохранения система сразу
              проверит доступ и сама определит тип: канал, группа или диалог.
            </DialogDescription>
          </DialogHeader>
          <FieldGroup className="py-4">
            <ModalError
              error={submitError}
              title="Не удалось добавить источник"
            />
            <Field>
              <HelpLabel
                htmlFor="source-refs"
                tip="Можно вставить один источник или сразу список: каждый с новой строки, через пробел, запятую или точку с запятой. Поддерживаются @username, t.me ссылки и id."
              >
                Источники
              </HelpLabel>
              <Textarea
                id="source-refs"
                name="refs"
                placeholder={"@channel\nhttps://t.me/group, @another_channel"}
                required
                rows={6}
              />
            </Field>
            <Field>
              <FieldLabel htmlFor="source-title">Название</FieldLabel>
              <Input
                id="source-title"
                name="title"
                placeholder="Опционально, только если добавляете один источник"
              />
            </Field>
          </FieldGroup>
          <DialogFooter>
            <Button
              type="button"
              variant="outline"
              onClick={() => setOpen(false)}
            >
              Отмена
            </Button>
            <Button type="submit" disabled={isBusy}>
              Сохранить
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

function ParsingScreen({
  accounts,
  sources,
  access,
  actionBusy,
  onParseSourcePosts,
  onParseDialogs,
  onParseUsers,
  onParseMessageUsers,
  onParseComments,
  onChannelSearch,
  onGroupSearch,
  onLoadJobs,
  onLoadJob,
  onLoadResults,
  onDownloadJob,
}: {
  accounts: TelegramAccount[];
  sources: Source[];
  access: AccessSummary | null;
  actionBusy: string | null;
  onParseSourcePosts: (
    payload: ParseSourcePostsPayload,
  ) => Promise<ParseSourceResponse>;
  onParseDialogs: (
    payload: ParseDialogsPayload,
  ) => Promise<ParseDialogsResponse>;
  onParseUsers: (payload: ParseUsersPayload) => Promise<ParseUsersResponse>;
  onParseMessageUsers: (
    payload: ParseMessageUsersPayload,
  ) => Promise<ParseUsersResponse>;
  onParseComments: (
    payload: ParseCommentsPayload,
  ) => Promise<ParseCommentsResponse>;
  onChannelSearch: (payload: ChannelSearchPayload) => Promise<ChannelSearchResponse>;
  onGroupSearch: (payload: GroupSearchPayload) => Promise<GroupSearchResponse>;
  onLoadJobs: () => Promise<ParsingJob[]>;
  onLoadJob: (jobId: string) => Promise<ParsingJobDetail>;
  onLoadResults: (jobId: string) => Promise<ParsingResult[]>;
  onDownloadJob: (jobId: string, format: string) => Promise<void>;
}) {
  const [mode, setMode] = React.useState<ParsingMode>("channels");
  const [result, setResult] = React.useState<
    | ParseSourceResponse
    | ParseDialogsResponse
    | ParseUsersResponse
    | ParseCommentsResponse
    | ChannelSearchResponse
    | GroupSearchResponse
    | null
  >(null);
  const [error, setError] = React.useState<string | null>(null);
  const [jobs, setJobs] = React.useState<ParsingJob[]>([]);
  const [selectedJob, setSelectedJob] = React.useState<ParsingJobDetail | null>(
    null,
  );
  const [jobResults, setJobResults] = React.useState<ParsingResult[]>([]);
  const [resultFilter, setResultFilter] = React.useState("");
  const [groupSuffixMode, setGroupSuffixMode] = React.useState<"manual" | "auto">("manual");
  const [groupSuffixLanguage, setGroupSuffixLanguage] = React.useState("ru");
  const [groupAutoSuffixCount, setGroupAutoSuffixCount] = React.useState(6);
  const [presetStatus, setPresetStatus] = React.useState<string | null>(null);
  const [pendingPreset, setPendingPreset] = React.useState<ParsingPreset | null>(null);
  const parsingFormRef = React.useRef<HTMLFormElement | null>(null);
  const presetFileInputRef = React.useRef<HTMLInputElement | null>(null);
  const busy = actionBusy?.startsWith("parsing") || false;
  const defaultAccountId = accounts[0]?.id || "";
  const defaultSourceId = sources[0]?.id || "";
  const enabled = React.useMemo(() => enabledFeatureSet(access), [access]);
  const canUseMode = React.useCallback(
    (value: ParsingMode) => enabled.has(parsingModeFeatures[value]),
    [enabled],
  );

  React.useEffect(() => {
    if (canUseMode(mode)) return;
    const available = parsingOptions.find((option) => canUseMode(option.value));
    if (available) setMode(available.value);
  }, [canUseMode, mode]);

  const refreshJobs = React.useCallback(async () => {
    try {
      const loaded = await onLoadJobs();
      setJobs(loaded);
    } catch (err) {
      setError(errorMessage(err));
    }
  }, [onLoadJobs]);

  React.useEffect(() => {
    if (mode === "jobs" || mode === "export") {
      void refreshJobs();
    }
  }, [mode, refreshJobs]);

  const buildCurrentPreset = React.useCallback((): ParsingPreset | null => {
    const form = parsingFormRef.current;
    if (!form) return null;
    return {
      schema: "demo-platform.parsing-preset.v1",
      saved_at: new Date().toISOString(),
      mode,
      ui: {
        group_suffix_mode: groupSuffixMode,
        group_suffix_language: groupSuffixLanguage,
        group_auto_suffix_count: groupAutoSuffixCount,
      },
      fields: collectParsingPresetFields(form),
    };
  }, [
    groupAutoSuffixCount,
    groupSuffixLanguage,
    groupSuffixMode,
    mode,
  ]);

  const queuePresetApply = React.useCallback((preset: ParsingPreset) => {
    setGroupSuffixMode(preset.ui.group_suffix_mode || "manual");
    setGroupSuffixLanguage(preset.ui.group_suffix_language || "ru");
    setGroupAutoSuffixCount(
      clampNumber(
        String(preset.ui.group_auto_suffix_count || 6),
        1,
        12,
        6,
      ),
    );
    setMode(preset.mode);
    setPendingPreset(preset);
  }, []);

  React.useEffect(() => {
    const raw = window.localStorage.getItem(PARSING_PRESET_STORAGE_KEY);
    if (!raw) return;
    try {
      const preset = normalizeParsingPreset(JSON.parse(raw));
      if (preset) queuePresetApply(preset);
    } catch {
      window.localStorage.removeItem(PARSING_PRESET_STORAGE_KEY);
    }
  }, [queuePresetApply]);

  React.useEffect(() => {
    if (!pendingPreset || pendingPreset.mode !== mode) return;
    const frame = window.requestAnimationFrame(() => {
      const form = parsingFormRef.current;
      if (!form) return;
      applyParsingPresetFields(form, pendingPreset.fields);
      setPendingPreset(null);
      setPresetStatus("Пресет применен");
    });
    return () => window.cancelAnimationFrame(frame);
  }, [mode, pendingPreset]);

  function handleSavePreset() {
    const preset = buildCurrentPreset();
    if (!preset) return;
    window.localStorage.setItem(PARSING_PRESET_STORAGE_KEY, JSON.stringify(preset));
    setPresetStatus("Пресет сохранен");
  }

  function handleExportPreset() {
    const preset = buildCurrentPreset();
    if (!preset) return;
    downloadJsonFile(
      `parsing-preset-${safeFileSlug(mode)}-${new Date()
        .toISOString()
        .slice(0, 10)}.json`,
      preset,
    );
    setPresetStatus("JSON экспортирован");
  }

  async function handleImportPreset(event: React.ChangeEvent<HTMLInputElement>) {
    const file = event.target.files?.[0];
    event.target.value = "";
    if (!file) return;
    try {
      const preset = normalizeParsingPreset(JSON.parse(await file.text()));
      if (!preset) throw new Error("Некорректный JSON пресета");
      window.localStorage.setItem(PARSING_PRESET_STORAGE_KEY, JSON.stringify(preset));
      queuePresetApply(preset);
    } catch (err) {
      setError(errorMessage(err));
    }
  }

  async function openJob(jobId: string) {
    setError(null);
    try {
      const [detail, results] = await Promise.all([
        onLoadJob(jobId),
        onLoadResults(jobId),
      ]);
      setSelectedJob(detail);
      setJobResults(results);
    } catch (err) {
      setError(errorMessage(err));
    }
  }

  async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setError(null);
    setResult(null);
    if (!canUseMode(mode)) {
      setError("Этот вид парсинга не подключен");
      return;
    }
    const form = new FormData(event.currentTarget);
    const accountId = String(form.get("telegram_account_id") || "") || null;
    const sourceId = String(form.get("source_id") || "") || null;
    const sourceRef = String(form.get("source_ref") || "").trim() || null;
    const limit = clampNumber(form.get("limit"), 1, 5000, 100);
    const ensureMembership = form.get("ensure_membership") === "on";
    const keywords = splitTextareaValues(form.get("keywords"));
    const dateFrom = String(form.get("date_from") || "").trim() || null;
    const dateTo = String(form.get("date_to") || "").trim() || null;
    const delayPayload: ParseDelayPayload = {
      delay_seconds_min: numberOrNull(form.get("delay_seconds_min")),
      delay_seconds_max: numberOrNull(form.get("delay_seconds_max")),
    };

    try {
      if (mode === "jobs" || mode === "export") {
        await refreshJobs();
        return;
      }
      if (mode === "channels") {
        const autoSuffixes = (
          parsingAutoSuffixes[groupSuffixLanguage] || parsingAutoSuffixes.ru
        ).slice(0, groupAutoSuffixCount);
        const commentsMode =
          (String(form.get("comments_mode") || "any") as
            | "any"
            | "open"
            | "closed") || "any";
        setResult(
          await onChannelSearch({
            telegram_account_id: accountId,
            keywords,
            keyword_suffixes:
              groupSuffixMode === "auto"
                ? autoSuffixes
                : splitTextareaValues(form.get("keyword_suffixes")),
            min_participants: numberOrNull(form.get("min_participants")),
            max_participants: numberOrNull(form.get("max_participants")),
            language_code:
              String(form.get("language_code") || "").trim() || null,
            country_code: String(form.get("country_code") || "").trim() || null,
            comments_required: commentsMode === "open",
            comments_mode: commentsMode,
            min_engagement_score: numberOrNull(
              form.get("min_engagement_score"),
            ),
            limit: clampNumber(form.get("limit"), 1, 200, 50),
            source: "mixed",
            active_days: numberOrNull(form.get("active_days")),
            ...delayPayload,
          }),
        );
        await refreshJobs();
        return;
      }
      if (mode === "groups") {
        const autoSuffixes = (
          parsingAutoSuffixes[groupSuffixLanguage] || parsingAutoSuffixes.ru
        ).slice(0, groupAutoSuffixCount);
        setResult(
          await onGroupSearch({
            telegram_account_id: accountId,
            keywords,
            keyword_suffixes:
              groupSuffixMode === "auto"
                ? autoSuffixes
                : splitTextareaValues(form.get("keyword_suffixes")),
            min_participants: numberOrNull(form.get("min_participants")),
            max_participants: numberOrNull(form.get("max_participants")),
            active_days: numberOrNull(form.get("active_days")),
            min_activity_score: numberOrNull(form.get("min_activity_score")),
            access_type:
              (String(form.get("access_type") || "any") as
                | "any"
                | "public"
                | "private") || "any",
            ai_suggestions_enabled: form.get("ai_suggestions_enabled") === "on",
            limit: clampNumber(form.get("limit"), 1, 300, 50),
            ...delayPayload,
          }),
        );
        await refreshJobs();
        return;
      }
      if (mode === "posts") {
        if (!sourceId) throw new Error("Выбери источник для парсинга постов");
        setResult(
          await onParseSourcePosts({
            telegram_account_id: accountId,
            source_id: sourceId,
            limit: clampNumber(form.get("limit"), 1, 100, 20),
            ensure_membership: ensureMembership,
          }),
        );
        return;
      }
      if (mode === "users") {
        if (!sourceId && !sourceRef)
          throw new Error(
            "Укажи источник или ссылку для парсинга пользователей",
          );
        setResult(
          await onParseUsers({
            telegram_account_id: accountId,
            source_id: sourceId,
            source_ref: sourceRef,
            limit,
            min_comments: clampNumber(form.get("min_comments"), 0, 100000, 0),
            min_messages: clampNumber(form.get("min_messages"), 0, 100000, 0),
            username_required: form.get("username_required") === "on",
            active_days: numberOrNull(form.get("active_days")),
            keywords,
            ...delayPayload,
          }),
        );
        await refreshJobs();
        return;
      }
      if (mode === "message_users") {
        if (!sourceId && !sourceRef)
          throw new Error("Укажи чат, группу или канал для поиска сообщений");
        setResult(
          await onParseMessageUsers({
            telegram_account_id: accountId,
            source_id: sourceId,
            source_ref: sourceRef,
            keywords,
            keywords_mode:
              (String(form.get("keywords_mode") || "any") as
                | "any"
                | "all"
                | "phrase") || "any",
            date_from: dateFrom,
            date_to: dateTo,
            message_limit: clampNumber(
              form.get("message_limit"),
              1,
              10000,
              500,
            ),
            user_limit: clampNumber(form.get("user_limit"), 1, 5000, 500),
            min_messages: clampNumber(form.get("min_messages"), 1, 100000, 1),
            username_required: form.get("username_required") === "on",
            ...delayPayload,
          }),
        );
        await refreshJobs();
        return;
      }
      if (mode === "comments") {
        if (!sourceId && !sourceRef)
          throw new Error(
            "Укажи источник или ссылку для парсинга комментариев",
          );
        setResult(
          await onParseComments({
            telegram_account_id: accountId,
            source_id: sourceId,
            source_ref: sourceRef,
            post_tg_message_id:
              String(form.get("post_tg_message_id") || "").trim() || null,
            post_limit: clampNumber(form.get("post_limit"), 1, 100, 5),
            comments_per_post: clampNumber(
              form.get("comments_per_post"),
              1,
              500,
              50,
            ),
            keywords,
            date_from: dateFrom,
            date_to: dateTo,
            ensure_membership: ensureMembership,
            ...delayPayload,
          }),
        );
        await refreshJobs();
        return;
      }
      setResult(
        await onParseDialogs({
          telegram_account_id: accountId,
          entity_type: mode === "channels" || mode === "groups" ? mode : "all",
          limit: clampNumber(form.get("limit"), 1, 500, 100),
          ...delayPayload,
        }),
      );
      await refreshJobs();
    } catch (err) {
      setError(errorMessage(err));
    }
  }

  return (
    <div className="grid gap-4">
      <Card>
        <CardHeader>
          <CardTitle>Парсинг Telegram</CardTitle>
          <CardDescription>
            Каналы, группы, пользователи, комментарии, сообщения, задачи и экспорт.
          </CardDescription>
        </CardHeader>
        <CardContent className="grid gap-4">
          <Tabs value={mode} onValueChange={(value) => setMode(value as ParsingMode)}>
            <TabsList className="h-auto flex-wrap justify-start">
              {parsingOptions.map((option) => (
                <TabsTrigger
                  key={option.value}
                  value={option.value}
                  disabled={!canUseMode(option.value)}
                >
                  {option.label}
                </TabsTrigger>
              ))}
            </TabsList>
          </Tabs>
          {(mode === "jobs" || mode === "export") && (
            <ParsingJobsPanel
              jobs={jobs}
              selectedJob={selectedJob}
              results={jobResults}
              resultFilter={resultFilter}
              onResultFilterChange={setResultFilter}
              onRefresh={refreshJobs}
              onOpenJob={(jobId) => void openJob(jobId)}
              onDownloadJob={(jobId, format) => void onDownloadJob(jobId, format)}
              exportOnly={mode === "export"}
            />
          )}
          {mode !== "jobs" && mode !== "export" && (
            <div className="grid gap-4 lg:grid-cols-[minmax(500px,560px)_minmax(0,1fr)]">
          <form ref={parsingFormRef} className="grid gap-4" onSubmit={handleSubmit}>
            <div className="flex flex-wrap items-center gap-2 rounded-md border bg-muted/20 p-2">
              <Button
                type="button"
                variant="outline"
                size="sm"
                onClick={handleSavePreset}
              >
                <CheckIcon className="size-4" />
                Сохранить
              </Button>
              <Button
                type="button"
                variant="outline"
                size="sm"
                onClick={handleExportPreset}
              >
                <DownloadIcon className="size-4" />
                Экспорт
              </Button>
              <Button
                type="button"
                variant="outline"
                size="sm"
                onClick={() => presetFileInputRef.current?.click()}
              >
                <UploadIcon className="size-4" />
                Импорт
              </Button>
              <input
                ref={presetFileInputRef}
                type="file"
                accept="application/json,.json"
                className="hidden"
                onChange={(event) => void handleImportPreset(event)}
              />
              {presetStatus && (
                <span className="text-sm text-muted-foreground">{presetStatus}</span>
              )}
            </div>
            <FieldGroup>
              <Field>
                <HelpLabel
                  htmlFor="parsing-account"
                  tip={
                    mode === "channels"
                      ? "Через этот аккаунт выполняется Telegram search и проверка найденных каналов. Если не выбрать, API возьмет последний активный аккаунт workspace."
                      : "Аккаунт, через который будет выполняться Telethon-запрос. Если не выбрать, API возьмет последний активный аккаунт workspace."
                  }
                >
                  Telegram аккаунт
                </HelpLabel>
                <NativeSelect
                  id="parsing-account"
                  name="telegram_account_id"
                  defaultValue={defaultAccountId}
                  className="w-full"
                >
                  <NativeSelectOption value="">
                    Автоматически
                  </NativeSelectOption>
                  {accounts.map((account) => (
                    <NativeSelectOption key={account.id} value={account.id}>
                      {account.display_name ||
                        account.username ||
                        account.id.slice(0, 8)}
                    </NativeSelectOption>
                  ))}
                </NativeSelect>
              </Field>
              {(mode === "channels" || mode === "groups" || mode === "users") && (
                <Field>
                  <HelpLabel
                    htmlFor="parsing-keywords"
                    tip={
                      mode === "channels"
                        ? "Ключевые слова ищутся одновременно через Telegram search и в базе каналов."
                        : "Ключевые слова через запятую или с новой строки. Для групп и пользователей фильтруем Telegram-данные."
                    }
                  >
                    Ключевые слова
                  </HelpLabel>
                  <Textarea
                    id="parsing-keywords"
                    name="keywords"
                    rows={3}
                    placeholder={
                      mode === "channels" || mode === "groups"
                        ? "недвижимость\nипотека\nновостройки"
                        : "Можно оставить пустым"
                    }
                  />
                </Field>
              )}
              {mode === "channels" && (
                <div className="grid gap-3 rounded-lg border bg-muted/20 p-3">
                  <div className="flex flex-wrap items-center justify-between gap-2">
                    <HelpLabel
                      htmlFor="parsing-channel-keyword-suffixes"
                      tip="Окончания комбинируются с ключевыми словами: например «crypto» + «signals/community». Можно через запятую или с новой строки."
                    >
                      Окончания запросов
                    </HelpLabel>
                    <div className="flex rounded-md border bg-background p-1">
                      <Button
                        type="button"
                        size="sm"
                        variant={groupSuffixMode === "manual" ? "secondary" : "ghost"}
                        onClick={() => setGroupSuffixMode("manual")}
                      >
                        Вручную
                      </Button>
                      <Button
                        type="button"
                        size="sm"
                        variant={groupSuffixMode === "auto" ? "secondary" : "ghost"}
                        onClick={() => setGroupSuffixMode("auto")}
                      >
                        Авто
                      </Button>
                    </div>
                  </div>
                  {groupSuffixMode === "manual" ? (
                    <Textarea
                      id="parsing-channel-keyword-suffixes"
                      name="keyword_suffixes"
                      rows={2}
                      placeholder="новости, канал, signals"
                    />
                  ) : (
                    <div className="grid gap-3 sm:grid-cols-[minmax(0,1fr)_220px]">
                      <Field>
                        <FieldLabel htmlFor="parsing-channel-auto-suffix-language">
                          Язык окончаний
                        </FieldLabel>
                        <NativeSelect
                          id="parsing-channel-auto-suffix-language"
                          value={groupSuffixLanguage}
                          onChange={(event) =>
                            setGroupSuffixLanguage(event.target.value)
                          }
                        >
                          <NativeSelectOption value="ru">Русский</NativeSelectOption>
                          <NativeSelectOption value="en">English</NativeSelectOption>
                          <NativeSelectOption value="mixed">Смешанный</NativeSelectOption>
                        </NativeSelect>
                      </Field>
                      <Field>
                        <FieldLabel htmlFor="parsing-channel-auto-suffix-count">
                          Количество
                        </FieldLabel>
                        <Input
                          id="parsing-channel-auto-suffix-count"
                          type="number"
                          min={1}
                          max={parsingAutoSuffixes[groupSuffixLanguage]?.length || 6}
                          value={groupAutoSuffixCount}
                          onChange={(event) =>
                            setGroupAutoSuffixCount(
                              clampNumber(event.target.value, 1, 12, 6),
                            )
                          }
                        />
                      </Field>
                      <div className="sm:col-span-2 rounded-md border bg-background px-3 py-2 text-sm text-muted-foreground">
                        Будет добавлено{" "}
                        {Math.min(
                          groupAutoSuffixCount,
                          parsingAutoSuffixes[groupSuffixLanguage]?.length || 0,
                        )}{" "}
                        окончаний к каждому ключевому слову.
                      </div>
                    </div>
                  )}
                </div>
              )}
              {mode === "channels" && (
                <>
                  <div className="grid gap-3 sm:grid-cols-2">
                    <Field>
                      <HelpLabel
                        htmlFor="parsing-min-participants"
                        tip="Минимальный размер аудитории канала. Для нишевых каналов можно ставить 100-500, для массовых - от 1000."
                      >
                        Участников от
                      </HelpLabel>
                      <Input id="parsing-min-participants" name="min_participants" type="number" min={0} defaultValue={500} />
                    </Field>
                    <Field>
                      <HelpLabel
                        htmlFor="parsing-max-participants"
                        tip="Верхняя граница аудитории. Оставьте пустым, если крупные каналы тоже подходят."
                      >
                        Участников до
                      </HelpLabel>
                      <Input id="parsing-max-participants" name="max_participants" type="number" min={0} />
                    </Field>
                  </div>
                    <Field>
                      <HelpLabel
                        htmlFor="parsing-active-days"
                        tip="После Telegram search канал останется в выдаче, если удалось увидеть свежий последний пост."
                      >
                        Активность, дней
                      </HelpLabel>
                      <Input
                        id="parsing-active-days"
                        name="active_days"
                        type="number"
                        min={1}
                        defaultValue={180}
                      />
                    </Field>
                      <div className="grid gap-3 sm:grid-cols-3">
                        <Field>
                          <HelpLabel
                            htmlFor="parsing-language"
                            tip="Для Telegram search язык определяется по названию и описанию, для базы берем сохраненный язык канала."
                          >
                            Язык
                          </HelpLabel>
                          <NativeSelect id="parsing-language" name="language_code" defaultValue="ru">
                            <NativeSelectOption value="">Любой</NativeSelectOption>
                            <NativeSelectOption value="ru">Русский</NativeSelectOption>
                            <NativeSelectOption value="en">Английский</NativeSelectOption>
                          </NativeSelect>
                        </Field>
                        <Field>
                          <HelpLabel
                            htmlFor="parsing-country"
                            tip="Страна или основной гео-сигнал канала. RU - Россия. Пустое значение не фильтрует гео."
                          >
                            Гео
                          </HelpLabel>
                          <NativeSelect id="parsing-country" name="country_code" defaultValue="RU">
                            <NativeSelectOption value="">Любое</NativeSelectOption>
                            <NativeSelectOption value="RU">Россия</NativeSelectOption>
                            <NativeSelectOption value="BY">Беларусь</NativeSelectOption>
                            <NativeSelectOption value="KZ">Казахстан</NativeSelectOption>
                            <NativeSelectOption value="UA">Украина</NativeSelectOption>
                          </NativeSelect>
                        </Field>
                        <Field>
                          <HelpLabel
                            htmlFor="parsing-engagement"
                            tip="Оценка активности аудитории от 0 до 100 по данным atlas. 0-30 слабый сигнал, 30-60 нормальный, 60+ сильный. Пустое значение не фильтрует."
                          >
                            Вовлеченность от
                          </HelpLabel>
                          <NativeSelect id="parsing-engagement" name="min_engagement_score" defaultValue="">
                            <NativeSelectOption value="">Любая</NativeSelectOption>
                            <NativeSelectOption value="20">20+ мягкий фильтр</NativeSelectOption>
                            <NativeSelectOption value="40">40+ нормальная</NativeSelectOption>
                            <NativeSelectOption value="60">60+ высокая</NativeSelectOption>
                            <NativeSelectOption value="80">80+ очень высокая</NativeSelectOption>
                          </NativeSelect>
                        </Field>
                      </div>
                      <Field>
                        <HelpLabel
                          htmlFor="parsing-comments-mode"
                          tip="Открытые - только каналы с найденным discussion-чатом. Закрытые - каналы без доступных комментариев. Не важно - не фильтровать по комментариям."
                        >
                          Фильтр комментариев
                        </HelpLabel>
                        <NativeSelect id="parsing-comments-mode" name="comments_mode" defaultValue="any">
                          <NativeSelectOption value="any">Не важно</NativeSelectOption>
                          <NativeSelectOption value="open">Только открытые комментарии</NativeSelectOption>
                          <NativeSelectOption value="closed">Только закрытые комментарии</NativeSelectOption>
                        </NativeSelect>
                      </Field>
                </>
              )}
              {mode === "groups" && (
                <>
                  <div className="grid gap-3 rounded-lg border bg-muted/20 p-3">
                    <div className="flex flex-wrap items-center justify-between gap-2">
                      <HelpLabel
                        htmlFor="parsing-keyword-suffixes"
                        tip="Окончания комбинируются с ключевыми словами: например «crypto» + «chat/community». Можно через запятую или с новой строки."
                      >
                        Окончания запросов
                      </HelpLabel>
                      <div className="flex rounded-md border bg-background p-1">
                        <Button
                          type="button"
                          size="sm"
                          variant={groupSuffixMode === "manual" ? "secondary" : "ghost"}
                          onClick={() => setGroupSuffixMode("manual")}
                        >
                          Вручную
                        </Button>
                        <Button
                          type="button"
                          size="sm"
                          variant={groupSuffixMode === "auto" ? "secondary" : "ghost"}
                          onClick={() => setGroupSuffixMode("auto")}
                        >
                          Авто
                        </Button>
                      </div>
                    </div>
                    {groupSuffixMode === "manual" ? (
                      <Textarea
                        id="parsing-keyword-suffixes"
                        name="keyword_suffixes"
                        rows={2}
                        placeholder="чат, сообщество, форум"
                      />
                    ) : (
                      <div className="grid gap-3 sm:grid-cols-[minmax(0,1fr)_220px]">
                        <Field>
                          <FieldLabel htmlFor="parsing-auto-suffix-language">
                            Язык окончаний
                          </FieldLabel>
                          <NativeSelect
                            id="parsing-auto-suffix-language"
                            value={groupSuffixLanguage}
                            onChange={(event) =>
                              setGroupSuffixLanguage(event.target.value)
                            }
                          >
                            <NativeSelectOption value="ru">Русский</NativeSelectOption>
                            <NativeSelectOption value="en">English</NativeSelectOption>
                            <NativeSelectOption value="mixed">Смешанный</NativeSelectOption>
                          </NativeSelect>
                        </Field>
                        <Field>
                          <FieldLabel htmlFor="parsing-auto-suffix-count">
                            Количество
                          </FieldLabel>
                          <Input
                            id="parsing-auto-suffix-count"
                            type="number"
                            min={1}
                            max={parsingAutoSuffixes[groupSuffixLanguage]?.length || 6}
                            value={groupAutoSuffixCount}
                            onChange={(event) =>
                              setGroupAutoSuffixCount(
                                clampNumber(event.target.value, 1, 12, 6),
                              )
                            }
                          />
                        </Field>
                        <div className="sm:col-span-2 rounded-md border bg-background px-3 py-2 text-sm text-muted-foreground">
                          Будет добавлено{" "}
                          {Math.min(
                            groupAutoSuffixCount,
                            parsingAutoSuffixes[groupSuffixLanguage]?.length || 0,
                          )}{" "}
                          окончаний к каждому ключевому слову.
                        </div>
                      </div>
                    )}
                  </div>
                  <div className="grid gap-3 sm:grid-cols-2">
                    <Field>
                      <HelpLabel
                        htmlFor="parsing-min-participants"
                        tip="Минимальный размер группы. Для маленьких локальных чатов можно ставить 20-50, для рабочих сообществ - от 100."
                      >
                        Участников от
                      </HelpLabel>
                      <Input id="parsing-min-participants" name="min_participants" type="number" min={0} defaultValue={50} />
                    </Field>
                    <Field>
                      <HelpLabel
                        htmlFor="parsing-max-participants"
                        tip="Верхняя граница участников. Оставьте пустым, если размер группы не важен."
                      >
                        Участников до
                      </HelpLabel>
                      <Input id="parsing-max-participants" name="max_participants" type="number" min={0} />
                    </Field>
                    <Field>
                      <HelpLabel
                        htmlFor="parsing-active-days"
                        tip="Группа попадет в выдачу, если последнее видимое сообщение было не старше этого количества дней."
                      >
                        Активность, дней
                      </HelpLabel>
                      <Input id="parsing-active-days" name="active_days" type="number" min={1} defaultValue={90} />
                    </Field>
                  </div>
                  <div className="grid gap-3 rounded-lg border bg-muted/20 p-3">
                    <div className="flex items-center gap-2 font-medium">
                      <UserRoundIcon className="size-4 text-muted-foreground" />
                      Качество найденных групп
                    </div>
                    <div className="grid gap-3 sm:grid-cols-2">
                      <Field>
                        <HelpLabel
                          htmlFor="parsing-mail-rating"
                          tip="Практический фильтр для дальнейшей работы: чем выше значение, тем свежее активность в группе."
                        >
                          Рейтинг для рассылки
                        </HelpLabel>
                        <NativeSelect
                          id="parsing-mail-rating"
                          name="min_activity_score"
                          defaultValue="30"
                        >
                          <NativeSelectOption value="">Любой</NativeSelectOption>
                          <NativeSelectOption value="30">3/10 и выше</NativeSelectOption>
                          <NativeSelectOption value="60">6/10 и выше</NativeSelectOption>
                          <NativeSelectOption value="80">8/10 и выше</NativeSelectOption>
                        </NativeSelect>
                      </Field>
                      <Field>
                        <HelpLabel
                          htmlFor="parsing-access-type"
                          tip="Публичные группы имеют username. Приватные берутся только из диалогов выбранного аккаунта."
                        >
                          Комментарии / доступ
                        </HelpLabel>
                        <NativeSelect
                          id="parsing-access-type"
                          name="access_type"
                          defaultValue="any"
                        >
                          <NativeSelectOption value="any">Любые</NativeSelectOption>
                          <NativeSelectOption value="public">Только публичные</NativeSelectOption>
                          <NativeSelectOption value="private">Только приватные</NativeSelectOption>
                        </NativeSelect>
                      </Field>
                    </div>
                  </div>
                  <label className="flex items-center gap-2 rounded-md border p-3 text-sm">
                    <Checkbox name="ai_suggestions_enabled" />
                    AI-варианты ключей
                  </label>
                </>
              )}
              {(mode === "users" ||
                mode === "message_users" ||
                mode === "comments" ||
                mode === "posts") && (
                <>
                  <Field>
                    <HelpLabel
                      htmlFor="parsing-source"
                      tip="Сохраненный источник из раздела Источники. Для комментариев и пользователей можно вместо него вставить ссылку ниже."
                    >
                      Источник
                    </HelpLabel>
                    <NativeSelect
                      id="parsing-source"
                      name="source_id"
                      defaultValue={defaultSourceId}
                      className="w-full"
                    >
                      <NativeSelectOption value="">
                        Не выбран
                      </NativeSelectOption>
                      {sources.map((source) => (
                        <NativeSelectOption key={source.id} value={source.id}>
                          {source.title ||
                            source.username ||
                            source.url ||
                            source.id.slice(0, 8)}
                        </NativeSelectOption>
                      ))}
                    </NativeSelect>
                  </Field>
                  {mode !== "posts" && (
                    <Field>
                      <HelpLabel
                        htmlFor="parsing-source-ref"
                        tip="Можно вставить @username, t.me-ссылку или id, если источник еще не сохранен в системе."
                      >
                        Ссылка или username
                      </HelpLabel>
                      <Input
                        id="parsing-source-ref"
                        name="source_ref"
                        placeholder="@channel или https://t.me/channel"
                      />
                    </Field>
                  )}
                </>
              )}
              {(mode === "channels" ||
                mode === "groups" ||
                mode === "users" ||
                mode === "message_users" ||
                mode === "posts") && (
                <ParsingLimitControl
                  mode={mode}
                />
              )}
              {(mode === "channels" ||
                mode === "groups" ||
                mode === "users" ||
                mode === "message_users" ||
                mode === "comments") && (
                <Collapsible>
                  <div className="rounded-md border">
                    <CollapsibleTrigger asChild>
                      <Button
                        type="button"
                        variant="ghost"
                        className="w-full justify-between px-3"
                      >
                        Безопасность Telegram
                        <ChevronDownIcon className="size-4" />
                      </Button>
                    </CollapsibleTrigger>
                    <CollapsibleContent className="grid gap-3 border-t p-3">
                      <p className="text-sm text-muted-foreground">
                        Пауза между запросами снижает риск FloodWait на живом
                        аккаунте. Для ручной проверки обычно достаточно 1-3 сек.
                      </p>
                      <div className="grid gap-3 sm:grid-cols-2">
                        <Field>
                          <HelpLabel
                            htmlFor="parsing-delay-min"
                            tip="Минимальная пауза между Telegram-операциями в секундах. Пустое значение означает без дополнительной задержки."
                          >
                            Задержка от, сек
                          </HelpLabel>
                          <Input
                            id="parsing-delay-min"
                            name="delay_seconds_min"
                            type="number"
                            min={0}
                            max={60}
                            step="0.5"
                            placeholder="1"
                          />
                        </Field>
                        <Field>
                          <HelpLabel
                            htmlFor="parsing-delay-max"
                            tip="Максимальная пауза. Сервер выбирает случайное значение между «от» и «до», чтобы запросы не шли ровным ритмом."
                          >
                            Задержка до, сек
                          </HelpLabel>
                          <Input
                            id="parsing-delay-max"
                            name="delay_seconds_max"
                            type="number"
                            min={0}
                            max={300}
                            step="0.5"
                            placeholder="3"
                          />
                        </Field>
                      </div>
                    </CollapsibleContent>
                  </div>
                </Collapsible>
              )}
              {(mode === "users" || mode === "message_users") && (
                <>
                  {mode === "message_users" && (
                    <>
                      <Field>
                        <HelpLabel
                          htmlFor="parsing-keywords"
                          tip="Слова или фразы для поиска в сообщениях. Можно через запятую или с новой строки. Если оставить пустым, будут собраны активные авторы последних сообщений."
                        >
                          Ключевые слова
                        </HelpLabel>
                        <Textarea
                          id="parsing-keywords"
                          name="keywords"
                          rows={3}
                          placeholder={"ипотека\nновостройка\nзастройщик"}
                        />
                      </Field>
                      <div className="grid gap-3 sm:grid-cols-3">
                        <Field>
                          <FieldLabel htmlFor="parsing-keywords-mode">
                            Режим
                          </FieldLabel>
                          <NativeSelect
                            id="parsing-keywords-mode"
                            name="keywords_mode"
                            defaultValue="any"
                          >
                            <NativeSelectOption value="any">
                              Любое слово
                            </NativeSelectOption>
                            <NativeSelectOption value="all">
                              Все слова
                            </NativeSelectOption>
                            <NativeSelectOption value="phrase">
                              Фраза целиком
                            </NativeSelectOption>
                          </NativeSelect>
                        </Field>
                        <Field>
                          <FieldLabel htmlFor="parsing-date-from">
                            Дата от
                          </FieldLabel>
                          <Input
                            id="parsing-date-from"
                            name="date_from"
                            type="datetime-local"
                          />
                        </Field>
                        <Field>
                          <FieldLabel htmlFor="parsing-date-to">
                            Дата до
                          </FieldLabel>
                          <Input
                            id="parsing-date-to"
                            name="date_to"
                            type="datetime-local"
                          />
                        </Field>
                      </div>
                    </>
                  )}
                  <div className="grid gap-3 sm:grid-cols-2">
                    <Field>
                      <HelpLabel
                        htmlFor="parsing-min-comments"
                        tip={
                          mode === "message_users"
                            ? "Минимум совпавших сообщений от одного автора, чтобы пользователь попал в результат."
                            : "Фильтр для аудитории, собранной из комментариев. Если Telegram отдает только участников, фильтр сохранится в задании и применится при наличии данных активности."
                        }
                      >
                        {mode === "message_users"
                          ? "Мин. сообщений"
                          : "Мин. комментариев"}
                      </HelpLabel>
                      <Input
                        id="parsing-min-comments"
                        name={
                          mode === "message_users"
                            ? "min_messages"
                            : "min_comments"
                        }
                        type="number"
                        min={mode === "message_users" ? 1 : 0}
                        defaultValue={mode === "message_users" ? 1 : 0}
                      />
                    </Field>
                    {mode === "message_users" ? (
                      <Field>
                        <HelpLabel
                          htmlFor="parsing-message-limit"
                          tip="Сколько последних сообщений просканировать в источнике."
                        >
                          Сообщений сканировать
                        </HelpLabel>
                        <Input
                          id="parsing-message-limit"
                          name="message_limit"
                          type="number"
                          min={1}
                          max={10000}
                          defaultValue={500}
                        />
                      </Field>
                    ) : (
                      <Field>
                        <HelpLabel
                          htmlFor="parsing-active-days"
                          tip="Ограничить пользователей активностью за последние N дней, когда доступна история комментариев или сообщений."
                        >
                          Активность, дней
                        </HelpLabel>
                        <Input
                          id="parsing-active-days"
                          name="active_days"
                          type="number"
                          min={1}
                          placeholder="Например 30"
                        />
                      </Field>
                    )}
                  </div>
                  {mode === "users" && (
                    <Field>
                      <HelpLabel
                        htmlFor="parsing-min-messages"
                        tip="Минимум сообщений в fallback-сборе активной аудитории. Если Telegram отдает только список участников, фильтр применяется к тем, у кого есть активность."
                      >
                        Мин. сообщений
                      </HelpLabel>
                      <Input
                        id="parsing-min-messages"
                        name="min_messages"
                        type="number"
                        min={0}
                        defaultValue={0}
                      />
                    </Field>
                  )}
                  {mode === "message_users" && (
                    <Field>
                      <HelpLabel
                        htmlFor="parsing-user-limit"
                        tip="Максимум пользователей в результате после дедупликации."
                      >
                        Лимит пользователей
                      </HelpLabel>
                      <Input
                        id="parsing-user-limit"
                        name="user_limit"
                        type="number"
                        min={1}
                        max={5000}
                        defaultValue={500}
                      />
                    </Field>
                  )}
                  <label className="flex items-center gap-2 rounded-md border p-3 text-sm">
                    <Checkbox name="username_required" />
                    Только с username
                  </label>
                </>
              )}
              {mode === "comments" && (
                <>
                  <Field>
                    <HelpLabel
                      htmlFor="parsing-comment-keywords"
                      tip="Необязательный фильтр: оставить только комментарии, где есть одно из слов или фраз."
                    >
                      Ключевые слова
                    </HelpLabel>
                    <Textarea
                      id="parsing-comment-keywords"
                      name="keywords"
                      rows={2}
                      placeholder="Можно оставить пустым"
                    />
                  </Field>
                  <div className="grid gap-3 sm:grid-cols-2">
                    <Field>
                      <FieldLabel htmlFor="parsing-comment-date-from">
                        Дата от
                      </FieldLabel>
                      <Input
                        id="parsing-comment-date-from"
                        name="date_from"
                        type="datetime-local"
                      />
                    </Field>
                    <Field>
                      <FieldLabel htmlFor="parsing-comment-date-to">
                        Дата до
                      </FieldLabel>
                      <Input
                        id="parsing-comment-date-to"
                        name="date_to"
                        type="datetime-local"
                      />
                    </Field>
                  </div>
                  <Field>
                    <HelpLabel
                      htmlFor="parsing-post-id"
                      tip="Если указать id поста Telegram, будут собраны комментарии только под ним. Если оставить пустым, система возьмет последние посты."
                    >
                      ID поста
                    </HelpLabel>
                    <Input
                      id="parsing-post-id"
                      name="post_tg_message_id"
                      placeholder="Например: 1234"
                    />
                  </Field>
                  <div className="grid gap-3 sm:grid-cols-2">
                    <Field>
                      <HelpLabel
                        htmlFor="parsing-post-limit"
                        tip="Сколько последних постов проверить, если конкретный ID поста не указан."
                      >
                        Постов проверить
                      </HelpLabel>
                      <Input
                        id="parsing-post-limit"
                        name="post_limit"
                        type="number"
                        min={1}
                        max={100}
                        defaultValue={5}
                      />
                    </Field>
                    <Field>
                      <HelpLabel
                        htmlFor="parsing-comments-limit"
                        tip="Сколько комментариев собирать максимум под каждым постом."
                      >
                        Комментариев на пост
                      </HelpLabel>
                      <Input
                        id="parsing-comments-limit"
                        name="comments_per_post"
                        type="number"
                        min={1}
                        max={500}
                        defaultValue={50}
                      />
                    </Field>
                  </div>
                </>
              )}
              {(mode === "comments" || mode === "posts") && (
                <label className="flex items-start gap-2 rounded-md border p-3 text-sm">
                  <Checkbox name="ensure_membership" />
                  <span>
                    <span className="font-medium">
                      Проверить доступ к источнику
                    </span>
                    <span className="block text-muted-foreground">
                      Если источник недоступен без подписки, API попробует
                      получить доступ стандартным способом.
                    </span>
                  </span>
                </label>
              )}
            </FieldGroup>
            {error && (
              <Alert variant="destructive">
                <AlertTitle>Ошибка парсинга</AlertTitle>
                <AlertDescription>{error}</AlertDescription>
              </Alert>
            )}
            <Button type="submit" disabled={busy || !accounts.length}>
              {busy ? (
                <Loader2Icon className="size-4 animate-spin" />
              ) : (
                <SearchIcon className="size-4" />
              )}
              Запустить парсинг
            </Button>
            {!accounts.length && (
              <p className="text-sm text-muted-foreground">
                Сначала добавь Telegram аккаунт.
              </p>
            )}
          </form>

          <ParsingResultCard
            result={result}
            onDownloadJob={(jobId, format) => void onDownloadJob(jobId, format)}
          />
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

function parsingJobTypeLabel(type: string) {
  const labels: Record<string, string> = {
    channel_search: "Поиск каналов",
    channel_validate: "Проверка каналов",
    group_search: "Поиск групп",
    source_posts: "Посты источника",
    source_comments: "Комментарии",
    source_users: "Пользователи",
    message_users: "Авторы сообщений",
    dialogs: "Диалоги аккаунта",
  };
  return labels[type] || type;
}

function parsingJobStatusLabel(status: string) {
  const labels: Record<string, string> = {
    queued: "В очереди",
    running: "В работе",
    completed: "Завершена",
    failed: "Ошибка",
    cancelled: "Отменена",
    paused: "Пауза",
    draft: "Черновик",
  };
  return labels[status] || status;
}

function ParsingLimitControl({
  mode,
}: {
  mode: ParsingMode;
}) {
  const max =
    mode === "users"
      ? 5000
      : mode === "message_users"
        ? 5000
        : mode === "channels"
          ? 200
          : mode === "groups"
            ? 300
            : mode === "posts"
              ? 100
              : 500;
  const fallback =
    mode === "users"
      ? 200
      : mode === "message_users"
        ? 500
        : mode === "channels"
          ? 50
          : mode === "groups"
            ? 50
            : mode === "posts"
              ? 20
              : 100;
  const presets = (parsingLimitPresets[mode] || [fallback]).filter(
    (value) => value <= max,
  );
  const [selectedLimit, setSelectedLimit] = React.useState(fallback);
  const [customLimit, setCustomLimit] = React.useState("");
  React.useEffect(() => {
    setSelectedLimit(fallback);
    setCustomLimit("");
  }, [fallback, max]);
  const customValue = Number(customLimit);
  const effectiveLimit =
    customLimit.trim() && Number.isFinite(customValue)
      ? Math.min(max, Math.max(1, Math.trunc(customValue)))
      : selectedLimit;

  return (
    <Field>
      <HelpLabel
        htmlFor="parsing-limit-custom"
        tip="Максимальное количество объектов, которые API попробует собрать за один ручной запуск."
      >
        Лимит результатов
      </HelpLabel>
      <input type="hidden" name="limit" value={effectiveLimit} />
      <div className="flex flex-wrap gap-2">
        {presets.map((value) => (
          <Button
            key={value}
            type="button"
            variant={!customLimit && selectedLimit === value ? "default" : "outline"}
            className="min-w-14"
            onClick={() => {
              setSelectedLimit(value);
              setCustomLimit("");
            }}
          >
            {value}
          </Button>
        ))}
        <Button
          type="button"
          variant={!customLimit && selectedLimit === max ? "default" : "outline"}
          className="min-w-14"
          onClick={() => {
            setSelectedLimit(max);
            setCustomLimit("");
          }}
        >
          max
        </Button>
      </div>
      <div className="grid gap-2 sm:grid-cols-[160px_minmax(0,1fr)]">
        <Input
          id="parsing-limit-custom"
          type="number"
          min={1}
          max={max}
          placeholder="Свое число"
          value={customLimit}
          onChange={(event) => setCustomLimit(event.target.value)}
        />
        <FieldDescription className="self-center">
          Быстрый выбор или свое значение до {formatCompactNumber(max)}.
        </FieldDescription>
      </div>
    </Field>
  );
}

function parsingEntityLabel(type: string) {
  const labels: Record<string, string> = {
    channel: "Канал",
    group: "Группа",
    source: "Источник",
    user: "Пользователь",
    comment: "Комментарий",
    message: "Пост",
  };
  return labels[type] || type;
}

function parsingPayloadTitle(payload: Record<string, unknown>) {
  return String(
    payload.title ||
      payload.display_name ||
      payload.username ||
      payload.ref ||
      payload.tg_user_id ||
      payload.comment_tg_message_id ||
      payload.tg_message_id ||
      "без названия",
  );
}

function parsingPayloadDescription(payload: Record<string, unknown>) {
  const text = payload.text || payload.sample_messages || payload.matched_keywords || payload.raw;
  if (Array.isArray(text)) return text.join(", ");
  if (typeof text === "object" && text) return JSON.stringify(text);
  return String(text || "");
}

function channelSearchStatusLabel(status: string) {
  const labels: Record<string, string> = {
    found: "Найден",
    needs_telegram_validation: "Нужна проверка Telegram",
  };
  return labels[status] || status;
}

function ParsingJobsPanel({
  jobs,
  selectedJob,
  results,
  resultFilter,
  onResultFilterChange,
  onRefresh,
  onOpenJob,
  onDownloadJob,
  exportOnly,
}: {
  jobs: ParsingJob[];
  selectedJob: ParsingJobDetail | null;
  results: ParsingResult[];
  resultFilter: string;
  onResultFilterChange: (value: string) => void;
  onRefresh: () => Promise<void>;
  onOpenJob: (jobId: string) => void;
  onDownloadJob: (jobId: string, format: string) => void;
  exportOnly: boolean;
}) {
  const normalizedFilter = resultFilter.trim().toLowerCase();
  const visibleResults = normalizedFilter
    ? results.filter((row) =>
        JSON.stringify(row.payload || {})
          .toLowerCase()
          .includes(normalizedFilter),
      )
    : results;

  return (
    <div className="grid gap-4 lg:grid-cols-[minmax(0,1fr)_420px]">
      <Card className="border-dashed">
        <CardHeader>
          <CardTitle>{exportOnly ? "Экспорт" : "Задачи парсинга"}</CardTitle>
          <CardDescription>
            История запусков, прогресс, логи, результаты и выгрузки.
          </CardDescription>
          <CardAction>
            <Button type="button" variant="outline" size="sm" onClick={() => void onRefresh()}>
              <RefreshCwIcon />
              Обновить
            </Button>
          </CardAction>
        </CardHeader>
        <CardContent className="grid gap-3">
          {jobs.length ? (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Тип</TableHead>
                  <TableHead>Статус</TableHead>
                  <TableHead>Найдено</TableHead>
                  <TableHead>Создана</TableHead>
                  <TableHead className="text-right">Экспорт</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {jobs.map((job) => (
                  <TableRow
                    key={job.id}
                    className="cursor-pointer"
                    onClick={() => onOpenJob(job.id)}
                  >
                    <TableCell className="font-medium">
                      {parsingJobTypeLabel(job.type)}
                      <div className="text-xs text-muted-foreground">
                        {job.id.slice(0, 8)}
                      </div>
                    </TableCell>
                    <TableCell>
                      <Badge variant={job.status === "failed" ? "destructive" : "outline"}>
                        {parsingJobStatusLabel(job.status)}
                      </Badge>
                      {job.error_message && (
                        <div className="mt-1 max-w-64 truncate text-xs text-destructive" title={job.error_message}>
                          {job.error_message}
                        </div>
                      )}
                    </TableCell>
                    <TableCell>
                      <span className="font-medium tabular-nums">
                        {job.found_count}
                      </span>
                      <span className="text-muted-foreground">
                        {" "}
                        / сохранено {job.saved_count}
                      </span>
                    </TableCell>
                    <TableCell>{formatDateTimeRu(job.created_at)}</TableCell>
                    <TableCell>
                      <div
                        className="flex justify-end gap-1"
                        onClick={(event) => event.stopPropagation()}
                      >
                        {["csv", "json", "txt"].map((format) => (
                          <Button
                            key={format}
                            type="button"
                            variant="outline"
                            size="sm"
                            onClick={() => onDownloadJob(job.id, format)}
                          >
                            {format.toUpperCase()}
                          </Button>
                        ))}
                      </div>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          ) : (
            <EmptyState
              icon={<SearchIcon />}
              title="Задач пока нет"
              description="Запустите парсинг в любой вкладке, и задача появится здесь."
            />
          )}
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle>Детали</CardTitle>
          <CardDescription>
            {selectedJob
              ? `${parsingJobTypeLabel(selectedJob.type)} · ${parsingJobStatusLabel(selectedJob.status)}`
              : "Выберите задачу из списка"}
          </CardDescription>
        </CardHeader>
        <CardContent className="grid gap-4">
          {selectedJob ? (
            <>
              <div className="grid grid-cols-3 gap-2 rounded-md border p-3 text-sm">
                <StatMini label="Найдено" value={selectedJob.found_count} />
                <StatMini label="Сохранено" value={selectedJob.saved_count} />
                <StatMini label="Пропущено" value={selectedJob.skipped_count} />
              </div>
              <Field>
                <FieldLabel htmlFor="parsing-result-filter">
                  Фильтр результатов
                </FieldLabel>
                <Input
                  id="parsing-result-filter"
                  value={resultFilter}
                  onChange={(event) => onResultFilterChange(event.target.value)}
                  placeholder="username, текст, keyword"
                />
              </Field>
              <div className="max-h-72 overflow-auto rounded-md border">
                {visibleResults.length ? (
                  visibleResults.slice(0, 120).map((row) => (
                    <div key={row.id} className="border-b p-3 text-sm last:border-b-0">
                      <div className="mb-1 flex items-center justify-between gap-2">
                        <Badge variant="outline">{parsingEntityLabel(row.entity_type)}</Badge>
                        <span className="text-xs text-muted-foreground">
                          {formatDateTimeRu(row.created_at)}
                        </span>
                      </div>
                      <div className="font-medium">
                        {parsingPayloadTitle(row.payload)}
                      </div>
                      <p className="mt-1 line-clamp-3 text-muted-foreground">
                        {parsingPayloadDescription(row.payload)}
                      </p>
                    </div>
                  ))
                ) : (
                  <div className="p-6 text-center text-sm text-muted-foreground">
                    Результатов по фильтру нет.
                  </div>
                )}
              </div>
              <div className="max-h-48 overflow-auto rounded-md border">
                {selectedJob.logs.map((log) => (
                  <div key={log.id} className="border-b p-3 text-sm last:border-b-0">
                    <div className="flex items-center justify-between gap-2">
                      <Badge variant={log.level === "error" ? "destructive" : "outline"}>
                        {log.level}
                      </Badge>
                      <span className="text-xs text-muted-foreground">
                        {formatDateTimeRu(log.created_at)}
                      </span>
                    </div>
                    <p className="mt-1">{log.message}</p>
                  </div>
                ))}
              </div>
            </>
          ) : (
            <p className="text-sm text-muted-foreground">
              Кликните по задаче, чтобы увидеть результаты и логи.
            </p>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

function StatMini({ label, value }: { label: string; value: number }) {
  return (
    <div>
      <div className="text-xs text-muted-foreground">{label}</div>
      <div className="text-lg font-semibold tabular-nums">{value}</div>
    </div>
  );
}

function ParsingResultCard({
  result,
  onDownloadJob,
}: {
  result:
    | ParseSourceResponse
    | ParseDialogsResponse
    | ParseUsersResponse
    | ParseCommentsResponse
    | ChannelSearchResponse
    | GroupSearchResponse
    | null;
  onDownloadJob: (jobId: string, format: string) => void;
}) {
  if (!result) {
    return (
      <Card className="min-h-[520px]">
        <CardContent className="grid min-h-[520px] place-items-center">
          <Empty>
            <EmptyHeader>
              <EmptyMedia variant="icon">
                <SearchIcon className="size-5" />
              </EmptyMedia>
              <EmptyTitle>Результатов пока нет</EmptyTitle>
              <EmptyDescription>
                Запусти парсинг, и здесь появятся найденные данные.
              </EmptyDescription>
            </EmptyHeader>
          </Empty>
        </CardContent>
      </Card>
    );
  }

  if ("items" in result) {
    const firstItem = result.items[0] as Record<string, unknown> | undefined;
    const isDialogResult = Boolean(firstItem && "type" in firstItem);
    const title = isDialogResult
      ? `Диалоги: ${result.count}`
      : `Найдено: ${result.count}`;
    return (
      <Card className="max-h-[720px] min-h-[520px] overflow-hidden">
        <CardHeader>
          <CardTitle>{title}</CardTitle>
          {result.job_id && (
            <CardDescription className="flex flex-wrap items-center gap-2">
              <span>Задача {result.job_id}</span>
              {["csv", "json", "txt"].map((format) => (
                <Button
                  key={format}
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={() => onDownloadJob(result.job_id || "", format)}
                >
                  {format.toUpperCase()}
                </Button>
              ))}
            </CardDescription>
          )}
        </CardHeader>
        <CardContent className="max-h-[600px] overflow-auto">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Название</TableHead>
                <TableHead>Username</TableHead>
                <TableHead>Участники</TableHead>
                <TableHead>Сигнал</TableHead>
                <TableHead>Последнее</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {result.items.map((item, index) => {
                const row = item as ParsedDialogItem & Partial<ChannelSearchItem & GroupSearchItem>;
                const signalStatus = row.status;
                const activityScore = row.activity_score;
                return (
                <TableRow key={`${row.tg_id || row.ref || index}`}>
                  <TableCell className="font-medium">
                    <div>{row.title || "без названия"}</div>
                    <div className="text-xs text-muted-foreground">
                      {isDialogResult ? dialogKindRu(row.type) : row.ref}
                    </div>
                  </TableCell>
                  <TableCell>
                    {row.username ? `@${row.username}` : "нет"}
                  </TableCell>
                  <TableCell>{row.participants_count ?? "нет"}</TableCell>
                  <TableCell>
                    {signalStatus ? (
                      <Badge variant="outline">
                        {channelSearchStatusLabel(signalStatus)}
                      </Badge>
                    ) : activityScore != null ? (
                      <Badge variant="outline">Активность {activityScore}</Badge>
                    ) : (
                      <span className="text-muted-foreground">нет</span>
                    )}
                  </TableCell>
                  <TableCell>
                    {formatDateTimeRu(row.last_message_at)}
                  </TableCell>
                </TableRow>
              );
              })}
            </TableBody>
          </Table>
        </CardContent>
      </Card>
    );
  }

  if ("users" in result) {
    return (
      <Card className="max-h-[720px] min-h-[520px] overflow-hidden">
        <CardHeader>
          <CardTitle>Пользователи: {result.count}</CardTitle>
          <CardDescription className="flex flex-wrap items-center gap-2">
            {[result.source_ref, result.job_id ? `задача ${result.job_id}` : ""]
              .filter(Boolean)
              .join(" · ")}
            {result.job_id && ["csv", "json", "txt"].map((format) => (
              <Button
                key={format}
                type="button"
                variant="outline"
                size="sm"
                onClick={() => onDownloadJob(result.job_id || "", format)}
              >
                {format.toUpperCase()}
              </Button>
            ))}
          </CardDescription>
        </CardHeader>
        <CardContent className="max-h-[600px] overflow-auto">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Имя</TableHead>
                <TableHead>Username</TableHead>
                <TableHead>Активность</TableHead>
                <TableHead>Ключи</TableHead>
                <TableHead>Последнее</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {result.users.map((user) => (
                <TableRow key={user.tg_user_id}>
                  <TableCell className="font-medium">
                    {user.display_name || "без имени"}
                  </TableCell>
                  <TableCell>
                    {user.username ? `@${user.username}` : "нет"}
                  </TableCell>
                  <TableCell>
                    <span className="whitespace-nowrap">
                      Сообщений: {user.messages_count || 0}
                    </span>
                    <span className="block whitespace-nowrap text-muted-foreground">
                      Комментариев: {user.comments_count || 0}
                    </span>
                  </TableCell>
                  <TableCell>
                    {(user.matched_keywords || []).length
                      ? user.matched_keywords?.join(", ")
                      : "нет"}
                  </TableCell>
                  <TableCell>
                    {formatDateTimeRu(user.last_activity_at)}
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </CardContent>
      </Card>
    );
  }

  if ("comments" in result) {
    return (
      <Card className="max-h-[720px] min-h-[520px] overflow-hidden">
        <CardHeader>
          <CardTitle>Комментарии: {result.count}</CardTitle>
          <CardDescription className="flex flex-wrap items-center gap-2">
            {[result.source_ref, result.job_id ? `задача ${result.job_id}` : ""]
              .filter(Boolean)
              .join(" · ")}
            {result.job_id && ["csv", "json", "txt"].map((format) => (
              <Button
                key={format}
                type="button"
                variant="outline"
                size="sm"
                onClick={() => onDownloadJob(result.job_id || "", format)}
              >
                {format.toUpperCase()}
              </Button>
            ))}
          </CardDescription>
        </CardHeader>
        <CardContent className="grid max-h-[600px] gap-3 overflow-auto">
          {result.comments.map((comment) => (
            <div
              key={`${comment.post_tg_message_id}-${comment.comment_tg_message_id}`}
              className="rounded-lg border p-3"
            >
              <div className="mb-2 flex flex-wrap gap-2 text-xs text-muted-foreground">
                <Badge variant="outline">
                  Пост {comment.post_tg_message_id}
                </Badge>
                <span>Комментарий {comment.comment_tg_message_id}</span>
                <span>{formatDateTimeRu(comment.published_at)}</span>
              </div>
              <p className="whitespace-pre-wrap text-sm leading-relaxed">
                {comment.text}
              </p>
            </div>
          ))}
        </CardContent>
      </Card>
    );
  }

  return (
    <Card className="max-h-[720px] min-h-[520px] overflow-hidden">
      <CardHeader>
        <CardTitle>Посты: {result.created}</CardTitle>
        {result.job_id && <CardDescription>Задача {result.job_id}</CardDescription>}
      </CardHeader>
      <CardContent className="grid max-h-[600px] gap-3 overflow-auto">
        {result.messages.map((message) => (
          <div key={message.id} className="rounded-lg border p-3">
            <div className="mb-2 flex flex-wrap gap-2 text-xs text-muted-foreground">
              <Badge variant="outline">ID {message.tg_message_id}</Badge>
              <span>{formatDateTimeRu(message.published_at)}</span>
              <span>Комментариев: {message.replies_count}</span>
            </div>
            <p className="whitespace-pre-wrap text-sm leading-relaxed">
              {message.text || "без текста"}
            </p>
          </div>
        ))}
      </CardContent>
    </Card>
  );
}

function CampaignRowActions({
  campaign,
  accounts,
  editSources,
  sourceUsage,
  accountUsage,
  actionBusy,
  isRunPending,
  safety,
  folders,
  currentFolder,
  onStartCampaignRun,
  onCampaignDryRun,
  onPatchCampaign,
  onCampaignAction,
  stopLabel = "Остановить кампанию",
}: {
  campaign: Campaign;
  accounts: TelegramAccount[];
  editSources: Source[];
  sourceUsage: SourceUsage;
  accountUsage: AccountUsage;
  actionBusy: string | null;
  isRunPending: boolean;
  safety: CampaignClientSafety;
  folders?: string[];
  currentFolder?: string;
  onStartCampaignRun: (campaignId: string) => Promise<void>;
  onCampaignDryRun: (campaignId: string) => Promise<void>;
  onPatchCampaign: (
    campaignId: string,
    payload: Record<string, unknown>,
  ) => Promise<void>;
  onCampaignAction: (
    campaignId: string,
    action: "stop" | "archive" | "restore" | "delete",
  ) => Promise<void>;
  stopLabel?: string;
}) {
  const availableFolders = uniqueFolderNames([
    ...(folders || []),
    currentFolder || "",
    COMMENT_CAMPAIGN_DEFAULT_FOLDER,
  ]);
  const normalizedCurrentFolder = currentFolder || COMMENT_CAMPAIGN_DEFAULT_FOLDER;

  function handleMoveFolder(nextFolder: string) {
    if (!nextFolder || nextFolder === normalizedCurrentFolder) {
      return;
    }
    void onPatchCampaign(campaign.id, {
      config: {
        ...campaign.config,
        folder: nextFolder,
      },
    });
  }

  return (
    <div
      className="flex min-w-0 items-center justify-end gap-1.5 whitespace-nowrap"
      onClick={(event) => event.stopPropagation()}
    >
      <Button
        variant="outline"
        size="sm"
        className="min-w-[108px]"
        disabled={actionBusy === `campaign-dry-run-${campaign.id}`}
        onClick={() => void onCampaignDryRun(campaign.id)}
      >
        {actionBusy === `campaign-dry-run-${campaign.id}` ? (
          <Loader2Icon className="size-4 animate-spin" />
        ) : (
          <ShieldCheckIcon />
        )}
        Проверка
      </Button>
      <Button
        variant="default"
        size="sm"
        className="min-w-[108px]"
        disabled={
          !isCampaignRunnable(campaign) || isRunPending || !safety.canStart
        }
        onClick={() => void onStartCampaignRun(campaign.id)}
      >
        {isRunPending ? (
          <Loader2Icon className="size-4 animate-spin" />
        ) : (
          <PlayIcon />
        )}
        Запуск
      </Button>
      <CampaignEditDialog
        campaign={campaign}
        accounts={accounts}
        sources={editSources}
        sourceUsage={sourceUsage}
        accountUsage={accountUsage}
        isBusy={actionBusy === `campaign-edit-${campaign.id}`}
        onPatchCampaign={onPatchCampaign}
        iconOnly
      />
      <DropdownMenu>
        <DropdownMenuTrigger asChild>
          <Button
            variant="outline"
            size="icon"
            disabled={
              actionBusy === `campaign-edit-${campaign.id}` ||
              availableFolders.length <= 1
            }
            title="Сменить папку"
            aria-label="Сменить папку"
          >
            <FolderInputIcon />
          </Button>
        </DropdownMenuTrigger>
        <DropdownMenuContent align="end" className="w-48">
          {availableFolders.map((folder) => (
            <DropdownMenuItem
              key={folder}
              disabled={folder === normalizedCurrentFolder}
              onSelect={() => handleMoveFolder(folder)}
            >
              {folder === normalizedCurrentFolder ? (
                <CheckIcon />
              ) : (
                <span className="size-4" />
              )}
              <span className="truncate">{folder}</span>
            </DropdownMenuItem>
          ))}
        </DropdownMenuContent>
      </DropdownMenu>
      <Button
        variant="outline"
        size="icon"
        disabled={
          actionBusy === `campaign-stop-${campaign.id}` ||
          !isCampaignStoppable(campaign.status)
        }
        title={stopLabel}
        aria-label={stopLabel}
        onClick={() => void onCampaignAction(campaign.id, "stop")}
      >
        <PauseCircleIcon />
      </Button>
      <Button
        variant="outline"
        size="sm"
        className="min-w-28"
        disabled={actionBusy === `campaign-archive-${campaign.id}`}
        onClick={() => void onCampaignAction(campaign.id, "archive")}
      >
        <ArchiveIcon />
        Архив
      </Button>
      <Button
        variant="ghost"
        size="icon"
        disabled={actionBusy === `campaign-delete-${campaign.id}`}
        title="Удалить"
        aria-label="Удалить"
        onClick={() => void onCampaignAction(campaign.id, "delete")}
      >
        <Trash2Icon />
      </Button>
    </div>
  );
}

function CampaignsScreen({
  campaignType,
  folderStorageScope,
  title,
  description,
  campaigns,
  accounts,
  campaignAccounts,
  sources,
  sourceFolders,
  actionBusy,
  campaignRunPendingIds,
  onCreateCampaign,
  onOpenChannelBase,
  onCreateNeuroChatCampaign,
  onCreateNeuroDialogCampaign,
  onCreateMessageBroadcastCampaign,
  onStartCampaignRun,
  onCampaignDryRun,
  onLoadCampaignDetails,
  onDownloadCampaignXlsx,
  onDownloadCampaignFolderXlsx,
  onSendCampaignDraft,
  onPatchCampaign,
  onCampaignAction,
}: {
  campaignType:
    | "comment_posts"
    | "neuro_chat"
    | "neuro_dialog"
    | "message_broadcast";
  folderStorageScope: string;
  title: string;
  description: string;
  campaigns: Campaign[];
  accounts: TelegramAccount[];
  campaignAccounts: TelegramAccount[];
  sources: Source[];
  sourceFolders: SourceFolder[];
  actionBusy: string | null;
  campaignRunPendingIds: string[];
  onCreateCampaign: (payload: CampaignCreatePayload) => Promise<void>;
  onOpenChannelBase?: () => void;
  onCreateNeuroChatCampaign: (
    payload: NeuroChatCampaignCreatePayload,
  ) => Promise<void>;
  onCreateNeuroDialogCampaign: (
    payload: NeuroDialogCampaignCreatePayload,
  ) => Promise<void>;
  onCreateMessageBroadcastCampaign: (
    payload: MessageBroadcastCampaignCreatePayload,
  ) => Promise<void>;
  onStartCampaignRun: (campaignId: string) => Promise<void>;
  onCampaignDryRun: (campaignId: string) => Promise<void>;
  onLoadCampaignDetails: (campaignId: string) => Promise<CampaignDetails>;
  onDownloadCampaignXlsx: (
    campaignId: string,
    campaignName: string,
    campaignType?: string,
  ) => Promise<void>;
  onDownloadCampaignFolderXlsx: (
    campaignType: string,
    folder: string,
  ) => Promise<void>;
  onSendCampaignDraft: (campaignId: string, commentId: string) => Promise<void>;
  onPatchCampaign: (
    campaignId: string,
    payload: Record<string, unknown>,
  ) => Promise<void>;
  onCampaignAction: (
    campaignId: string,
    action: "stop" | "archive" | "restore" | "delete",
  ) => Promise<void>;
}) {
  const visibleCampaigns = campaigns.filter(
    (campaign) =>
      campaign.type === campaignType && campaign.status !== "archived",
  );
  const archivedCampaigns = campaigns.filter(
    (campaign) =>
      campaign.type === campaignType && campaign.status === "archived",
  );
  const eligibleSources = sourcesForCampaignType(campaignType, sources);
  const sourceUsage = sourceUsageForCampaigns(visibleCampaigns, campaignType);
  const accountUsage = accountUsageForCampaigns(
    campaigns,
    undefined,
    campaignType,
  );
  const [showArchive, setShowArchive] = React.useState(false);
  const [openCampaignId, setOpenCampaignId] = React.useState<string | null>(
    null,
  );
  const foldersEnabled = true;
  const folderStorageKey = React.useMemo(
    () => commentCampaignFoldersStorageKey(folderStorageScope),
    [folderStorageScope],
  );
  const [customFolders, setCustomFolders] = React.useState<string[]>([]);
  const [activeFolder, setActiveFolder] = React.useState(
    COMMENT_CAMPAIGN_DEFAULT_FOLDER,
  );
  const shouldPickInitialFolderRef = React.useRef(true);

  const persistCustomFolders = React.useCallback(
    (folders: string[]) => {
      const nextFolders = uniqueFolderNames(folders);
      setCustomFolders(nextFolders);
      storeCommentCampaignFolders(folderStorageKey, nextFolders);
      return nextFolders;
    },
    [folderStorageKey],
  );

  React.useEffect(() => {
    if (!foldersEnabled) return;
    shouldPickInitialFolderRef.current = true;
    setCustomFolders(readStoredCommentCampaignFolders(folderStorageKey));
    setActiveFolder(COMMENT_CAMPAIGN_DEFAULT_FOLDER);
  }, [folderStorageKey, foldersEnabled]);

  const explicitCampaignFolders = React.useMemo(
    () =>
      uniqueFolderNames(
        visibleCampaigns
          .map((campaign) => explicitCommentCampaignFolder(campaign))
          .filter(Boolean),
      ),
    [visibleCampaigns],
  );
  const campaignFolderFallback = COMMENT_CAMPAIGN_DEFAULT_FOLDER;

  React.useEffect(() => {
    if (!foldersEnabled || !explicitCampaignFolders.length) return;
    const missingFolders = explicitCampaignFolders.filter(
      (folder) => !customFolders.includes(folder),
    );
    if (!missingFolders.length) return;
    persistCustomFolders([...customFolders, ...missingFolders]);
  }, [
    customFolders,
    explicitCampaignFolders,
    foldersEnabled,
    persistCustomFolders,
  ]);

  const campaignFolders = React.useMemo(() => {
    if (!foldersEnabled) return [];
    return uniqueFolderNames([
      ...visibleCampaigns.map((campaign) =>
        commentCampaignFolder(campaign, campaignFolderFallback),
      ),
      ...customFolders,
      campaignFolderFallback,
    ]);
  }, [campaignFolderFallback, customFolders, foldersEnabled, visibleCampaigns]);

  React.useEffect(() => {
    if (!foldersEnabled || !campaignFolders.length) return;
    const preferredFolder = preferredCampaignFolder(
      visibleCampaigns,
      campaignFolders,
      campaignFolderFallback,
    );
    if (shouldPickInitialFolderRef.current) {
      if (!visibleCampaigns.length) return;
      shouldPickInitialFolderRef.current = false;
      if (activeFolder !== preferredFolder) {
        setActiveFolder(preferredFolder);
      }
      return;
    }
    const activeFolderHasCampaigns = visibleCampaigns.some(
      (campaign) =>
        commentCampaignFolder(campaign, campaignFolderFallback) === activeFolder,
    );
    const preferredFolderHasCampaigns = visibleCampaigns.some(
      (campaign) =>
        commentCampaignFolder(campaign, campaignFolderFallback) ===
        preferredFolder,
    );
    if (!campaignFolders.includes(activeFolder)) {
      setActiveFolder(preferredFolder);
    } else if (
      activeFolder === campaignFolderFallback &&
      !activeFolderHasCampaigns &&
      preferredFolderHasCampaigns &&
      preferredFolder !== activeFolder
    ) {
      setActiveFolder(preferredFolder);
    }
  }, [
    activeFolder,
    campaignFolderFallback,
    campaignFolders,
    foldersEnabled,
    visibleCampaigns,
  ]);

  const folderCampaigns = foldersEnabled
    ? visibleCampaigns.filter(
        (campaign) =>
          commentCampaignFolder(campaign, campaignFolderFallback) ===
          activeFolder,
      )
    : visibleCampaigns;
  const folderSummary = campaignFolderSummary(folderCampaigns);

  function handleCreateFolder(name: string) {
    const normalized = normalizeCampaignFolderName(name);
    if (!normalized) return;
    persistCustomFolders([...customFolders, normalized]);
    setActiveFolder(normalized);
  }

  async function handleRenameFolder() {
    if (!foldersEnabled || activeFolder === COMMENT_CAMPAIGN_DEFAULT_FOLDER) {
      return;
    }
    const nextName = normalizeCampaignFolderName(
      window.prompt("Новое название папки", activeFolder),
    );
    if (!nextName || nextName === activeFolder) return;
    if (campaignFolders.includes(nextName)) {
      window.alert("Папка с таким названием уже есть.");
      return;
    }

    persistCustomFolders(
      customFolders.map((folder) => (folder === activeFolder ? nextName : folder)),
    );
    setActiveFolder(nextName);

    const campaignsToMove = visibleCampaigns.filter(
      (campaign) =>
        commentCampaignFolder(campaign, campaignFolderFallback) === activeFolder,
    );
    for (const campaign of campaignsToMove) {
      await onPatchCampaign(campaign.id, {
        config: {
          ...campaign.config,
          folder: nextName,
        },
      });
    }
  }

  async function handleDeleteFolder() {
    if (!foldersEnabled || activeFolder === COMMENT_CAMPAIGN_DEFAULT_FOLDER) {
      return;
    }
    const campaignsToMove = visibleCampaigns.filter(
      (campaign) =>
        commentCampaignFolder(campaign, campaignFolderFallback) === activeFolder,
    );
    const confirmed = window.confirm(
      campaignsToMove.length
        ? `Удалить папку «${activeFolder}»? ${campaignsToMove.length} кампаний будут перенесены в «${COMMENT_CAMPAIGN_DEFAULT_FOLDER}».`
        : `Удалить пустую папку «${activeFolder}»?`,
    );
    if (!confirmed) return;

    persistCustomFolders(
      customFolders.filter((folder) => folder !== activeFolder),
    );
    setActiveFolder(COMMENT_CAMPAIGN_DEFAULT_FOLDER);

    for (const campaign of campaignsToMove) {
      await onPatchCampaign(campaign.id, {
        config: {
          ...campaign.config,
          folder: COMMENT_CAMPAIGN_DEFAULT_FOLDER,
        },
      });
    }
  }

  if (showArchive) {
    return (
      <CampaignArchiveScreen
        title={title}
        campaigns={archivedCampaigns}
        accounts={accounts}
        sources={sources}
        actionBusy={actionBusy}
        onBack={() => setShowArchive(false)}
        onLoadCampaignDetails={onLoadCampaignDetails}
        onDownloadCampaignXlsx={onDownloadCampaignXlsx}
        onSendCampaignDraft={onSendCampaignDraft}
        onCampaignAction={onCampaignAction}
      />
    );
  }

  return (
    <Card className="max-w-full">
      <CardHeader className="min-w-0">
        <CardTitle>{title}</CardTitle>
        <CardDescription>{description}</CardDescription>
        <CardAction className="max-w-full">
          <div className="flex flex-wrap items-center justify-end gap-2">
            <Button
              type="button"
              variant="outline"
              onClick={() => setShowArchive(true)}
            >
              <ArchiveIcon />
              Архив
              {archivedCampaigns.length ? ` · ${archivedCampaigns.length}` : ""}
            </Button>
            {campaignType === "comment_posts" && (
              <CampaignCreateDialog
                accounts={accounts}
                sources={eligibleSources}
                sourceFolders={sourceFolders}
                sourceUsage={sourceUsage}
                accountUsage={accountUsage}
                folder={activeFolder}
                isBusy={actionBusy === "campaign-create"}
                onCreateCampaign={onCreateCampaign}
                onOpenChannelBase={onOpenChannelBase}
              />
            )}
            {campaignType === "neuro_chat" && (
              <NeuroChatCreateDialog
                accounts={accounts}
                sources={eligibleSources}
                sourceFolders={sourceFolders}
                sourceUsage={sourceUsage}
                accountUsage={accountUsage}
                folder={activeFolder}
                isBusy={actionBusy === "neuro-chat-create"}
                onCreate={onCreateNeuroChatCampaign}
              />
            )}
            {campaignType === "neuro_dialog" && (
              <NeuroDialogCreateDialog
                accounts={accounts}
                sources={eligibleSources}
                sourceFolders={sourceFolders}
                sourceUsage={sourceUsage}
                accountUsage={accountUsage}
                folder={activeFolder}
                isBusy={actionBusy === "neuro-dialog-create"}
                onCreate={onCreateNeuroDialogCampaign}
              />
            )}
            {campaignType === "message_broadcast" && (
              <MessageBroadcastCreateDialog
                accounts={accounts}
                sources={eligibleSources}
                sourceFolders={sourceFolders}
                sourceUsage={sourceUsage}
                accountUsage={accountUsage}
                folder={activeFolder}
                isBusy={actionBusy === "message-broadcast-create"}
                onCreate={onCreateMessageBroadcastCampaign}
              />
            )}
          </div>
        </CardAction>
      </CardHeader>
      <CardContent>
        {foldersEnabled && (
          <div className="mb-4 flex flex-wrap items-center justify-between gap-3">
            <Tabs
              value={activeFolder}
              onValueChange={(folder) => {
                shouldPickInitialFolderRef.current = false;
                setActiveFolder(folder);
              }}
            >
              <TabsList className="h-auto max-w-full flex-wrap justify-start">
                {campaignFolders.map((folder) => (
                  <TabsTrigger key={folder} value={folder}>
                    {folder}
                    <span className="ml-1 text-muted-foreground">
                      {
                        visibleCampaigns.filter(
                          (campaign) =>
                            commentCampaignFolder(
                              campaign,
                              campaignFolderFallback,
                            ) === folder,
                        ).length
                      }
                    </span>
                  </TabsTrigger>
                ))}
              </TabsList>
            </Tabs>
            <div className="flex flex-wrap items-center gap-2">
              <Button
                type="button"
                variant="outline"
                size="icon"
                disabled={activeFolder === COMMENT_CAMPAIGN_DEFAULT_FOLDER}
                title="Переименовать папку"
                aria-label="Переименовать папку"
                onClick={() => void handleRenameFolder()}
              >
                <Edit3Icon />
              </Button>
              <Button
                type="button"
                variant="outline"
                size="icon"
                disabled={activeFolder === COMMENT_CAMPAIGN_DEFAULT_FOLDER}
                title="Удалить папку"
                aria-label="Удалить папку"
                onClick={() => void handleDeleteFolder()}
              >
                <Trash2Icon />
              </Button>
              <Button
                type="button"
                variant="outline"
                size="sm"
                disabled={
                  !folderCampaigns.length ||
                  actionBusy ===
                    `campaign-folder-report-${campaignType}-${activeFolder}`
                }
                onClick={() =>
                  void onDownloadCampaignFolderXlsx(campaignType, activeFolder)
                }
              >
                {actionBusy ===
                `campaign-folder-report-${campaignType}-${activeFolder}` ? (
                  <Loader2Icon className="size-4 animate-spin" />
                ) : (
                  <DownloadIcon />
                )}
                Отчет XLSX
              </Button>
              <CampaignFolderCreateDialog onCreate={handleCreateFolder} />
            </div>
          </div>
        )}
        {folderCampaigns.length ? (
          <Table className="w-full min-w-[1060px] table-fixed">
            <colgroup>
              <col className="w-[180px]" />
              <col className="w-[95px]" />
              <col className="w-[220px]" />
              <col className="w-[75px]" />
              <col />
            </colgroup>
            <TableHeader>
              <TableRow>
                <TableHead className="w-[180px]">Кампания</TableHead>
                <TableHead className="w-[95px]">Статус</TableHead>
                <TableHead className="w-[220px]">Контур</TableHead>
                <TableHead className="w-[75px] text-center">Отправлено</TableHead>
                <TableHead className="text-right">Действия</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {folderCampaigns.map((campaign) => {
                const isRunPending = campaignRunPendingIds.includes(
                  campaign.id,
                );
                const safety = campaignClientSafety(campaign, campaignAccounts);
                return (
                  <TableRow
                    key={campaign.id}
                    className="cursor-pointer"
                    onClick={() => setOpenCampaignId(campaign.id)}
                  >
                    <TableCell className="w-[180px] max-w-[180px]">
                      <div
                        className="truncate font-medium"
                        title={campaign.name}
                      >
                        {campaign.name}
                      </div>
                    </TableCell>
                    <TableCell>
                      <Badge variant="outline">
                        {statusLabel(
                          campaign.status === "paused" ? "paused" : campaign.active_run_status || campaign.status,
                        )}
                      </Badge>
                    </TableCell>
                    <TableCell className="w-[220px] max-w-[220px] text-sm text-muted-foreground">
                      <div className="grid gap-1">
                        <span
                          className="truncate"
                          title={campaignScope(
                            campaign,
                            campaignAccounts,
                            sources,
                          )}
                        >
                          {campaignScope(campaign, campaignAccounts, sources)}
                        </span>
                        <CampaignReplacementQueueBadge campaign={campaign} accounts={campaignAccounts} />
                        {!campaignReplacementPreparing(campaign) && <CampaignSafetyBadge safety={safety} />}
                      </div>
                    </TableCell>
                    <TableCell className="w-[75px] text-center">
                      <span className="font-medium tabular-nums">
                        {Number(campaign.sent_count || 0)}
                      </span>
                    </TableCell>
                    <TableCell className="text-right">
                      <CampaignDetailDialog
                        campaign={campaign}
                        accounts={campaignAccounts}
                        sources={sources}
                        open={openCampaignId === campaign.id}
                        onOpenChange={(open) =>
                          setOpenCampaignId(open ? campaign.id : null)
                        }
                        onLoadDetails={onLoadCampaignDetails}
                        onDownloadXlsx={onDownloadCampaignXlsx}
                        onSendDraft={onSendCampaignDraft}
                        actionBusy={actionBusy}
                      />
                      <div
                        className="flex min-w-0 items-center justify-end whitespace-nowrap"
                        onClick={(event) => event.stopPropagation()}
                      >
                        <CampaignRowActions
                          campaign={campaign}
                          accounts={accounts}
                          editSources={eligibleSources}
                          sourceUsage={sourceUsageForCampaigns(
                            visibleCampaigns,
                            campaignType,
                            campaign.id,
                          )}
                          accountUsage={accountUsageForCampaigns(
                            campaigns,
                            campaign.id,
                            campaignType,
                          )}
                          actionBusy={actionBusy}
                          isRunPending={isRunPending}
                          safety={safety}
                          folders={campaignFolders}
                          currentFolder={commentCampaignFolder(
                            campaign,
                            campaignFolderFallback,
                          )}
                          onStartCampaignRun={onStartCampaignRun}
                          onCampaignDryRun={onCampaignDryRun}
                          onPatchCampaign={onPatchCampaign}
                          onCampaignAction={onCampaignAction}
                        />
                      </div>
                    </TableCell>
                  </TableRow>
                );
              })}
            </TableBody>
          </Table>
        ) : (
          <EmptyState
            icon={<BotIcon />}
            title="Пока пусто"
            description={
              foldersEnabled
                ? "Создайте кампанию в этой папке или перенесите сюда существующую."
                : "Создайте первый запуск в этом разделе."
            }
          />
        )}
        {foldersEnabled && (
          <div className="mt-4 grid gap-3 rounded-md border bg-muted/20 p-3 sm:grid-cols-4">
            <CampaignFolderStat
              label="Кампаний"
              value={folderSummary.campaigns}
            />
            <CampaignFolderStat
              label="Запущено"
              value={folderSummary.running}
            />
            <CampaignFolderStat
              label="Источников"
              value={folderSummary.sources}
            />
            <CampaignFolderStat label="Отправлено" value={folderSummary.sent} />
          </div>
        )}
        {!eligibleSources.length && (
          <p className="mt-4 text-sm text-muted-foreground">
            {sourceRequirementText(campaignType)}
          </p>
        )}
      </CardContent>
    </Card>
  );
}

