function sourcePayloadFromRef(
  rawRef: string,
  title: string | null,
): SourceCreatePayload {
  const ref = rawRef.trim();
  const isUrl =
    ref.includes("://") ||
    ref.startsWith("t.me/") ||
    ref.startsWith("telegram.me/");
  if (isUrl) {
    const url = ref.includes("://") ? ref : `https://${ref}`;
    return { type: "unknown", url, title };
  }

  return {
    type: "unknown",
    username: ref.replace(/^@/, "").trim() || null,
    title,
  };
}

function splitSourceRefs(rawRefs: string) {
  return Array.from(
    new Set(
      rawRefs
        .split(/[\s,;]+/)
        .map((ref) => ref.trim())
        .filter(Boolean),
    ),
  );
}

function telegramMessageUrl(peerRef: string, messageId: string) {
  const ref = peerRef.trim();
  if (!ref || !messageId) return "";
  const username = ref
    .replace(/^https?:\/\/t\.me\//, "")
    .replace(/^t\.me\//, "")
    .replace(/^@/, "")
    .split("/")[0];
  if (!username || username.startsWith("+") || /^-?\d+$/.test(username))
    return "";
  return `https://t.me/${username}/${messageId}`;
}

