function campaignDetailReport(
  campaign: Campaign,
  details: CampaignDetails | null,
) {
  if (campaign.type === "comment_posts") {
    return {
      total: details?.report?.total_count ?? 0,
      drafts: details?.report?.draft_count ?? 0,
      sent: details?.report?.sent_count ?? 0,
      failed: details?.report?.failed_count ?? 0,
    };
  }
  const actions = (details?.actions ?? []).filter(
    (action) =>
      action.action_type.startsWith("neuro_") ||
      action.action_type === "message_broadcast" ||
      action.action_type === "set_reaction",
  );
  return {
    total: actions.length,
    drafts: actions.filter(
      (action) => action.status === "generated" || action.status === "draft",
    ).length,
    sent: actions.filter(
      (action) => action.status === "succeeded" || action.status === "sent",
    ).length,
    failed: actions.filter((action) => action.status === "failed").length,
  };
}

function campaignTargetLabels(campaign: Campaign, sources: Source[]) {
  const sourceLabels = stringList(campaign.config.source_ids).map((id) =>
    sourceNameById(sources, id),
  );
  const targetRefs = stringList(campaign.config.target_refs);
  return sourceLabels.length ? sourceLabels : targetRefs;
}

function normalizeCampaignFolderName(value: unknown) {
  return String(value || "")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, 80);
}

function explicitCommentCampaignFolder(campaign: Campaign) {
  return normalizeCampaignFolderName(campaign.config.folder);
}

function commentCampaignFolder(
  campaign: Campaign,
  fallback = COMMENT_CAMPAIGN_DEFAULT_FOLDER,
) {
  return explicitCommentCampaignFolder(campaign) || fallback;
}

function uniqueFolderNames(values: string[]) {
  const seen = new Set<string>();
  const folders: string[] = [];
  for (const value of values) {
    const folder = normalizeCampaignFolderName(value);
    if (!folder || seen.has(folder)) continue;
    seen.add(folder);
    folders.push(folder);
  }
  return folders;
}

function preferredCampaignFolder(
  campaigns: Campaign[],
  folders: string[],
  fallback: string,
) {
  const folderCounts = new Map<string, number>();
  for (const campaign of campaigns) {
    const folder = commentCampaignFolder(campaign, fallback);
    folderCounts.set(folder, (folderCounts.get(folder) || 0) + 1);
  }
  return folders.find((folder) => (folderCounts.get(folder) || 0) > 0) || folders[0] || fallback;
}

function commentCampaignFoldersStorageKey(scope: string) {
  const normalizedScope = normalizeCampaignFolderName(scope) || "default";
  return `${COMMENT_CAMPAIGN_FOLDERS_STORAGE_KEY}:${normalizedScope}`;
}

function readStoredCommentCampaignFolders(storageKey: string) {
  if (typeof window === "undefined") return [];
  try {
    window.localStorage.removeItem(COMMENT_CAMPAIGN_FOLDERS_STORAGE_KEY);
    const raw = window.localStorage.getItem(storageKey);
    const parsed = raw ? JSON.parse(raw) : [];
    return Array.isArray(parsed)
      ? uniqueFolderNames(parsed.map((item) => String(item)))
      : [];
  } catch {
    return [];
  }
}

function storeCommentCampaignFolders(storageKey: string, folders: string[]) {
  if (typeof window === "undefined") return;
  window.localStorage.removeItem(COMMENT_CAMPAIGN_FOLDERS_STORAGE_KEY);
  window.localStorage.setItem(
    storageKey,
    JSON.stringify(uniqueFolderNames(folders)),
  );
}

function campaignFolderSummary(campaigns: Campaign[]) {
  const sourceIds = new Set<string>();
  for (const campaign of campaigns) {
    for (const sourceId of stringList(campaign.config.source_ids)) {
      sourceIds.add(sourceId);
    }
  }
  return {
    campaigns: campaigns.length,
    running: campaigns.filter((campaign) =>
      ["pending", "running", "active"].includes(campaign.status),
    ).length,
    sources: sourceIds.size,
    sent: campaigns.reduce(
      (total, campaign) => total + Number(campaign.sent_count || 0),
      0,
    ),
  };
}

function pluralRu(count: number, one: string, few: string, many: string) {
  const mod10 = Math.abs(count) % 10;
  const mod100 = Math.abs(count) % 100;
  if (mod10 === 1 && mod100 !== 11) return one;
  if (mod10 >= 2 && mod10 <= 4 && (mod100 < 12 || mod100 > 14)) return few;
  return many;
}

function sourceTypeLabel(value: string | null | undefined) {
  const labels: Record<string, string> = {
    channel: "Канал",
    group: "Группа",
    dialog: "Диалог",
    unknown: "Не проверен",
  };
  return labels[value || "unknown"] || value || "Не проверен";
}

function sourceIsBlacklisted(source: Source) {
  return (
    source.access_status === "blacklisted" ||
    source.source_metadata?.blacklisted === true
  );
}

function sourcesForCampaignType(
  campaignType:
    | "comment_posts"
    | "neuro_chat"
    | "neuro_dialog"
    | "message_broadcast",
  sources: Source[],
) {
  const allowedSources = sources.filter((source) => !sourceIsBlacklisted(source));
  if (campaignType === "comment_posts") {
    return allowedSources.filter(
      (source) =>
        source.type === "channel" &&
        source.access_status !== "archived" &&
        !String(source.access_status || "").startsWith("invalid_") &&
        !source.is_private &&
        !source.is_join_request_required,
    );
  }
  if (campaignType === "neuro_chat") {
    return allowedSources.filter((source) => source.type === "group");
  }
  return allowedSources.filter((source) => source.type === "dialog");
}

function sourceRequirementText(
  campaignType:
    | "comment_posts"
    | "neuro_chat"
    | "neuro_dialog"
    | "message_broadcast",
) {
  if (campaignType === "comment_posts")
    return "Нужны каналы. Доступность комментариев проверится во время работы кампании.";
  if (campaignType === "neuro_chat")
    return "Нужны проверенные источники типа группа.";
  if (campaignType === "message_broadcast")
    return "Нужны проверенные источники типа диалог.";
  return "Нужны проверенные источники типа диалог.";
}

function sourceUsageForCampaigns(
  campaigns: Campaign[],
  campaignType: string,
  excludeCampaignId?: string,
): SourceUsage {
  return campaigns.reduce<SourceUsage>((usage, campaign) => {
    if (campaign.id === excludeCampaignId) return usage;
    if (campaign.type !== campaignType) return usage;
    if (["archived", "deleted"].includes(campaign.status)) return usage;
    for (const sourceId of stringList(campaign.config.source_ids)) {
      usage[sourceId] = [...(usage[sourceId] || []), campaign.name];
    }
    return usage;
  }, {});
}

function accountUsageForCampaigns(
  campaigns: Campaign[],
  excludeCampaignId?: string,
  campaignType?: string,
): AccountUsage {
  return campaigns.reduce<AccountUsage>((usage, campaign) => {
    if (campaign.id === excludeCampaignId) return usage;
    if (campaignType && campaign.type !== campaignType) return usage;
    if (!["active", "pending", "running", "stopping"].includes(campaign.status))
      return usage;
    for (const accountId of stringList(campaign.config.account_ids)) {
      usage[accountId] = [...(usage[accountId] || []), campaign.name];
    }
    return usage;
  }, {});
}

function isSelectableCampaignAccount(account: TelegramAccount) {
  return !isBlockedCampaignAccount(account);
}

function selectableCampaignAccounts(accounts: TelegramAccount[]) {
  return accounts.filter(isSelectableCampaignAccount);
}

function isBlockedCampaignAccount(account: TelegramAccount) {
  if (account.telegram_manual_hold) return true;
  if (!["active", "ready"].includes(account.status)) return true;
  if (account.restriction_status === "limited") return true;
  if (account.restriction_status === "blocked") return true;
  if (accountNeedsProxy(account)) return true;
  return false;
}

function accountHasSpamBlock(account: TelegramAccount) {
  return (
    account.status === "spam_blocked" ||
    account.restriction_status === "limited" ||
    account.restriction_status === "blocked"
  );
}

function accountIsQuarantined(account: TelegramAccount) {
  return account.status === "quarantined";
}

function accountNeedsProxy(account: TelegramAccount) {
  return account.proxy_required && !account.proxy_id;
}

function countOverloadedAccountProxies(
  accounts: TelegramAccount[],
  proxies: Proxy[],
) {
  const proxyCounts = accounts.reduce<Record<string, number>>((acc, account) => {
    if (!account.proxy_id) return acc;
    acc[account.proxy_id] = (acc[account.proxy_id] || 0) + 1;
    return acc;
  }, {});
  return proxies.filter((proxy) => {
    const count = proxyCounts[proxy.id] || proxy.account_count || 0;
    return proxy.max_accounts > 0 && count > proxy.max_accounts;
  }).length;
}

function isLimitedCampaignAccount(account: TelegramAccount) {
  return Boolean(accountMediumRiskReason(account));
}

function accountMediumRiskReason(account: TelegramAccount) {
  if (isBlockedCampaignAccount(account)) return null;
  if (
    account.restriction_status === "unknown" &&
    (account.restriction_label || "").toLowerCase().includes("заблокирован")
  ) {
    return "Telegram заблокировал";
  }
  if (account.owner_attested) return null;
  if (account.warmup_score < 80) return `прогрев ${account.warmup_score}/100`;
  if (!["completed", "succeeded", "ready"].includes(account.warmup_status)) {
    return "прогрев не завершен";
  }
  return null;
}

function accountRiskLevelForFilter(
  account: TelegramAccount,
): "low" | "medium" | "critical" {
  if (accountHasCriticalRisk(account)) return "critical";
  if (isLimitedCampaignAccount(account)) return "medium";
  return "low";
}

function accountHasCriticalRisk(account: TelegramAccount) {
  if (accountHasSpamBlock(account)) return true;
  if (accountIsQuarantined(account)) return true;
  if (account.status === "blocked" || account.status === "deleted") return true;
  if (accountNeedsProxy(account)) return true;
  return false;
}

function accountMatchesRiskFilter(
  account: TelegramAccount,
  filter: AccountRiskFilter,
) {
  if (filter === "missing_proxy") return accountNeedsProxy(account);
  if (filter === "spam_blocked") return accountHasSpamBlock(account);
  if (filter === "quarantined") return accountIsQuarantined(account);
  if (filter === "warming") return isAccountWarmupActive(account);
  if (filter === "ai_blocked") return isBlockedCampaignAccount(account);
  return accountRiskLevelForFilter(account) === filter;
}

function accountRiskFilterLabel(filter: AccountRiskFilter) {
  const labels: Record<AccountRiskFilter, string> = {
    low: "низкий риск",
    medium: "средний риск",
    critical: "критический риск",
    missing_proxy: "без прокси",
    spam_blocked: "спам-блок",
    quarantined: "карантин",
    warming: "на прогреве",
    ai_blocked: "AI-комментарии заблокированы",
  };
  return labels[filter];
}

function accountCampaignSafetyText(account: TelegramAccount) {
  if (account.telegram_manual_hold) {
    const reasons: Record<string, string> = { admission_required: "нужен допуск владельца", operator_paused: "приостановлен оператором", source_denied: "остановлен после отказа источника", transport_error: "остановлен после ошибки соединения", spam_suspected: "остановлен: требуется проверка ограничений", spam_restricted: "подтверждено ограничение Telegram" };
    return `${accountName(account)}: ${reasons[account.telegram_safety_reason || ""] || "аккаунт остановлен — причина в разделе Безопасность"}`;
  }
  if (!["active", "ready"].includes(account.status)) {
    return `${accountName(account)}: статус ${statusLabel(account.status)} не подходит для кампаний`;
  }
  if (account.restriction_status === "limited" || account.restriction_status === "blocked") {
    return `${accountName(account)}: Telegram-ограничение`;
  }
  if (accountNeedsProxy(account)) {
    return `${accountName(account)}: не назначен прокси`;
  }
  if (account.warmup_score < 80) {
    return `${accountName(account)}: прогрев ${account.warmup_score}/100`;
  }
  const reason = accountMediumRiskReason(account);
  return reason
    ? `${accountName(account)}: ${reason}`
    : `${accountName(account)}: проверка пройдена`;
}

function SourceUsageBadge({ usage }: { usage: string[] }) {
  if (!usage.length) return null;
  const label = `Уже выбран: ${usage.join(", ")}`;
  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <Badge variant="secondary" className="shrink-0 cursor-default">
          Уже выбран
        </Badge>
      </TooltipTrigger>
      <TooltipContent className="max-w-80 whitespace-pre-wrap text-left">
        {label}
      </TooltipContent>
    </Tooltip>
  );
}

function CampaignAccountDropdown({
  accounts,
  accountUsage,
  initialSelectedIds = [],
  name = "account_ids",
  emptyText = "Нет свободных активных аккаунтов.",
  onSelectionChange,
}: {
  accounts: TelegramAccount[];
  accountUsage: AccountUsage;
  initialSelectedIds?: string[];
  name?: string;
  emptyText?: string;
  onSelectionChange?: (selectedIds: string[]) => void;
}) {
  const selectableAccounts = React.useMemo(
    () =>
      accounts.filter(account => initialSelectedIds.includes(account.id) ||
        (isSelectableCampaignAccount(account) && !(accountUsage[account.id] || []).length)),
    [accountUsage, accounts, initialSelectedIds],
  );
  const selectableKey = React.useMemo(
    () => selectableAccounts.map((account) => account.id).join("|"),
    [selectableAccounts],
  );
  const initialKey = React.useMemo(
    () => initialSelectedIds.join("|"),
    [initialSelectedIds],
  );
  const [selectedIds, setSelectedIds] = React.useState<string[]>(() =>
    initialSelectedIds.length
      ? initialSelectedIds
      : selectableAccounts[0]
        ? [selectableAccounts[0].id]
        : [],
  );
  const [open, setOpen] = React.useState(false);
  const [query, setQuery] = React.useState("");
  const visibleAccounts = accounts.filter(account =>
    `${accountDisplayLabel(account)} ${account.username || ""} ${account.id}`.toLocaleLowerCase().includes(query.trim().toLocaleLowerCase()));
  function unavailableReason(account: TelegramAccount) {
    if (initialSelectedIds.includes(account.id)) return null;
    if ((accountUsage[account.id] || []).length) return `Занят: ${accountUsage[account.id].join(", ")}`;
    if (isBlockedCampaignAccount(account)) return accountNeedsProxy(account) ? "Нужен прокси" : accountCampaignSafetyText(account);
    return null;
  }

  React.useEffect(() => {
    onSelectionChange?.(selectedIds);
  }, [onSelectionChange, selectedIds]);

  React.useEffect(() => {
    const selectableIds = new Set(selectableKey.split("|").filter(Boolean));
    if (initialKey) {
      setSelectedIds(
        initialKey
          .split("|")
          .filter((accountId) => accountId && selectableIds.has(accountId)),
      );
      return;
    }
    const firstAccountId = selectableKey.split("|").filter(Boolean)[0];
    setSelectedIds(firstAccountId ? [firstAccountId] : []);
  }, [initialKey, selectableKey]);

  const selectedSet = React.useMemo(() => new Set(selectedIds), [selectedIds]);
  const selectedAccounts = React.useMemo(
    () => selectableAccounts.filter((account) => selectedSet.has(account.id)),
    [selectableAccounts, selectedSet],
  );
  const firstSelectedAccount = selectedAccounts[0] || null;
  const triggerText =
    selectedAccounts.length > 1
      ? `${selectedAccounts.length} ${pluralRu(selectedAccounts.length, "аккаунт", "аккаунта", "аккаунтов")} · ${accountDisplayLabel(selectedAccounts[0])}`
      : firstSelectedAccount
        ? accountDisplayLabel(firstSelectedAccount)
        : "Выберите аккаунты";

  function toggleAccount(accountId: string) {
    setSelectedIds((current) =>
      current.includes(accountId)
        ? current.filter((selectedAccountId) => selectedAccountId !== accountId)
        : [...current, accountId],
    );
  }


  return (
    <div className="grid gap-2">
      {selectedIds.map((accountId) => (
        <input key={accountId} type="hidden" name={name} value={accountId} />
      ))}
      <Popover open={open} onOpenChange={setOpen}>
        <PopoverTrigger asChild>
          <Button
            type="button"
            variant="outline"
            className="h-auto min-h-11 w-full justify-between gap-3 px-3 py-2"
          >
            <span className="flex min-w-0 items-center gap-2 text-left">
              {firstSelectedAccount ? (
                <AccountMiniAvatar account={firstSelectedAccount} />
              ) : null}
              <span className="min-w-0 truncate">{triggerText}</span>
            </span>
            <ChevronDownIcon className="size-4 shrink-0 text-muted-foreground" />
          </Button>
        </PopoverTrigger>
        <PopoverContent
          align="start"
          sideOffset={6}
          portalled={false}
          className="flex max-h-[min(420px,var(--radix-popover-content-available-height),calc(100dvh-2rem))] w-[520px] max-w-[88vw] flex-col overflow-hidden p-2"
        >
          <div className="flex min-h-0 flex-1 flex-col overflow-hidden">
            {selectableAccounts.length ? (
              <div className="mb-1 flex shrink-0 items-center justify-between gap-2 border-b bg-popover pb-2">
                <span className="text-xs text-muted-foreground">
                  Выбрано: {selectedIds.length}
                </span>
                <div className="flex gap-2">
                  <Button
                    type="button"
                    variant="ghost"
                    size="sm"
                    onClick={() =>
                      setSelectedIds(selectableAccounts.map((account) => account.id))
                    }
                  >
                    Все доступные
                  </Button>
                  <Button
                    type="button"
                    variant="ghost"
                    size="sm"
                    onClick={() => setSelectedIds([])}
                  >
                    Снять
                  </Button>
                </div>
              </div>
            ) : null}
            <Input aria-label="Поиск аккаунтов" placeholder="Номер, имя или username" value={query} onChange={e => setQuery(e.target.value)} className="mb-2 shrink-0" />
            <div className="mb-1 text-xs text-muted-foreground">Всего: {accounts.length} · доступно: {selectableAccounts.length}</div>
            <div
              className="h-[280px] min-h-0 overflow-y-auto overscroll-contain pr-1"
            >
              <div className="grid gap-1">
                {visibleAccounts.map((account) => (
                  <div
                    key={account.id}
                    role="button"
                    tabIndex={unavailableReason(account) ? -1 : 0}
                    aria-disabled={Boolean(unavailableReason(account))}
                    className={`flex min-w-0 items-center gap-3 rounded-md px-2 py-2 text-left ${unavailableReason(account) ? "opacity-50" : "cursor-pointer hover:bg-muted"}`}
                    onClick={() => { if (!unavailableReason(account)) toggleAccount(account.id); }}
                    onKeyDown={(event) => {
                      if (!unavailableReason(account) && (event.key === "Enter" || event.key === " ")) {
                        event.preventDefault();
                        toggleAccount(account.id);
                      }
                    }}
                  >
                    <span className="flex size-4 items-center justify-center">
                      {selectedSet.has(account.id) ? (
                        <CheckIcon className="size-4" />
                      ) : null}
                    </span>
                    <AccountMiniAvatar account={account} />
                    <span className="min-w-0 flex-1">
                      <span
                        className="block truncate font-medium"
                        title={accountDisplayLabel(account)}
                      >
                        {accountDisplayLabel(account)}
                      </span>
                      <span className="block truncate text-xs text-muted-foreground">
                        {unavailableReason(account) || `${accountHandle(account)} · здоровье ${account.health_score}`}
                      </span>
                    </span>
                  </div>
                ))}
                {!visibleAccounts.length && (
                  <span className="px-2 py-3 text-sm text-muted-foreground">
                    {emptyText}
                  </span>
                )}
              </div>
            </div>
          </div>
        </PopoverContent>
      </Popover>
    </div>
  );
}

