function CampaignSourceDistributionPreview({
  accounts,
  sources,
  accountIds,
  sourceIds,
  mode,
}: {
  accounts: TelegramAccount[];
  sources: Source[];
  accountIds: string[];
  sourceIds: string[];
  mode: CampaignSourceAssignmentMode;
}) {
  const assignment = React.useMemo(
    () =>
      mode === "parallel_pool"
        ? buildParallelSourceAssignment(accountIds, sourceIds)
        : buildRoundRobinSourceAssignment(accountIds, sourceIds),
    [accountIds, mode, sourceIds],
  );
  const assignmentJson = React.useMemo(
    () => JSON.stringify(assignment, null, 2),
    [assignment],
  );
  const activeAccountIds = mode === "standard" ? accountIds.slice(0, 1) : accountIds;

  return (
    <div className="grid gap-3 rounded-lg border bg-muted/20 p-3">
      <textarea
        name="source_assignment"
        value={mode === "standard" ? "{}" : assignmentJson}
        readOnly
        className="hidden"
      />
      <div className="flex flex-wrap items-center justify-between gap-2">
        <div className="text-sm font-medium">
          {mode === "parallel_pool" ? "Параллельный пул" : "Распределение по аккаунтам"}
        </div>
        <Badge variant="secondary">
          {sourceIds.length} источников / {accountIds.length || 0} аккаунтов
        </Badge>
      </div>
      {!accountIds.length || !sourceIds.length ? (
        <div className="rounded-md border border-dashed bg-background px-3 py-4 text-sm text-muted-foreground">
          Выберите аккаунты и источники, чтобы увидеть схему.
        </div>
      ) : (
        <div className="grid max-h-72 gap-3 overflow-y-auto pr-1 sm:grid-cols-2 xl:grid-cols-3">
          {activeAccountIds.map((accountId) => {
            const assignedSourceIds =
              mode === "standard" ? sourceIds : assignment[accountId] || [];
            return (
              <div key={accountId} className="grid min-w-0 gap-2 rounded-md border bg-background p-3">
                <div className="min-w-0">
                  <div className="truncate text-sm font-medium" title={accountNameById(accounts, accountId)}>
                    {accountNameById(accounts, accountId)}
                  </div>
                  <div className="text-xs text-muted-foreground">
                    {assignedSourceIds.length} {pluralRu(assignedSourceIds.length, "источник", "источника", "источников")}
                  </div>
                </div>
	                <div className="grid max-h-28 gap-1 overflow-y-auto rounded bg-muted/30 p-2 text-xs">
	                  {assignedSourceIds.slice(0, 12).map((sourceId) => {
	                    const source = sources.find((item) => item.id === sourceId);
	                    const label = source ? sourceDisplayName(source) : sourceNameById(sources, sourceId);
	                    const ref = source ? sourceRef(source) : "";
	                    return (
	                      <div key={sourceId} className="min-w-0" title={ref ? `${label} · ${ref}` : label}>
	                        <div className="truncate font-medium">{label}</div>
	                        {ref ? (
	                          <div className="truncate text-[11px] text-muted-foreground">
	                            {ref}
	                          </div>
	                        ) : null}
	                      </div>
	                    );
	                  })}
                  {assignedSourceIds.length > 12 ? (
                    <div className="text-muted-foreground">
                      Еще {assignedSourceIds.length - 12}
                    </div>
                  ) : null}
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

const SOURCE_SELECTION_RENDER_LIMIT = 80;
type SourceInlineImportType = "unknown" | "channel" | "group" | "dialog";

function SourceSelectionBox({
  sources,
  sourceUsage,
  initialSelectedIds = [],
  name = "source_ids",
  emptyText = "Источников пока нет.",
  emptyAction = null,
  allUsedText = "Все подходящие источники уже выбраны в других кампаниях.",
  maxHeightClass = "max-h-52",
  showRef = false,
  showType = false,
  columnsClass = "",
  hideUsed = false,
  preserveOrder = false,
  showSelectedCount = false,
  showBulkActions = true,
  showThemeFilter = false,
  allowLinkImport = false,
  importSourceType = "unknown",
  manualListOnly = false,
  onSelectionChange,
  onSourcesChange,
}: {
  sources: Source[];
  sourceUsage: SourceUsage;
  initialSelectedIds?: string[];
  name?: string;
  emptyText?: string;
  emptyAction?: React.ReactNode;
  allUsedText?: string;
  maxHeightClass?: string;
  showRef?: boolean;
  showType?: boolean;
  columnsClass?: string;
  hideUsed?: boolean;
  preserveOrder?: boolean;
  showSelectedCount?: boolean;
  showBulkActions?: boolean;
  showThemeFilter?: boolean;
  allowLinkImport?: boolean;
  importSourceType?: SourceInlineImportType;
  manualListOnly?: boolean;
  onSelectionChange?: (selectedIds: string[]) => void;
  onSourcesChange?: (sources: Source[]) => void;
}) {
  const initialKey = React.useMemo(
    () => initialSelectedIds.join("|"),
    [initialSelectedIds],
  );
  const [selectedIds, setSelectedIds] = React.useState<string[]>(() => [
    ...initialSelectedIds,
  ]);
  const [searchQuery, setSearchQuery] = React.useState("");
  const [importText, setImportText] = React.useState("");
  const [importedSources, setImportedSources] = React.useState<Source[]>([]);
  const [importStatus, setImportStatus] = React.useState<string | null>(null);
  const [importBusy, setImportBusy] = React.useState(false);

  React.useEffect(() => {
    setSelectedIds(initialKey ? initialKey.split("|") : []);
  }, [initialKey]);

  React.useEffect(() => {
    onSelectionChange?.(selectedIds);
  }, [onSelectionChange, selectedIds]);

  const mergedSources = React.useMemo(() => {
    const byId = new Map<string, Source>();
    for (const source of sources) byId.set(source.id, source);
    for (const source of importedSources) byId.set(source.id, source);
    return [...byId.values()];
  }, [importedSources, sources]);

  React.useEffect(() => {
    onSourcesChange?.(mergedSources);
  }, [mergedSources, onSourcesChange]);

  const selectedSet = React.useMemo(() => new Set(selectedIds), [selectedIds]);
  const mergedSourceById = React.useMemo(
    () => new Map(mergedSources.map((source) => [source.id, source])),
    [mergedSources],
  );
  const selectedIdsInSourceOrder = React.useMemo(
    () =>
      mergedSources
        .filter((source) => selectedSet.has(source.id))
        .map((source) => source.id),
    [mergedSources, selectedSet],
  );
  const availableSources = React.useMemo(
    () =>
      mergedSources.filter(
        (source) => !sourceIsBlacklisted(source) && !(sourceUsage[source.id] || []).length,
      ),
    [mergedSources, sourceUsage],
  );
  const visibleSources = React.useMemo(
    () =>
      hideUsed
        ? mergedSources.filter(
            (source) =>
              !sourceIsBlacklisted(source) &&
              (selectedSet.has(source.id) || !(sourceUsage[source.id] || []).length),
          )
        : mergedSources.filter((source) => !sourceIsBlacklisted(source)),
    [hideUsed, mergedSources, selectedSet, sourceUsage],
  );
  const themeOptions = React.useMemo(() => sourceThemeOptions(visibleSources), [
    visibleSources,
  ]);
  const [selectedThemeKey, setSelectedThemeKey] = React.useState("__all__");

  React.useEffect(() => {
    if (
      selectedThemeKey !== "__all__" &&
      !themeOptions.some((option) => option.key === selectedThemeKey)
    ) {
      setSelectedThemeKey("__all__");
    }
  }, [selectedThemeKey, themeOptions]);

  const normalizedSearchQuery = normalizeSearchText(searchQuery);
  const sortedSources = React.useMemo(() => {
    const themeFilteredSources =
      showThemeFilter && selectedThemeKey !== "__all__"
        ? visibleSources.filter(
            (source) => sourceThemeOption(source).key === selectedThemeKey,
          )
        : visibleSources;
    const searchedSources = normalizedSearchQuery
      ? themeFilteredSources.filter((source) =>
          sourceSearchText(source).includes(normalizedSearchQuery),
        )
      : themeFilteredSources;
    if (preserveOrder) return searchedSources;
    return [...searchedSources].sort((left, right) => {
      const leftUsed = (sourceUsage[left.id] || []).length > 0;
      const rightUsed = (sourceUsage[right.id] || []).length > 0;
      const leftSelected = selectedSet.has(left.id);
      const rightSelected = selectedSet.has(right.id);
      const leftRank = leftSelected ? 0 : leftUsed ? 2 : 1;
      const rightRank = rightSelected ? 0 : rightUsed ? 2 : 1;
      return leftRank - rightRank;
    });
  }, [
    normalizedSearchQuery,
    preserveOrder,
    selectedSet,
    selectedThemeKey,
    showThemeFilter,
    sourceUsage,
    visibleSources,
  ]);
  const displayedSources = React.useMemo(
    () => sortedSources.slice(0, SOURCE_SELECTION_RENDER_LIMIT),
    [sortedSources],
  );

  function setAvailable(limit?: number) {
    const ids = availableSources
      .slice(0, limit ?? availableSources.length)
      .map((source) => source.id);
    setSelectedIds(ids);
  }

  function setVisibleThemeAvailable() {
    const ids = sortedSources
      .filter((source) => !(sourceUsage[source.id] || []).length)
      .map((source) => source.id);
    setSelectedIds((current) => Array.from(new Set([...current, ...ids])));
  }

  function toggleSource(sourceId: string) {
    setSelectedIds((current) =>
      current.includes(sourceId)
        ? current.filter((item) => item !== sourceId)
        : [...current, sourceId],
    );
  }

  function removeSelectedSource(sourceId: string) {
    setSelectedIds((current) => current.filter((item) => item !== sourceId));
  }

  async function importSourceLinks() {
    const refs = splitTextareaValues(importText);
    if (!refs.length) {
      setImportStatus("Вставьте ссылки или @username по одному в строке.");
      return;
    }
    setImportBusy(true);
    setImportStatus(null);
    try {
      const response = await apiRequest<SourceBulkCreateResponse>("/sources/bulk", {
        method: "POST",
        token: storedToken(),
        workspaceId: storedWorkspaceId(),
        body: { refs, type: importSourceType },
      });
      const imported = response.items.map((item) => item.source);
      const importedIds = imported
        .filter((source) => !sourceIsBlacklisted(source))
        .map((source) => source.id);
      setImportedSources((current) => {
        const byId = new Map(current.map((source) => [source.id, source]));
        for (const source of imported) byId.set(source.id, source);
        return [...byId.values()];
      });
      setSelectedIds((current) => Array.from(new Set([...current, ...importedIds])));
      setImportText("");
      setImportStatus(
        `Добавлено: ${response.created}, уже были: ${response.reused}. Выбрано ${importedIds.length} источников из вставки.`,
      );
    } catch (error) {
      setImportStatus(errorMessage(error));
    } finally {
      setImportBusy(false);
    }
  }

  return (
    <div className="grid gap-2">
      {showSelectedCount || (showThemeFilter && !manualListOnly) ? (
        <div className="flex flex-wrap items-center justify-between gap-3">
          {showThemeFilter && !manualListOnly ? (
            <div className="flex min-w-56 flex-1 flex-wrap gap-2">
              <NativeSelect
                className="min-w-56 flex-1"
                value={selectedThemeKey}
                onChange={(event) => setSelectedThemeKey(event.target.value)}
              >
                <NativeSelectOption value="__all__">
                  Все тематики
                </NativeSelectOption>
                {themeOptions.map((option) => (
                  <NativeSelectOption key={option.key} value={option.key}>
                    {option.label} ({option.count})
                  </NativeSelectOption>
                ))}
              </NativeSelect>
              <Button
                type="button"
                variant="outline"
                size="sm"
                disabled={!sortedSources.some((source) => !(sourceUsage[source.id] || []).length)}
                onClick={setVisibleThemeAvailable}
              >
                Выбрать тематику
              </Button>
            </div>
          ) : null}
          {showSelectedCount ? (
            <div className="shrink-0 text-sm text-muted-foreground">
              Выбрано: {selectedIds.length}
            </div>
          ) : null}
        </div>
      ) : null}
      {!manualListOnly ? (
        <Input
          value={searchQuery}
          placeholder="Поиск по названию, username, ссылке или ID"
          onChange={(event) => setSearchQuery(event.currentTarget.value)}
        />
      ) : null}
      {allowLinkImport ? (
        <div className="grid gap-2 rounded-md border bg-muted/20 p-3">
          <HelpLabel tip="Вставьте ссылки t.me, https://t.me/... или @username. Система добавит новые источники через базу источников, уже существующие переиспользует и сразу отметит их в выборе.">
            Быстро добавить ссылками
          </HelpLabel>
          <Textarea
            value={importText}
            onChange={(event) => setImportText(event.currentTarget.value)}
            placeholder="https://t.me/channel&#10;@another_channel"
            className="min-h-24 font-mono text-sm"
          />
          <div className="flex flex-wrap items-center gap-2">
            <Button
              type="button"
              variant="outline"
              size="sm"
              disabled={importBusy}
              onClick={() => void importSourceLinks()}
            >
              <PlusIcon className="size-4" />
              Добавить и распределить
            </Button>
            {importStatus ? (
              <span className="text-xs text-muted-foreground">{importStatus}</span>
            ) : null}
          </div>
        </div>
      ) : null}
      {showBulkActions && !manualListOnly ? (
      <div className="flex flex-wrap gap-2">
        <Button
          type="button"
          variant="outline"
          size="sm"
          disabled={!availableSources.length}
          onClick={() => setAvailable()}
        >
          Выбрать все свободные
        </Button>
        <Button
          type="button"
          variant="outline"
          size="sm"
          disabled={!availableSources.length}
          onClick={() => setAvailable(10)}
        >
          Последние 10
        </Button>
        <Button
          type="button"
          variant="outline"
          size="sm"
          disabled={!availableSources.length}
          onClick={() => setAvailable(20)}
        >
          Последние 20
        </Button>
        <Button
          type="button"
          variant="ghost"
          size="sm"
          disabled={!selectedIds.length}
          onClick={() => setSelectedIds([])}
        >
          Снять выбор
        </Button>
      </div>
      ) : null}
      {(manualListOnly ? selectedIds : selectedIdsInSourceOrder).map((sourceId) => (
        <input key={sourceId} type="hidden" name={name} value={sourceId} />
      ))}
      {manualListOnly ? (
        <div className={`grid gap-2 overflow-auto rounded-md border p-3 ${maxHeightClass}`}>
          {selectedIds.map((sourceId) => {
            const source = mergedSourceById.get(sourceId);
            const label = source ? sourceDisplayName(source) : sourceNameById(mergedSources, sourceId);
            const ref = source ? sourceRef(source) : sourceId;
            return (
              <div
                key={sourceId}
                className="flex min-w-0 items-center gap-2 rounded-md border bg-background px-3 py-2"
              >
                <span className="min-w-0 flex-1">
                  <span className="block truncate text-sm font-medium" title={label}>
                    {label}
                  </span>
                  <span className="block truncate text-xs text-muted-foreground" title={ref}>
                    {ref}
                  </span>
                </span>
                {source ? (
                  <Badge variant="outline">{sourceTypeLabel(source.type)}</Badge>
                ) : null}
                <Button
                  type="button"
                  variant="ghost"
                  size="icon"
                  className="size-8 shrink-0"
                  onClick={() => removeSelectedSource(sourceId)}
                  aria-label="Убрать источник"
                  title="Убрать источник"
                >
                  <XIcon className="size-4" />
                </Button>
              </div>
            );
          })}
          {!selectedIds.length ? (
            <span className="text-sm text-muted-foreground">
              Вставьте ссылки или username выше, чтобы собрать рабочий список кампании.
            </span>
          ) : null}
        </div>
      ) : (
        <div
          className={`grid gap-2 overflow-auto rounded-md border p-3 ${maxHeightClass} ${columnsClass}`}
        >
        {displayedSources.map((source) => {
          const usage = sourceUsage[source.id] || [];
          const isUsed = usage.length > 0;
          const isSelected = selectedSet.has(source.id);
          const sourceLabel = sourceDisplayName(source);
          return (
            <label
              key={source.id}
              className={`flex min-w-0 items-center gap-2 rounded px-1 py-0.5 text-sm ${isUsed ? "text-muted-foreground" : ""}`}
            >
              <Checkbox
                checked={isSelected}
                disabled={isUsed}
                onCheckedChange={() => toggleSource(source.id)}
              />
              <span className="min-w-0 flex-1">
                <span
                  className="block truncate"
                  title={sourceLabel}
                >
                  {sourceLabel}
                </span>
                {showRef && (
                  <span className="block truncate text-xs text-muted-foreground">
                    {sourceRef(source)}
                  </span>
                )}
              </span>
              {showType && (
                <Badge variant="outline">{sourceTypeLabel(source.type)}</Badge>
              )}
              <SourceUsageBadge usage={usage} />
            </label>
          );
        })}
        {sortedSources.length > displayedSources.length && (
          <span className="rounded-md bg-muted/50 px-2 py-1 text-xs text-muted-foreground">
            Показано {displayedSources.length} из {sortedSources.length}.
            Уточните поиск, чтобы быстрее найти нужный источник.
          </span>
        )}
        {!visibleSources.length && (
          <div className="grid gap-2 text-sm text-muted-foreground">
            <span>{emptyText}</span>
            {emptyAction}
          </div>
        )}
        {visibleSources.length > 0 && !sortedSources.length && (
          <span className="text-sm text-muted-foreground">
            {normalizedSearchQuery
              ? "По этому поиску источники не найдены."
              : "В этой тематике нет доступных источников."}
          </span>
        )}
        {visibleSources.length > 0 && !availableSources.length && (
          <span className="text-sm text-muted-foreground">{allUsedText}</span>
        )}
      </div>
      )}
    </div>
  );
}

function SourceFolderSelectionBox({
  folders,
  name = "source_folder_ids",
}: {
  folders: SourceFolder[];
  name?: string;
}) {
  const [selectedIds, setSelectedIds] = React.useState<string[]>([]);
  const selectedSet = React.useMemo(() => new Set(selectedIds), [selectedIds]);
  function toggleFolder(folderId: string) {
    setSelectedIds((current) =>
      current.includes(folderId)
        ? current.filter((item) => item !== folderId)
        : [...current, folderId],
    );
  }
  return (
    <div className="grid gap-2">
      <div className="flex items-center justify-between gap-3">
        <div className="text-sm text-muted-foreground">
          Выбрано папок: {selectedIds.length}
        </div>
        <Button
          type="button"
          variant="ghost"
          size="sm"
          disabled={!selectedIds.length}
          onClick={() => setSelectedIds([])}
        >
          Снять выбор
        </Button>
      </div>
      {selectedIds.map((folderId) => (
        <input key={folderId} type="hidden" name={name} value={folderId} />
      ))}
      <div className="grid max-h-40 gap-2 overflow-auto rounded-md border p-3 sm:grid-cols-2">
        {folders.map((folder) => (
          <label
            key={folder.id}
            className="flex min-w-0 items-center gap-2 rounded px-1 py-0.5 text-sm"
          >
            <Checkbox
              checked={selectedSet.has(folder.id)}
              onCheckedChange={() => toggleFolder(folder.id)}
            />
            <span className="min-w-0 flex-1">
              <span className="block truncate" title={folder.name}>
                {folder.name}
              </span>
              <span className="block text-xs text-muted-foreground">
                {folder.sources_count} источников
              </span>
            </span>
          </label>
        ))}
        {!folders.length && (
          <span className="text-sm text-muted-foreground">
            Папок источников пока нет.
          </span>
        )}
      </div>
    </div>
  );
}

void SourceSafetySummaryStrip;
void SourceCommentsBadge;
void SourceSafetyBadge;
void SourceAccessSelect;
void SourceDialog;
void SourceFolderSelectionBox;

async function channelMapRequest<T>(path: string) {
  return apiRequest<T>(`/channel-map${path}`, {
    token: storedToken(),
    workspaceId: storedWorkspaceId(),
  });
}

function formatCompactNumber(value: number | null | undefined) {
  const number = Number(value || 0);
  if (number >= 1_000_000) return `${(number / 1_000_000).toFixed(1)}M`;
  if (number >= 1_000) return `${(number / 1_000).toFixed(1)}K`;
  return String(number);
}

function sourceComparableRef(source: Source) {
  return comparableRef(
    source.username ? `@${source.username}` : source.url || source.id,
  );
}

function normalizeSearchText(value: string) {
  return value.trim().toLowerCase().replace(/^@+/, "");
}

function sourceSearchText(source: Source) {
  const metadata = objectRecord(source.source_metadata);
  const channelMap = objectRecord(metadata.channel_map);
  return [
    source.id,
    source.id.slice(0, 8),
    sourceDisplayName(source),
    source.username,
    source.username ? source.username.replace(/^@/, "") : "",
    source.url,
    sourceRef(source),
    sourceTypeLabel(source.type),
    stringFromUnknown(channelMap.sub_cluster_label),
    stringFromUnknown(channelMap.cluster_label),
  ]
    .filter(Boolean)
    .join(" ")
    .toLowerCase()
    .replace(/@/g, "");
}

function sourceDisplayName(source: Source) {
  return source.title || source.username || source.url || source.id.slice(0, 8);
}

function sourceThemeOptions(sources: Source[]) {
  const options = new Map<string, { key: string; label: string; count: number }>();
  sources.forEach((source) => {
    const option = sourceThemeOption(source);
    const current = options.get(option.key);
    if (current) {
      current.count += 1;
    } else {
      options.set(option.key, { ...option, count: 1 });
    }
  });
  return [...options.values()].sort((left, right) =>
    left.label.localeCompare(right.label, "ru"),
  );
}

function sourceThemeOption(source: Source) {
  const metadata = objectRecord(source.source_metadata);
  const channelMap = objectRecord(metadata.channel_map);
  const subClusterId = stringFromUnknown(channelMap.sub_cluster_id);
  const clusterId = stringFromUnknown(channelMap.cluster_id);
  const label =
    stringFromUnknown(channelMap.sub_cluster_label) ||
    stringFromUnknown(channelMap.cluster_label) ||
    "Без тематики";
  const key = subClusterId
    ? `micro:${subClusterId}`
    : clusterId
      ? `macro:${clusterId}`
      : `unknown:${label}`;
  return { key, label };
}

function comparableRef(value: string) {
  return value
    .trim()
    .toLowerCase()
    .replace(/^https?:\/\/t\.me\//, "@")
    .replace(/^@+/, "@");
}

function campaignScope(
  campaign: Campaign,
  accounts: TelegramAccount[],
  sources: Source[],
) {
  const accountIds = stringList(campaign.config.account_ids);
  const sourceIds = stringList(campaign.config.source_ids);
  const targetRefs = stringList(campaign.config.target_refs);
  const accountLabels = accountIds.map((id) => accountNameById(accounts, id));
  const sourceLabels = sourceIds.map((id) => sourceNameById(sources, id));

  return [
    accountLabels.length
      ? `${accountLabels.length} аккаунтов`
      : "аккаунты не заданы",
    sourceLabels.length
      ? `${sourceLabels.length} источников`
      : targetRefs.length
        ? `${targetRefs.length} диалогов`
        : "цели не заданы",
  ].join(" / ");
}

type CampaignClientSafety = {
  status: "allowed" | "limited" | "blocked";
  canStart: boolean;
  blockedCount: number;
  limitedCount: number;
  messages: string[];
};

function campaignReplacementPreparing(campaign: Campaign) {
  const r = campaign.config.account_replacement as { status?: string; jobs?: { status: string }[] } | undefined;
  return Boolean(r && (["queued", "joining", "waiting_account", "needs_review"].includes(r.status || "") ||
    r.status === "cancelled" && r.jobs?.some(j => j.status !== "joined")));
}

function CampaignReplacementQueueBadge({ campaign, accounts }: { campaign: Campaign; accounts: TelegramAccount[] }) {
  const r = campaign.config.account_replacement as { status?: string; jobs?: { status: string; kind: string }[]; resume_when_ready?: boolean; next_join_at?: string; wait_reason?: string } | undefined;
  if (!r || !campaignReplacementPreparing(campaign)) return null;
  const channels = (r.jobs || []).filter(j => j.kind === "channel");
  const discussions = (r.jobs || []).filter(j => j.kind === "discussion");
  return <Tooltip>
    <TooltipTrigger asChild><Badge variant="outline" tabIndex={0} className="w-fit cursor-help whitespace-nowrap" role="status">{r.status === "needs_review" ? "Подготовка остановлена" : "Подготовка"}: {channels.filter(j => j.status === "joined").length}/{channels.length}</Badge></TooltipTrigger>
    <TooltipContent className="max-w-96 text-left"><div className="grid gap-1 text-xs">
    <span>Аккаунт: {accountName(accounts.find(a => a.id === stringList(campaign.config.account_ids)[0]) || { id: stringList(campaign.config.account_ids)[0] } as TelegramAccount)}</span>
    <span className="font-medium">{r.status === "needs_review" ? "Подготовка остановлена" : "Подготовка источников"}: {channels.filter(j => j.status === "joined").length}/{channels.length} каналов</span>
    {discussions.length > 0 && <span>Обсуждения: {discussions.filter(j => j.status === "joined").length}/{discussions.length}</span>}
    <span>{r.resume_when_ready ? "Автозапуск после подготовки" : "После подготовки — на паузе"}</span>
    {r.next_join_at && r.status !== "needs_review" && <span>Следующая проверка: {formatDateTime(r.next_join_at)}</span>}
    {r.wait_reason && <span className="whitespace-normal">{r.wait_reason}</span>}
  </div></TooltipContent></Tooltip>;
}

function campaignClientSafety(
  campaign: Campaign,
  accounts: TelegramAccount[],
): CampaignClientSafety {
  if (
    campaign.last_run_status === "failed" &&
    campaign.last_error_code === "ACCOUNT_SAFETY_BLOCKED"
  ) {
    return {
      status: "blocked",
      canStart: false,
      blockedCount: 1,
      limitedCount: 0,
      messages: [
        campaignErrorText(
          campaign.last_error_message ||
            "Кампания остановлена safety-проверкой аккаунтов.",
          campaign.last_error_code,
        ),
      ],
    };
  }
  const accountById = new Map(accounts.map((account) => [account.id, account]));
  const selectedAccountIds = stringList(campaign.config.account_ids);
  const selectedAccounts = selectedAccountIds
    .map((id) => accountById.get(id))
    .filter((account): account is TelegramAccount => Boolean(account));
  const missingAccountMessages = selectedAccountIds
    .filter((id) => !accountById.has(id))
    .map(
      (id) =>
        `Аккаунт ${id.slice(0, 8)}: не найден в активных или архивных аккаунтах`,
    );
  const blocked = selectedAccounts.filter(isBlockedCampaignAccount);
  const limited = selectedAccounts.filter(
    (account) => !isBlockedCampaignAccount(account) && isLimitedCampaignAccount(account),
  );
  const blockedCount = blocked.length + missingAccountMessages.length;
  return {
    status: blockedCount ? "blocked" : limited.length ? "limited" : "allowed",
    canStart: blockedCount === 0,
    blockedCount,
    limitedCount: limited.length,
    messages: [
      ...blocked.map((account) => accountCampaignSafetyText(account)),
      ...missingAccountMessages,
      ...limited.map((account) => accountCampaignSafetyText(account)),
    ],
  };
}

function CampaignSafetyBadge({ safety }: { safety: CampaignClientSafety }) {
  if (safety.status === "allowed") {
    return (
      <Tooltip>
        <TooltipTrigger asChild>
          <Badge
            variant="outline"
            className="w-fit cursor-help border-emerald-200 bg-emerald-50 text-emerald-700"
          >
            <ShieldCheckIcon className="size-3" />
            Проверка пройдена
          </Badge>
        </TooltipTrigger>
        <TooltipContent className="max-w-96 whitespace-pre-wrap text-left">
          В выбранных аккаунтах кампании не найдено жестких блокеров. Это не
          автозапуск: перед стартом все равно учитываются лимиты частоты,
          дневной лимит и доступность live-listener.
        </TooltipContent>
      </Tooltip>
    );
  }
  const label =
    safety.status === "blocked"
      ? `Запуск заблокирован · ${safety.blockedCount}`
      : campaignSafetyWarningLabel(safety);
  const fallback =
    safety.status === "blocked"
      ? "Есть аккаунты с блокировками. Уберите их из кампании или исправьте статус."
      : "Есть аккаунты с предупреждениями. Проверьте runtime-события, прогрев и прокси перед запуском.";
  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <Badge
          variant="outline"
          className={cn(
            "w-fit cursor-default",
            safety.status === "blocked"
              ? "border-red-200 bg-red-50 text-red-700"
              : "border-amber-200 bg-amber-50 text-amber-700",
          )}
        >
          <ShieldCheckIcon className="size-3" />
          {label}
        </Badge>
      </TooltipTrigger>
      <TooltipContent className="max-w-96 whitespace-pre-wrap text-left">
        {safety.messages.slice(0, 6).join("\n") || fallback}
      </TooltipContent>
    </Tooltip>
  );
}

function campaignSafetyWarningLabel(safety: CampaignClientSafety) {
  const firstMessage = safety.messages[0] || "";
  const count = safety.limitedCount || safety.messages.length || 1;
  if (firstMessage.includes("прогрев")) {
    return `Прогрев не завершен · ${count}`;
  }
  if (firstMessage.includes("runtime-статус")) {
    return `Нет runtime-статуса · ${count}`;
  }
  if (firstMessage.includes("здоровье")) {
    return `Здоровье аккаунта · ${count}`;
  }
  return `Есть предупреждения · ${count}`;
}

function isCampaignRunnable(campaign: Campaign) {
  if (campaignReplacementPreparing(campaign)) return false;
  return (
    !isActiveCampaignRunStatus(campaign.active_run_status) &&
    !isActiveCampaignStatus(campaign.status)
  );
}

function isActiveCampaignStatus(status: string | null | undefined) {
  return ["active", "pending", "running", "stopping"].includes(status || "");
}

function isActiveCampaignRunStatus(status: string | null | undefined) {
  return ["pending", "running", "stopping"].includes(status || "");
}

function campaignPostSelectionMode(
  config: Record<string, unknown>,
): CampaignPostSelectionMode {
  const value = config.post_selection_mode;
  if (
    value === "new_posts" ||
    value === "historical_posts" ||
    value === "latest_post"
  )
    return value;
  return config.mode === "comment_new_posts" ? "new_posts" : "historical_posts";
}

function campaignDeliveryMode(
  config: Record<string, unknown>,
): CampaignDeliveryMode {
  const value = config.delivery_mode;
  if (value === "draft_only" || value === "generate_and_send") return value;
  return config.mode === "generate_and_send"
    ? "generate_and_send"
    : "draft_only";
}

function legacyCampaignMode(
  postSelectionMode: CampaignPostSelectionMode,
  deliveryMode: CampaignDeliveryMode,
): CampaignMode {
  if (deliveryMode === "generate_and_send") return "generate_and_send";
  return postSelectionMode === "new_posts"
    ? "comment_new_posts"
    : "comment_recent_posts";
}

function stringList(value: unknown) {
  return Array.isArray(value)
    ? value.filter((item): item is string => typeof item === "string")
    : [];
}

function delimitedTextList(value: FormDataEntryValue | null) {
  return String(value || "")
    .split(/[,;\n]+/)
    .map((item) => item.trim())
    .filter(Boolean);
}

function objectRecord(value: unknown): Record<string, unknown> {
  return value && typeof value === "object" && !Array.isArray(value)
    ? (value as Record<string, unknown>)
    : {};
}

function omitRecordKeys(
  value: Record<string, unknown>,
  keys: string[],
): Record<string, unknown> {
  const omitted = new Set(keys);
  return Object.fromEntries(
    Object.entries(value).filter(([key]) => !omitted.has(key)),
  );
}

function stringFromUnknown(value: unknown, fallback = "") {
  return value === null || value === undefined ? fallback : String(value);
}

function campaignSourceAssignmentMode(
  value: unknown,
): CampaignSourceAssignmentMode {
  if (value === "manual_pinned") return "manual_pinned";
  if (value === "parallel_pool") return "parallel_pool";
  return value === "multi_account_split" ? "multi_account_split" : "standard";
}

function campaignSourceAssignmentModeFromForm(
  form: FormData,
): CampaignSourceAssignmentMode {
  return campaignSourceAssignmentMode(form.get("source_assignment_mode"));
}

function campaignSourceAssignmentFromFormData(form: FormData): Record<string, string[]> {
  const raw = String(form.get("source_assignment") || "").trim();
  if (!raw) return {};
  try {
    return normalizeSourceAssignment(JSON.parse(raw));
  } catch {
    throw new Error("Схема закрепления должна быть валидным JSON вида { account_id: [source_id] }.");
  }
}

function normalizeSourceAssignment(value: unknown): Record<string, string[]> {
  const record = objectRecord(value);
  const assignment: Record<string, string[]> = {};
  for (const [accountId, sourceIds] of Object.entries(record)) {
    if (!Array.isArray(sourceIds)) continue;
    const cleanedSources = sourceIds
      .map(String)
      .map((item) => item.trim())
      .filter(Boolean);
    if (accountId.trim() && cleanedSources.length) {
      assignment[accountId.trim()] = Array.from(new Set(cleanedSources));
    }
  }
  return assignment;
}

function buildRoundRobinSourceAssignment(
  accountIds: string[],
  sourceIds: string[],
): Record<string, string[]> {
  const cleanedAccountIds = Array.from(new Set(accountIds.filter(Boolean)));
  const cleanedSourceIds = Array.from(new Set(sourceIds.filter(Boolean)));
  if (!cleanedAccountIds.length || !cleanedSourceIds.length) return {};
  return cleanedSourceIds.reduce<Record<string, string[]>>((assignment, sourceId, index) => {
    const accountId = cleanedAccountIds[index % cleanedAccountIds.length];
    assignment[accountId] = [...(assignment[accountId] || []), sourceId];
    return assignment;
  }, {});
}

function buildParallelSourceAssignment(
  accountIds: string[],
  sourceIds: string[],
): Record<string, string[]> {
  const cleanedAccountIds = Array.from(new Set(accountIds.filter(Boolean)));
  const cleanedSourceIds = Array.from(new Set(sourceIds.filter(Boolean)));
  return cleanedAccountIds.reduce<Record<string, string[]>>((assignment, accountId) => {
    assignment[accountId] = [...cleanedSourceIds];
    return assignment;
  }, {});
}

function campaignSettingsExportPayload(campaign: Campaign) {
  const config = objectRecord(campaign.config);
  const policy = objectRecord(campaign.policy);
  const stopConditions = objectRecord(config.stop_conditions);
  const inviteTracking = campaign.invite_tracking ?? config.invite_tracking ?? null;
  const settings = {
    ...config,
    policy,
    stop_conditions: stopConditions,
    invite_tracking: inviteTracking,
  };
  return {
    schema: "demo-platform.campaign.settings.v1",
    version: 1,
    exported_at: new Date().toISOString(),
    campaign_type: campaign.type,
    name: campaign.name,
    settings,
    config,
    policy,
    stop_conditions: stopConditions,
    invite_tracking: inviteTracking,
  };
}

function campaignSettingsImportPatch(rawText: string, currentCampaignType: string): Record<string, unknown> {
  const parsed = JSON.parse(rawText);
  const root = objectRecord(parsed);
  const rootSettings = objectRecord(root.settings);
  const campaignType = stringFromUnknown(root.campaign_type || root.type, currentCampaignType);
  if (campaignType && campaignType !== currentCampaignType) {
    throw new Error("JSON относится к другому типу кампании.");
  }
  const config = {
    ...root,
    ...rootSettings,
    ...objectRecord(rootSettings.config),
    ...objectRecord(root.config),
  };
  const policy = objectRecord(root.policy || rootSettings.policy || config.policy);
  const patch: Record<string, unknown> = {};
  const allowedConfigKeys = campaignSettingsImportKeys(currentCampaignType);
  for (const key of allowedConfigKeys) {
    if (key in config) patch[key] = config[key];
  }
  if (typeof root.name === "string" && root.name.trim()) {
    patch.name = root.name.trim();
  }
  if (Object.keys(policy).length) {
    patch.policy = policy;
  }
  if ("stop_conditions" in root || "stop_conditions" in rootSettings) {
    patch.stop_conditions = root.stop_conditions || rootSettings.stop_conditions;
  }
  if ("invite_tracking" in root || "invite_tracking" in rootSettings) {
    patch.invite_tracking = root.invite_tracking || rootSettings.invite_tracking;
  }
  if ("source_assignment" in patch) {
    patch.source_assignment = normalizeSourceAssignment(patch.source_assignment);
  }
  if ("source_assignment_mode" in patch) {
    patch.source_assignment_mode = campaignSourceAssignmentMode(patch.source_assignment_mode);
  }
  return patch;
}

function campaignSettingsImportKeys(campaignType: string) {
  const common = [
    "source_ids",
    "source_folder_ids",
    "account_ids",
    "source_assignment_mode",
    "source_assignment",
    "author_gender",
    "delivery_mode",
    "stop_conditions",
    "invite_tracking",
    "daily_limit_per_account",
    "delay_seconds_min",
    "delay_seconds_max",
    "prompt_text",
    "prompt_name",
    "prompt_tone",
    "product_context",
    "max_length",
    "max_comments",
    "run_for_minutes",
  ];
  if (campaignType === "comment_posts") {
    return [
      ...common,
      "comment_prompt_template_id",
      "latest_posts_per_source",
      "post_selection_mode",
      "mode",
    ];
  }
  if (campaignType === "neuro_chat") {
    return [
      ...common,
      "prompt_text",
      "tone",
      "trigger_keywords",
      "keyword_mode",
      "messages_per_source",
      "max_replies_per_tick",
      "min_quality_score",
      "reply_to_only",
    ];
  }
  if (campaignType === "neuro_dialog") {
    return [
      ...common,
      "prompt_text",
      "tone",
      "messages_per_dialog",
      "max_replies_per_tick",
      "min_quality_score",
      "only_reply_to_incoming",
    ];
  }
  if (campaignType === "mass_reactions") {
    return [
      ...common,
      "reactions",
      "target_scope",
      "reaction_weights",
      "comments_per_post",
      "messages_per_source",
      "react_as",
      "post_selection_mode",
      "latest_posts_per_source",
      "reaction_probability",
      "reaction_mode",
      "max_reactions",
    ];
  }
  if (campaignType === "message_broadcast") {
    return [...common, "message_text", "max_messages"];
  }
  return common;
}

function downloadJsonFile(filename: string, payload: unknown) {
  const blob = new Blob([JSON.stringify(payload, null, 2)], {
    type: "application/json;charset=utf-8",
  });
  const objectUrl = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = objectUrl;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  link.remove();
  URL.revokeObjectURL(objectUrl);
}

function collectParsingPresetFields(form: HTMLFormElement) {
  const fields: Record<string, string | boolean> = {};
  Array.from(form.elements).forEach((element) => {
    if (
      !(
        element instanceof HTMLInputElement ||
        element instanceof HTMLTextAreaElement ||
        element instanceof HTMLSelectElement
      )
    ) {
      return;
    }
    if (!element.name || ["button", "submit", "file"].includes(element.type)) {
      return;
    }
    if (element instanceof HTMLInputElement && element.type === "checkbox") {
      fields[element.name] = element.checked;
      return;
    }
    fields[element.name] = element.value;
  });
  return fields;
}

function applyParsingPresetFields(
  form: HTMLFormElement,
  fields: Record<string, string | boolean>,
) {
  Array.from(form.elements).forEach((element) => {
    if (
      !(
        element instanceof HTMLInputElement ||
        element instanceof HTMLTextAreaElement ||
        element instanceof HTMLSelectElement
      )
    ) {
      return;
    }
    if (!element.name || ["button", "submit", "file"].includes(element.type)) {
      return;
    }
    const value = fields[element.name];
    if (element instanceof HTMLInputElement && element.type === "checkbox") {
      element.checked = value === true || value === "true";
    } else if (value !== undefined) {
      element.value = String(value);
    }
    element.dispatchEvent(new Event("input", { bubbles: true }));
    element.dispatchEvent(new Event("change", { bubbles: true }));
  });
}

function normalizeParsingPreset(value: unknown): ParsingPreset | null {
  if (!value || typeof value !== "object") return null;
  const raw = value as Record<string, unknown>;
  const mode = String(raw.mode || "");
  if (!parsingOptions.some((option) => option.value === mode)) return null;
  const ui = raw.ui && typeof raw.ui === "object" ? (raw.ui as Record<string, unknown>) : {};
  const rawFields =
    raw.fields && typeof raw.fields === "object"
      ? (raw.fields as Record<string, unknown>)
      : {};
  const fields: Record<string, string | boolean> = {};
  Object.entries(rawFields).forEach(([key, fieldValue]) => {
    if (!key) return;
    if (typeof fieldValue === "boolean") {
      fields[key] = fieldValue;
      return;
    }
    if (typeof fieldValue === "string" || typeof fieldValue === "number") {
      fields[key] = String(fieldValue);
    }
  });
  const groupSuffixMode = String(ui.group_suffix_mode || "manual");
  return {
    schema: "demo-platform.parsing-preset.v1",
    saved_at: String(raw.saved_at || new Date().toISOString()),
    mode: mode as ParsingMode,
    ui: {
      group_suffix_mode:
        groupSuffixMode === "auto" || groupSuffixMode === "manual"
          ? groupSuffixMode
          : "manual",
      group_suffix_language: String(ui.group_suffix_language || "ru"),
      group_auto_suffix_count: clampNumber(
        String(ui.group_auto_suffix_count || 6),
        1,
        12,
        6,
      ),
    },
    fields,
  };
}

function safeFileSlug(value: string) {
  return (
    value
      .toLowerCase()
      .replace(/[^a-z0-9а-яё]+/gi, "-")
      .replace(/^-+|-+$/g, "")
      .slice(0, 80) || "campaign"
  );
}

function campaignBehaviorProtectionMode(value: unknown) {
  const mode = stringFromUnknown(value, "balanced");
  return ["conservative", "balanced", "fast"].includes(mode) ? mode : "balanced";
}

function campaignBehaviorProtectionPolicy(form: FormData): Record<string, unknown> {
  return {
    behavior_protection_enabled: form.get("behavior_protection_enabled") !== null,
    behavior_protection_mode: campaignBehaviorProtectionMode(
      form.get("behavior_protection_mode"),
    ),
  };
}

function accountName(account: TelegramAccount) {
  return accountDisplayLabel(account);
}

function accountProfileName(account: TelegramAccount) {
  const profileName = [account.first_name, account.last_name]
    .filter(Boolean)
    .join(" ")
    .trim();
  return profileName || null;
}

function accountDisplayLabel(account: TelegramAccount) {
  const displayName = (account.display_name || "").trim();
  if (displayName) return displayName;
  const username = (account.username || "").replace(/^@/, "").trim();
  if (username) return `@${username}`;
  return account.id ? `ID ${account.id.slice(0, 8)}` : "Аккаунт";
}

function AccountIdentity({
  account,
  showMetaChips = true,
}: {
  account: TelegramAccount;
  showMetaChips?: boolean;
}) {
  const displayLabel = accountDisplayLabel(account);
  const profileName = accountProfileName(account);
  const name = profileName || displayLabel;
  const phone = (account.phone || "").trim();
  const displayDuplicatesName =
    profileName && normalizeAccountLabel(displayLabel) === normalizeAccountLabel(profileName);
  const displayIsPhone = phone && normalizePhoneLabel(displayLabel) === normalizePhoneLabel(phone);
  const sublabel =
    profileName && !displayDuplicatesName && !displayIsPhone
      ? displayLabel
      : phone || accountHandle(account);
  const metaLine = accountOriginSystemLine(account);
  return (
    <div className="flex min-w-0 items-center gap-2.5">
      <div className="flex size-9 shrink-0 items-center justify-center overflow-hidden rounded-full bg-muted text-sm font-semibold text-muted-foreground">
        {account.profile_photo_data_url ? (
          <img
            src={account.profile_photo_data_url}
            alt=""
            className="size-full object-cover"
          />
        ) : (
          initials(name)
        )}
      </div>
      <div className="min-w-0">
        <div className="truncate font-medium" title={name}>
          {name}
        </div>
        <div
          className="truncate text-[13px] leading-tight text-muted-foreground"
          title={sublabel}
        >
          {sublabel}
        </div>
        {showMetaChips && metaLine ? (
          <div className="truncate text-xs leading-tight text-muted-foreground" title={metaLine}>
            {metaLine}
          </div>
        ) : null}
      </div>
    </div>
  );
}

function accountOriginLabel(origin: TelegramAccount["origin"] | undefined) {
  if (!origin) return "Не указано";
  const labels: Record<string, string> = {
    manual_phone_registered: "Ручной",
    sms_service_manual: "SMS ручной",
    market_session: "Маркет",
    tdata: "TData",
  };
  return labels[origin] || origin;
}

function accountAgeLine(account: TelegramAccount) {
  const realAge = account.real_age_days;
  if (typeof realAge === "number") return `реал ${realAge}д`;
  const claimedAge = account.claimed_age_days;
  if (typeof claimedAge === "number") return `заявл ${claimedAge}д`;
  if (typeof account.system_age_days === "number") return `в системе ${account.system_age_days}д`;
  return null;
}

function accountOriginSystemLine(account: TelegramAccount) {
  const origin = account.origin ? accountOriginLabel(account.origin) : "Источник не указан";
  const systemAge =
    typeof account.system_age_days === "number"
      ? `в системе ${account.system_age_days}д`
      : null;
  return [origin, systemAge].filter(Boolean).join(" · ");
}

function normalizeAccountLabel(value: string | null | undefined) {
  return (value || "").replace(/^@/, "").trim().toLowerCase();
}

function normalizePhoneLabel(value: string | null | undefined) {
  return (value || "").replace(/[^\d+]/g, "");
}

function AccountMiniAvatar({ account }: { account: TelegramAccount }) {
  const label = accountDisplayLabel(account);
  return (
    <span className="flex size-8 shrink-0 items-center justify-center overflow-hidden rounded-full bg-muted text-xs font-semibold text-muted-foreground">
      {account.profile_photo_data_url ? (
        <img
          src={account.profile_photo_data_url}
          alt=""
          className="size-full object-cover"
        />
      ) : (
        initials(label)
      )}
    </span>
  );
}

function AccountIdentityFallback({
  label,
  sublabel,
}: {
  label: string;
  sublabel?: string | null;
}) {
  const name = label || "Аккаунт";
  return (
    <div className="flex min-w-0 items-center gap-3">
      <div className="flex size-10 shrink-0 items-center justify-center rounded-full bg-muted text-sm font-semibold text-muted-foreground">
        {initials(name)}
      </div>
      <div className="min-w-0">
        <div className="truncate font-medium" title={name}>
          {name}
        </div>
        {sublabel ? (
          <div
            className="truncate text-sm text-muted-foreground"
            title={sublabel}
          >
            {sublabel}
          </div>
        ) : null}
      </div>
    </div>
  );
}

function proxySelectLabel(proxy: Proxy) {
  const geo = proxy.country ? ` · ${proxy.country}` : " · гео —";
  const usage = ` · ${proxyAccountUsageText(proxy)}`;
  const provider = proxy.provider ? ` · ${proxy.provider}` : "";
  return `${proxy.type}://${proxy.host}:${proxy.port}${geo}${usage}${provider}`;
}

function proxyAddressLabel(proxy: Proxy) {
  return `${proxy.type}://${proxy.host}:${proxy.port}`;
}

function proxyAccountUsageText(proxy: Proxy) {
  const accountCount = proxy.account_count ?? 0;
  const limit = proxy.max_accounts || 0;
  return limit > 0
    ? `подключено ${accountCount}/${limit} акк.`
    : `подключено ${accountCount} акк.`;
}

function proxyIsOverloaded(proxy: Proxy, usage?: ProxyUsage | null) {
  const accountCount = usage?.account_count ?? proxy.account_count ?? 0;
  return proxy.max_accounts > 0 && accountCount > proxy.max_accounts;
}

function proxyPingText(proxy: Proxy) {
  const telegramLatency = proxy.latest_telegram_latency_ms;
  const tcpLatency = proxy.latest_latency_ms;
  if (typeof telegramLatency === "number") {
    const isSlow = telegramLatency >= 1500;
    return (
      <div className="grid gap-0.5">
        <span className={isSlow ? "font-medium text-amber-700" : ""}>
          Telegram {telegramLatency} ms
        </span>
        {typeof tcpLatency === "number" ? (
          <span className="text-xs text-muted-foreground">
            TCP {tcpLatency} ms
          </span>
        ) : null}
      </div>
    );
  }
  return typeof tcpLatency === "number" ? (
    <span className="text-muted-foreground">TCP {tcpLatency} ms</span>
  ) : (
    <span className="text-muted-foreground">—</span>
  );
}

function proxyClassLabel(value?: string | null) {
  const labels: Record<string, string> = {
    datacenter: "Датацентр",
    static_residential: "Статический residential",
    isp: "ISP",
    mobile: "Мобильный",
    rotating_residential: "Ротационный residential",
    unknown: "Класс не указан",
  };
  return labels[value || "unknown"] || value || "Класс не указан";
}

function proxyExclusivityLabel(value?: string | null) {
  const labels: Record<string, string> = {
    dedicated: "Выделенный",
    private_1_2: "Приватный 1-2",
    shared: "Общий",
    unknown: "Эксклюзивность не указана",
  };
  return labels[value || "unknown"] || value || "Эксклюзивность не указана";
}

function ProxyConnectivityBadge({ status }: { status?: string | null }) {
  if (status === "ok") {
    return (
      <Badge variant="outline" className="border-emerald-200 bg-emerald-50 text-emerald-700">
        Telegram ok
      </Badge>
    );
  }
  if (status === "failed") {
    return (
      <Badge variant="outline" className="border-red-200 bg-red-50 text-red-700">
        Telegram ошибка
      </Badge>
    );
  }
  return <Badge variant="outline">Telegram не проверен</Badge>;
}

function GeoLabel({ country }: { country?: string | null }) {
  const code = String(country || "")
    .trim()
    .toUpperCase();
  if (!code) return <span className="text-muted-foreground">—</span>;
  return (
    <span className="inline-flex items-center gap-2 font-medium">
      <span aria-hidden="true">{countryFlag(code)}</span>
      <span>{code}</span>
    </span>
  );
}

function countryFlag(countryCode: string) {
  if (!/^[A-Z]{2}$/.test(countryCode)) return "🏳️";
  return Array.from(countryCode)
    .map((char) => String.fromCodePoint(127397 + char.charCodeAt(0)))
    .join("");
}

function ProxyTooltipLabel({ proxy }: { proxy: Proxy | null }) {
  if (!proxy) {
    return (
      <Tooltip>
        <TooltipTrigger asChild>
          <span
            className="block cursor-help truncate text-sm text-muted-foreground"
            tabIndex={0}
          >
            Не назначен
          </span>
        </TooltipTrigger>
        <TooltipContent className="max-w-80 whitespace-pre-wrap text-left">
          Прокси не назначен. Для рабочих Telegram-аккаунтов это риск: назначьте
          прокси в редакторе аккаунта. Исключение — личный аккаунт, если вы
          специально используете его без прокси.
        </TooltipContent>
      </Tooltip>
    );
  }

  const fullLabel = proxySelectLabel(proxy);
  const addressLabel = proxyAddressLabel(proxy);
  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <span
          className="block max-w-full truncate text-sm text-muted-foreground"
          tabIndex={0}
          title={fullLabel}
        >
          {addressLabel}
        </span>
      </TooltipTrigger>
      <TooltipContent className="max-w-[520px] break-all text-left">
        <p>{fullLabel}</p>
      </TooltipContent>
    </Tooltip>
  );
}

function AccountStatusCell({
  account,
  aiProfileStatus,
}: {
  account: TelegramAccount;
  aiProfileStatus: AccountAiProfileStatus | null;
}) {
  const metaLines = accountStatusMetaLines(account);
  const title = accountStatusTitle(account);
  const statusTitle = aiProfileStatus?.message || title;
  const trustLines = accountTrustTooltipLines(account);

  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <div
          className="mx-auto inline-flex min-w-0 cursor-help items-center justify-center text-center"
          tabIndex={0}
        >
          <AccountStatusBadge
            account={account}
            aiProfileStatus={aiProfileStatus}
          />
        </div>
      </TooltipTrigger>
      <TooltipContent className="max-w-96 whitespace-pre-wrap text-left">
        {statusTitle}
        {"\n\n"}
        {accountStatusActionHint(account)}
        {metaLines.length ? (
          <>
            {"\n\n"}
            {metaLines.join("\n")}
          </>
        ) : null}
        {trustLines.length ? (
          <>
            {"\n\n"}
            {trustLines.join("\n")}
          </>
        ) : null}
      </TooltipContent>
    </Tooltip>
  );
}

function AccountStatusBadge({
  account,
  aiProfileStatus,
}: {
  account: TelegramAccount;
  aiProfileStatus: AccountAiProfileStatus | null;
}) {
  if (aiProfileStatus?.state === "updating") {
    return (
      <Badge
        variant="outline"
        className="border-blue-200 bg-blue-50 text-blue-700"
      >
        <Loader2Icon className="size-3 animate-spin" />
        AI обновляет
      </Badge>
    );
  }
  if (aiProfileStatus?.state === "done") {
    return (
      <Badge
        variant="outline"
        className="border-emerald-200 bg-emerald-50 text-emerald-700"
      >
        <CheckCircle2Icon className="size-3" />
        Обновлен
      </Badge>
    );
  }
  if (aiProfileStatus?.state === "error") {
    return (
      <Badge
        variant="outline"
        className="border-red-200 bg-red-50 text-red-700"
      >
        <XCircleIcon className="size-3" />
        Ошибка AI
      </Badge>
    );
  }
  const tone = accountStatusTone(account);
  return (
    <Badge
      variant="outline"
      className={cn(
        tone === "danger" && "border-red-200 bg-red-50 text-red-700",
        tone === "warn" && "border-amber-200 bg-amber-50 text-amber-700",
        tone === "ok" && "border-emerald-200 bg-emerald-50 text-emerald-700",
      )}
    >
      {accountStatusBadgeLabel(account)}
    </Badge>
  );
}

function accountAiProfileStatusFromEvent(
  event: AccountHealthEvent | undefined,
  options: { useEventTime?: boolean } = {},
): AccountAiProfileStatus | null {
  if (!event) return null;
  const requestId = String(event.raw_error?.bulk_request_id || "");
  if (!requestId) return null;
  const eventTime = Date.parse(event.created_at);
  const updatedAt =
    options.useEventTime && Number.isFinite(eventTime) ? eventTime : Date.now();

  if (
    event.event_type === "bulk_ai_profile_completed" &&
    (!options.useEventTime ||
      Date.now() - updatedAt <= AI_PROFILE_STATUS_DONE_VISIBLE_MS)
  ) {
    return {
      state: "done",
      requestId,
      message: "AI профиль обновлен",
      updatedAt,
    };
  }
  if (
    event.event_type === "bulk_ai_profile_failed" ||
    event.event_type === "bulk_ai_profiles_failed"
  ) {
    if (Date.now() - updatedAt > AI_PROFILE_STATUS_ERROR_VISIBLE_MS) {
      return null;
    }
    return {
      state: "error",
      requestId,
      message:
        String(event.raw_error?.error || "") ||
        event.message ||
        "AI профиль не обновился",
      updatedAt,
    };
  }
  if (event.event_type === "bulk_ai_profiles_requested") {
    if (Date.now() - updatedAt > AI_PROFILE_QUEUE_STALE_MS) {
      return null;
    }
    return {
      state: "updating",
      requestId,
      message: event.message || "AI профиль в очереди",
      updatedAt,
    };
  }
  if (event.event_type === "bulk_ai_profile_processing") {
    if (Date.now() - updatedAt > AI_PROFILE_STATUS_STALE_MS) {
      return null;
    }
    return {
      state: "updating",
      requestId,
      message: event.message || "AI профиль обновляется",
      updatedAt,
    };
  }
  return null;
}

function accountHandle(account: TelegramAccount) {
  if (account.username) return `@${account.username.replace(/^@/, "")}`;
  return account.id ? `ID ${account.id.slice(0, 8)}` : "ID не указан";
}

function accountWarmupLabel(account: TelegramAccount) {
  if (account.incubator_mode || account.status === "incubator") {
    return "Инкубатор";
  }
  if (["completed", "succeeded", "ready"].includes(account.warmup_status)) {
    return account.warmup_score >= 80 ? "Прогрет" : "Прогрев пройден";
  }
  if (account.warmup_score >= 80) return "Прогрет";
  if (account.warmup_status === "validated") {
    return "Проверен";
  }
  if (["warming", "running", "scheduled"].includes(account.warmup_status)) {
    return "Прогревается";
  }
  return "Без прогрева";
}

function isAccountWarmupActive(account: TelegramAccount) {
  return ["warming", "running", "scheduled", "incubator"].includes(account.warmup_status) || account.incubator_mode;
}

function hasAccountOperationalError(account: TelegramAccount) {
  return ["failed", "error", "invalid"].includes(account.status);
}

function accountRestrictionLabel(account: TelegramAccount) {
  const until = formatRestrictionUntilMoscow(account.restriction_until_text);
  const untilTitle = until
    ? `${until.date}, ${until.time}`
    : account.restriction_until_text;
  if (
    account.status === "blocked" ||
    account.restriction_status === "blocked"
  ) {
    return untilTitle
      ? "Блокировка Telegram: до " + untilTitle
      : "Блокировка Telegram, срок не указан";
  }
  if (account.status === "frozen") {
    return untilTitle
      ? "Заморозка Telegram: до " + untilTitle
      : "Заморозка Telegram, срок не указан";
  }
  if (
    account.status === "spam_blocked" ||
    account.restriction_status === "limited"
  ) {
    return untilTitle
      ? "Спам-блок: до " + untilTitle
      : "Спам-блок, срок не указан";
  }
  if (account.restriction_status === "clear") return "Ограничений нет";
  if (account.restriction_status === "unknown")
    return account.restriction_label || "Статус ограничений неизвестен";
  return null;
}

function accountStatusTone(account: TelegramAccount) {
  if (
    account.status === "blocked" ||
    account.status === "spam_blocked" ||
    account.status === "frozen" ||
    account.restriction_status === "blocked" ||
    account.restriction_status === "limited"
  ) {
    return "danger";
  }
  if (
    account.status === "quarantined" ||
    account.status === "failed" ||
    account.status === "error" ||
    account.restriction_status === "unknown"
  ) {
    return "warn";
  }
  if (isAccountWarmupActive(account)) {
    return "neutral";
  }
  if (account.status === "active" && account.restriction_status !== "unknown") {
    return "ok";
  }
  return "neutral";
}

function accountStatusBadgeLabel(account: TelegramAccount) {
  if (account.restriction_status === "blocked" || account.status === "blocked") {
    return "Блок";
  }
  if (account.restriction_status === "limited" || account.status === "spam_blocked") {
    return "Ограничен";
  }
  if (hasAccountOperationalError(account)) {
    return statusLabel(account.status);
  }
  if (account.warmup_status === "validated") {
    return "Проверен";
  }
  if (account.incubator_mode || account.status === "incubator") {
    return "Инкубатор";
  }
  if (isAccountWarmupActive(account)) {
    return "Прогревается";
  }
  return statusLabel(account.status);
}

function accountStatusMetaLines(account: TelegramAccount) {
  const until = formatRestrictionUntilMoscow(account.restriction_until_text);
  const quality = accountQualitySummary(account);
  const mediumRiskReason = accountMediumRiskReason(account);
  const riskLine = mediumRiskReason ? `Риск: ${mediumRiskReason}` : null;
  const withRisk = (lines: string[]) => (riskLine ? [...lines, riskLine] : lines);
  if (
    account.status === "blocked" ||
    account.restriction_status === "blocked"
  ) {
    const lines = until
      ? ["Блокировка до", until.date, until.time]
      : ["Блокировка", "срок не указан"];
    return quality ? [...lines, quality] : lines;
  }
  if (account.status === "frozen") {
    return until
      ? ["Заморозка до", until.date, until.time]
      : ["Заморозка", "срок не указан"];
  }
  if (account.status === "quarantined") {
    return ["действия остановлены"];
  }
  if (account.incubator_mode || account.status === "incubator") {
    return ["кампании запрещены", accountAgeLine(account) || "возраст не указан"];
  }
  if (
    account.status === "spam_blocked" ||
    account.restriction_status === "limited"
  ) {
    const lines = until
      ? ["Спам-блок до", until.date, until.time]
      : ["Спам-блок", "срок не указан"];
    return quality ? [...lines, quality] : lines;
  }
  if (account.restriction_status === "clear") return withRisk(["Ограничений нет"]);
  if (account.restriction_status === "unknown")
    return withRisk([account.restriction_label || "Статус неизвестен"]);
  if (hasAccountOperationalError(account)) {
    return withRisk(["ошибка проверки"]);
  }
  return withRisk([accountWarmupLabel(account)]);
}

function accountQualitySummary(account: TelegramAccount) {
  const quality = account.quality_score || {};
  const rating = quality.rating;
  const potential = quality.potential_30d;
  const ratingText = typeof rating === "number" ? `рейтинг ${rating}/10` : null;
  const potentialText = typeof potential === "number" ? `потенциал ${potential}/10` : null;
  if (!ratingText && !potentialText) return null;
  if (account.restriction_status === "limited" || account.restriction_status === "blocked") {
    return `${[ratingText, potentialText].filter(Boolean).join(" · ")} ≠ разрешение`;
  }
  return [ratingText, potentialText].filter(Boolean).join(" · ");
}

function accountSafetyLabel(status: string) {
  const labels: Record<string, string> = {
    clear: "Clear",
    limited: "Limited",
    blocked: "Blocked",
    unknown: "Unknown",
    technical_only: "Tech only",
    quarantined: "Quarantine",
    invalid: "Invalid",
  };
  return labels[status] || status;
}

function accountTrustLabel(label: string) {
  const labels: Record<string, string> = {
    excellent: "отличный",
    good: "хороший",
    medium: "средний",
    risky: "риск",
    critical: "критический",
  };
  return labels[label] || label;
}

function accountTrustTooltipLines(account: TelegramAccount) {
  const trust = account.latest_trust;
  if (!trust) return [];
  const positive = (trust.positive_factors || [])
    .slice(0, 3)
    .map((factor) => `+ ${factor.label} (${factor.delta})`);
  const negative = (trust.risk_factors || [])
    .slice(0, 4)
    .map((factor) => `- ${factor.label} (${factor.delta})`);
  return [
    `Safety: ${accountSafetyLabel(trust.safety_status)}`,
    `Trust: ${trust.score_100}/100 ${accountTrustLabel(trust.label)}, confidence ${trust.confidence}`,
    `Следующий шаг: ${accountTrustNextActionLabel(trust.recommendations?.next_best_action)}`,
    ...positive,
    ...negative,
  ];
}

function accountTrustNextActionLabel(action?: string | null) {
  const labels: Record<string, string> = {
    runtime_review_before_launch: "проверка runtime-событий перед боевым запуском",
    pause_or_replace_account: "пауза, карантин или замена аккаунта",
    fix_proxy_or_session_before_launch: "исправить прокси или сессию",
    safe_warmup_before_outbound: "мягкий прогрев перед исходящими действиями",
    soft_launch_low_daily_limits: "мягкий запуск с низкими лимитами",
    allowed_with_account_limits: "можно запускать по лимитам аккаунта",
  };
  return labels[action || ""] || action || "разобрать аккаунт";
}

function accountStatusTitle(account: TelegramAccount) {
  const restriction = accountRestrictionLabel(account);
  if (restriction) return restriction;
  if (hasAccountOperationalError(account)) {
    return "Последняя проверка аккаунта не удалась. Чаще всего причина в прокси, Telegram-соединении или поврежденной сессии.";
  }
  if (account.incubator_mode || account.status === "incubator") {
    return "Аккаунт находится в инкубаторе: проверки и мягкий прогрев разрешены, кампании запрещены.";
  }
  if (isAccountWarmupActive(account)) {
    return "Аккаунт участвует в активном прогреве.";
  }
  if (account.status === "active") {
    return "Аккаунт считается активным после последней успешной проверки Telegram-сессии. Нажмите «Проверить», чтобы обновить статус.";
  }
  if (account.status === "new") {
    return "Аккаунт добавлен, но еще не проверен через Telegram.";
  }
  if (account.status === "frozen") {
    return "Telegram ограничил аккаунт. Не запускайте активные действия с ним, пока ограничение не снято.";
  }
  if (account.status === "quarantined") {
    return "Аккаунт в карантине: массовые действия и кампании должны его пропускать.";
  }
  if (account.status === "blocked") {
    return "Telegram ограничил аккаунт по фактическим событиям. Не запускайте активные действия, пока ограничение не снято.";
  }
  if (account.status === "spam_blocked") {
    return "Telegram ограничил исходящие сообщения аккаунта. Статус обновляется по фактическим ошибкам действий.";
  }
  return statusLabel(account.status);
}

function accountStatusActionHint(account: TelegramAccount) {
  if (
    account.status === "blocked" ||
    account.restriction_status === "blocked"
  ) {
    return "Что делать: не запускать аккаунт в кампаниях, проверить последние ошибки действий. Если блок не снят — оставить в карантине или архивировать.";
  }
  if (
    account.status === "spam_blocked" ||
    account.restriction_status === "limited"
  ) {
    return "Что делать: временно не использовать в AI-комментариях и рассылках. Статус вернется в работу только после чистых фактических действий.";
  }
  if (account.status === "quarantined") {
    return "Что делать: выяснить причину карантина в деталях аккаунта. Кампании и массовые действия должны пропускать этот аккаунт.";
  }
  if (account.restriction_status === "unknown") {
    if ((account.restriction_label || "").toLowerCase().includes("заблокирован")) {
      return "Что делать: оставить аккаунт вне кампаний и смотреть последние runtime-события.";
    }
    return "Что делать: нажать «Проверить», чтобы проверить Telegram-сессию; ограничения обновляются по фактическим действиям.";
  }
  if (account.incubator_mode || account.status === "incubator") {
    return "Что делать: держать аккаунт на чистом прокси, не запускать кампании, позже снять флаг инкубатора вручную.";
  }
  if (isAccountWarmupActive(account)) {
    return "Что делать: дождаться завершения прогрева. Для агрессивных действий и AI-комментариев лучше использовать аккаунты со здоровьем 80+.";
  }
  if (accountNeedsProxy(account)) {
    return "Что делать: назначить прокси в редакторе аккаунта. Без прокси рабочий аккаунт лучше не запускать.";
  }
  if (account.status === "active" && account.restriction_status === "clear") {
    return "Что делать: явных ограничений нет. Можно использовать аккуратно, соблюдая лимиты кампаний.";
  }
  return "Что делать: при сомнении нажмите «Проверить» и посмотрите детали аккаунта.";
}

function accountNameById(accounts: TelegramAccount[], accountId: string) {
  const account = accounts.find((item) => item.id === accountId);
  return account ? accountName(account) : accountId.slice(0, 8);
}

function sourceNameById(sources: Source[], sourceId: string) {
  const source = sources.find((item) => item.id === sourceId);
  return (
    source?.title || source?.username || source?.url || sourceId.slice(0, 8)
  );
}

function sourceRef(source: Source) {
  if (source.username) {
    return `@${source.username.replace(/^@/, "")}`;
  }
  return source.url || source.id;
}

function initials(value: string) {
  return (
    value
      .split(/\s+/)
      .filter(Boolean)
      .slice(0, 2)
      .map((part) => part[0]?.toUpperCase() || "")
      .join("")
      .slice(0, 2) || "WA"
  );
}

function accountWarmupPresetPayload(value: FormDataEntryValue | null): {
  warmup_status: string;
  warmup_score: number;
} {
  const preset = String(value || "not_started");
  if (preset === "trusted") {
    return { warmup_status: "completed", warmup_score: 100 };
  }
  if (preset === "validated") {
    return { warmup_status: "validated", warmup_score: 60 };
  }
  if (preset === "warming") {
    return { warmup_status: "running", warmup_score: 1 };
  }
  return { warmup_status: "not_started", warmup_score: 0 };
}

function inviteTrackingFromForm(
  form: FormData,
): CampaignInviteTrackingConfig | null {
  const inviteLink = cleanOptionalText(form.get("invite_tracking_link"));
  const sourceRef = cleanOptionalText(form.get("invite_tracking_source_ref"));
  if (!inviteLink && !sourceRef) return null;
  if (!inviteLink || !sourceRef) {
    throw new Error(
      "Для трекинга invite-ссылки заполните и ссылку, и канал/группу этой ссылки.",
    );
  }
  return {
    invite_link: inviteLink,
    source_ref: sourceRef,
    account_id: cleanOptionalText(form.get("invite_tracking_account_id")),
  };
}

function sourceInvalidLabel(source: Source) {
  const reason = stringFromUnknown(source.source_metadata?.invalid_reason, "");
  const labels: Record<string, string> = {
    account_banned_in_source: "Аккаунт забанен",
    account_cannot_write_comments: "Запрет записи",
    discussion_join_approval_required: "Нужна заявка",
    source_comments_not_available: "Комментарии закрыты",
    source_not_accessible: "Приватный",
    source_not_channel: "Не канал",
    source_not_found: "Не найден",
  };
  return labels[reason] || statusLabel(source.access_status);
}

function campaignPostSelectionLabel(config: Record<string, unknown>) {
  const labels: Record<CampaignPostSelectionMode, string> = {
    new_posts: "Новые посты",
    historical_posts: "Старые посты",
    latest_post: "Только последний пост",
  };
  return labels[campaignPostSelectionMode(config)];
}

function campaignDeliveryLabel(config: Record<string, unknown>) {
  const labels: Record<CampaignDeliveryMode, string> = {
    draft_only: "Черновики",
    generate_and_send: "Сразу отправлять",
  };
  return labels[campaignDeliveryMode(config)];
}

function campaignEventDescription(event: CampaignEvent) {
  const payload = objectRecord(event.payload);
  const errorCode = stringFromUnknown(payload.error_code);
  const errorMessage = stringFromUnknown(payload.error_message);
  const reason = stringFromUnknown(payload.reason);
  const score =
    payload.score === undefined ? null : stringFromUnknown(payload.score);
  const minQuality =
    payload.min_quality_score === undefined
      ? null
      : stringFromUnknown(payload.min_quality_score);
  const peer = stringFromUnknown(payload.peer_ref);
  const accountName = stringFromUnknown(payload.account_name);
  const sourceTitle = stringFromUnknown(payload.source_title);
  const sourceRef = stringFromUnknown(payload.source_ref);
  const messageId = stringFromUnknown(payload.incoming_message_id);
  const matchedKeyword = stringFromUnknown(payload.matched_keyword);
  const parts: string[] = [];
  const message = campaignEventMessage(event.message);
  if (message) parts.push(message);
  if (accountName) parts.push(accountName);
  if (sourceTitle || sourceRef) parts.push(sourceTitle || sourceRef);
  if (errorCode || errorMessage) {
    parts.push(`ошибка: ${campaignErrorText(errorMessage, errorCode)}`);
  }
  if (peer) parts.push(`Диалог: ${peer}`);
  if (messageId) parts.push(`сообщение ${messageId}`);
  if (reason) parts.push(`причина: ${campaignSkipReasonLabel(reason)}`);
  if (matchedKeyword) parts.push(`ключ: ${matchedKeyword}`);
  if (score)
    parts.push(
      minQuality ? `качество: ${score} из ${minQuality}` : `качество: ${score}`,
    );
  return parts.join(" · ");
}

function campaignActionLogTitle(
  action: CampaignActionDetail,
  sources: Source[],
) {
  if (action.action_type === "parse_source") {
    return `Источник: ${sourceNameById(sources, action.target_id)}`;
  }
  if (action.action_type === "comment_posts") {
    return `Комментарии: ${sourceNameById(sources, action.target_id)}`;
  }
  if (action.action_type === "generate_and_send_comment") {
    return "Отправка комментария";
  }
  if (action.action_type === "generate_comment") {
    return "Генерация комментария";
  }
  if (action.action_type === "message_broadcast") {
    const result = objectRecord(action.result);
    return `Рассылка: ${stringFromUnknown(result.chat_title, stringFromUnknown(result.peer_ref, "диалог"))}`;
  }
  if (action.action_type === "neuro_chat_reply") {
    const result = objectRecord(action.result);
    return `AI-чат: ${stringFromUnknown(result.chat_title, stringFromUnknown(result.peer_ref, "диалог"))}`;
  }
  if (action.action_type === "neuro_dialog_reply") {
    const result = objectRecord(action.result);
    return `AI-диалог: ${stringFromUnknown(result.chat_title, stringFromUnknown(result.peer_ref, "диалог"))}`;
  }
  if (action.action_type === "set_reaction") {
    return "Реакция";
  }
  return action.action_type;
}

function campaignTerminalRows(
  events: CampaignEvent[],
  actions: CampaignActionDetail[],
  accounts: TelegramAccount[],
  sources: Source[],
  level: string,
): CampaignTerminalRow[] {
  return [
    ...events.map((event) => campaignTerminalEventRow(event)),
    ...actions.map((action) => campaignTerminalActionRow(action, accounts, sources)),
  ]
    .filter((row) => level === "all" || row.level === level)
    .sort(
      (left, right) =>
        new Date(left.at).getTime() - new Date(right.at).getTime(),
    );
}

function campaignTerminalEventRow(event: CampaignEvent): CampaignTerminalRow {
  const payload = objectRecord(event.payload);
  const accountName = stringFromUnknown(payload.account_name);
  const sourceTitle = stringFromUnknown(payload.source_title);
  const sourceRef = stringFromUnknown(payload.source_ref);
  const sourceName = sourceTitle || sourceRef || null;
  const errorCode = stringFromUnknown(payload.error_code);
  const errorMessage = stringFromUnknown(payload.error_message);
  const eventText = campaignTerminalEventText(event, payload);
  return {
    id: `event-${event.id}`,
    level: event.level,
    at: event.created_at,
    accountName: accountName || null,
    sourceName,
    text:
      errorCode || errorMessage
        ? `${eventText}: ${campaignErrorText(errorMessage, errorCode)}`
        : eventText,
    code: event.event_type,
  };
}

function campaignTerminalActionRow(
  action: CampaignActionDetail,
  accounts: TelegramAccount[],
  sources: Source[],
): CampaignTerminalRow {
  const result = objectRecord(action.result);
  const level =
    action.status === "failed"
      ? "error"
      : action.status === "succeeded" || action.status === "sent"
        ? "success"
        : action.status === "skipped"
          ? "warning"
          : "info";
  return {
    id: `action-${action.id}`,
    level,
    at: action.executed_at || action.created_at,
    accountName: action.telegram_account_id
      ? accountNameById(accounts, action.telegram_account_id)
      : null,
    sourceName:
      action.action_type === "set_reaction"
        ? stringFromUnknown(
            result.source_title,
            stringFromUnknown(
              result.source_ref,
              stringFromUnknown(result.source_id)
                ? sourceNameById(sources, stringFromUnknown(result.source_id))
                : stringFromUnknown(result.reaction_peer_ref),
            ),
          )
        : action.target_type === "source"
          ? sourceNameById(sources, action.target_id)
          : stringFromUnknown(result.chat_title, stringFromUnknown(result.peer_ref)),
    text: campaignTerminalActionText(action, sources),
    code: action.action_type,
  };
}

function campaignTerminalEventText(
  event: CampaignEvent,
  payload: Record<string, unknown>,
) {
  const sourceTitle = stringFromUnknown(payload.source_title);
  const sourceRef = stringFromUnknown(payload.source_ref);
  const sourceName = sourceTitle || sourceRef || "источник";
  const reason = stringFromUnknown(payload.reason);
  const matchedKeyword = stringFromUnknown(payload.matched_keyword);
  const peer = stringFromUnknown(payload.peer_ref);
  const messageId = stringFromUnknown(payload.incoming_message_id);
  const count = stringFromUnknown(payload.count);
  const labels: Record<string, string> = {
    run_created: "Создан запуск кампании",
    run_pending: "Запуск поставлен в очередь",
    tick_started: "Началась фоновая проверка источников",
    runner_waiting: "Проверка завершена, runner ждет следующий тик",
    tick_completed: "Фоновая проверка завершена",
    run_completed: "Запуск кампании завершен",
    run_cancelled: "Запуск кампании остановлен",
    run_failed: "Запуск кампании упал",
    manual_stop_requested: "Запрошена ручная остановка",
    live_listener_active: "Live listener подключен и слушает источники",
    source_monitoring_started: `Начал читать источник «${sourceName}»`,
    source_posts_loaded: `Прочитал посты из «${sourceName}»`,
    source_posts_filtered: `Отфильтровал посты из «${sourceName}»`,
    source_discussion_joined: `Вступил в обсуждение «${sourceName}», можно продолжать комментарии`,
    source_fetch_failed: `Не удалось прочитать источник «${sourceName}»`,
    comment_generation_started: `Начал генерировать комментарий для «${sourceName}»`,
    comment_generated: `Сгенерировал комментарий для «${sourceName}»`,
    comment_send_started: `Начал отправку комментария в «${sourceName}»`,
    comment_sent: `Комментарий отправлен в «${sourceName}»`,
    comment_drafted: `Черновик комментария создан для «${sourceName}»`,
    comment_send_failed: `Комментарий не отправлен в «${sourceName}»`,
    live_neuro_message_skipped: `Пропущено входящее сообщение${peer ? ` в ${peer}` : ""}`,
    live_neuro_reply_created: `Создан ответ${peer ? ` в ${peer}` : ""}`,
    live_neuro_reply_failed: `Не удалось ответить${peer ? ` в ${peer}` : ""}`,
  };
  const base =
    labels[event.event_type] ||
    campaignEventDescription(event) ||
    campaignEventMessage(event.message) ||
    campaignEventLabel(event.event_type);
  const details = [
    messageId ? `сообщение ${messageId}` : null,
    reason ? `причина: ${campaignSkipReasonLabel(reason)}` : null,
    matchedKeyword ? `ключ: ${matchedKeyword}` : null,
    count ? `кол-во: ${count}` : null,
  ].filter(Boolean);
  return details.length ? `${base} · ${details.join(" · ")}` : base;
}

function campaignTerminalActionText(
  action: CampaignActionDetail,
  sources: Source[],
) {
  const result = objectRecord(action.result);
  const target =
    action.target_type === "source"
      ? sourceNameById(sources, action.target_id)
      : stringFromUnknown(result.chat_title, stringFromUnknown(result.peer_ref, "цель"));
  if (action.error_message) {
    return `${campaignActionLogTitle(action, sources)}: ${campaignErrorText(action.error_message, action.error_code)}`;
  }
  if (action.status === "skipped") {
    return `${campaignActionLogTitle(action, sources)} пропущено`;
  }
  if (action.action_type === "parse_source") {
    return action.status === "failed"
      ? `Не удалось получить посты из «${target}»`
      : `Получены/проверены посты из «${target}»`;
  }
  if (action.action_type === "comment_posts") {
    return action.status === "succeeded"
      ? `Комментарии по источнику «${target}» обработаны`
      : `Подготовка комментариев по «${target}»`;
  }
  if (action.action_type === "generate_comment") {
    return "Сгенерирован черновик комментария";
  }
  if (action.action_type === "generate_and_send_comment") {
    return "Комментарий сгенерирован и отправлен в Telegram";
  }
  if (action.action_type === "message_broadcast") {
    return `Сообщение отправлено в диалог «${target}»`;
  }
  if (action.action_type === "neuro_chat_reply") {
    return `AI-чат ответил в «${target}»`;
  }
  if (action.action_type === "neuro_dialog_reply") {
    return `AI-диалог ответил в «${target}»`;
  }
  if (action.action_type === "set_reaction") {
    const reaction = stringFromUnknown(result.reaction);
    const source = stringFromUnknown(
      result.source_title,
      stringFromUnknown(
        result.source_ref,
        stringFromUnknown(result.source_id)
          ? sourceNameById(sources, stringFromUnknown(result.source_id))
          : target,
      ),
    );
    const messageId = stringFromUnknown(
      result.tg_message_id,
      stringFromUnknown(result.message_id),
    );
    return `Поставлена реакция${reaction ? ` ${reaction}` : ""}${messageId ? ` на пост ${messageId}` : ""} в «${source}»`;
  }
  return campaignActionLogTitle(action, sources);
}

function campaignTerminalLevelClass(level: string) {
  if (level === "error") return "text-red-600";
  if (level === "warning") return "text-amber-700";
  if (level === "success") return "text-emerald-700";
  if (level === "debug") return "text-muted-foreground";
  return "text-sky-700";
}

function eventLevelLabel(value: string) {
  const labels: Record<string, string> = {
    debug: "debug",
    error: "ошибка",
    info: "инфо",
    success: "успех",
    warning: "внимание",
  };
  return labels[value] || value;
}

function accountEventTypeLabel(eventType: string) {
  const labels: Record<string, string> = {
    account_channel_discovery_completed: "каналы найдены",
    account_channel_discovery_failed: "каналы ошибка",
    account_profile_update_completed: "профиль обновлен",
    account_profile_update_failed: "профиль ошибка",
    account_quarantined: "карантин",
    bulk_ai_profile_completed: "AI профиль",
    bulk_ai_profile_failed: "AI профиль ошибка",
    bulk_ai_profile_processing: "AI профиль в работе",
    bulk_ai_profiles_failed: "AI профили ошибка",
    bulk_ai_profiles_requested: "AI профили очередь",
    bulk_clone_profile_completed: "профиль скопирован",
    bulk_clone_profile_failed: "копирование ошибка",
    bulk_copy_stories_failed: "сторис ошибка",
    bulk_join_chat_attempt: "join попытка",
    bulk_join_chat_completed: "join успех",
    bulk_join_chat_failed: "join ошибка",
    bulk_join_chats_completed: "join завершен",
    bulk_join_chats_delay: "join пауза",
    bulk_join_chats_requested: "join очередь",
    bulk_join_chats_skipped: "join пропуск",
    bulk_join_chats_started: "join старт",
  };
  return labels[eventType] || eventType.replaceAll("_", " ");
}

function contentFactoryCaptionLimit(accounts: TelegramAccount[], accountId: string, imagesEnabled: boolean) {
  if (!imagesEnabled) return 4096;
  const account = accounts.find((item) => item.id === accountId);
  return (account as (TelegramAccount & { is_premium?: boolean }) | undefined)?.is_premium ? 2000 : 1000;
}

function clampContentFactoryPostLength(value: number, captionLimit: number) {
  const fallback = Math.min(1200, captionLimit);
  if (!Number.isFinite(value)) return fallback;
  return Math.min(captionLimit, Math.max(200, Math.trunc(value)));
}


function errorMessage(error: unknown) {
  const message = error instanceof Error ? error.message : "Неизвестная ошибка";
  return friendlyErrorMessage(message);
}

function friendlyErrorMessage(message: string) {
  const text = message.toLowerCase();
  if (
    text.includes("signal is aborted") ||
    text.includes("aborterror") ||
    text.includes("the user aborted a request")
  ) {
    return "Сервер не ответил вовремя. Обновите страницу и повторите действие; если ошибка повторяется, проверьте доступность API.";
  }
  if (
    text.includes("session_invalid") ||
    text.includes("session string is invalid")
  ) {
    return "Сессия Telegram аккаунта повреждена. Переподключите аккаунт или выберите другой.";
  }
  if (
    text.includes("session_unauthorized") ||
    text.includes("not authorized") ||
    text.includes("expired")
  ) {
    return "Telegram сессия больше не авторизована. Нужно заново подключить аккаунт.";
  }
  if (
    text.includes("session_not_found") ||
    text.includes("session string was not found")
  ) {
    return "У аккаунта нет сохраненной Telegram-сессии. Импортируйте аккаунт заново.";
  }
  if (
    text.includes("chatadminrequired") ||
    text.includes("getparticipantsrequest") ||
    text.includes("admin privileges")
  ) {
    return "Telegram не дает получить полный список участников без прав администратора. Собираем доступную активную аудиторию через комментарии и сообщения.";
  }
  if (
    text.includes("frozenmethodinvalid") ||
    text.includes("frozen account") ||
    text.includes("frozen accounts") ||
    text.includes("заморозил аккаунт")
  ) {
    return "Telegram заморозил аккаунт и временно запретил это действие. Проверьте аккаунт в официальном Telegram и пока не запускайте с ним активные кампании.";
  }
  if (text.includes("flood") || text.includes("wait of")) {
    return "Telegram временно ограничил частые действия аккаунта. Нужно подождать и повторить позже.";
  }
  if (
    text.includes("channelprivate") ||
    text.includes("not a participant") ||
    text.includes("usernotparticipant")
  ) {
    return "У аккаунта нет доступа к этому источнику. Проверьте доступ или выберите другой аккаунт.";
  }
  if (
    text.includes("no user has") ||
    text.includes("could not find") ||
    text.includes("cannot find")
  ) {
    return "Источник не найден в Telegram. Проверьте username или ссылку.";
  }
  if (text.includes("failed to fetch")) {
    return "Сервер недоступен или сеть не ответила. Обновите страницу и повторите действие.";
  }
  return message;
}

function recoverLockedList<T>(error: unknown): T[] {
  if (
    error instanceof ApiError &&
    (error.status === 402 || error.status === 403)
  ) {
    return [];
  }
  throw error;
}

async function loadDashboardSecondaryData({
  token,
  workspaceId,
  proxies,
  warmupPlans,
}: {
  token: string;
  workspaceId: string;
  proxies: Proxy[];
  warmupPlans: WarmupPlan[];
}): Promise<DashboardSecondaryData> {
  const [proxyUsageEntries, warmupRunEntries] = await Promise.all([
    Promise.all(
      proxies.map(async (proxy) => {
        try {
          const usage = await apiRequest<ProxyUsage>(
            `/proxies/${proxy.id}/usage`,
            { token, workspaceId },
          );
          return { proxyId: proxy.id, usage };
        } catch {
          return { proxyId: proxy.id, usage: null };
        }
      }),
    ),
    Promise.all(
      warmupPlans.map(async (plan) => {
        try {
          const [runs, steps] = await Promise.all([
            apiRequest<WarmupRun[]>(`/warmup/plans/${plan.id}/runs`, {
              token,
              workspaceId,
            }),
            apiRequest<WarmupStep[]>(`/warmup/plans/${plan.id}/steps`, {
              token,
              workspaceId,
            }),
          ]);
          return { planId: plan.id, runs, steps, error: null };
        } catch (error) {
          return {
            planId: plan.id,
            runs: [],
            steps: [],
            error: errorMessage(error),
          };
        }
      }),
    ),
  ]);

  const proxyUsage = proxyUsageEntries.reduce<Record<string, ProxyUsage>>(
    (acc, entry) => {
      if (entry.usage) {
        acc[entry.proxyId] = entry.usage;
      }
      return acc;
    },
    {},
  );
  const warmupRuns = warmupRunEntries.reduce<Record<string, WarmupRun[]>>(
    (acc, entry) => {
      acc[entry.planId] = entry.runs;
      return acc;
    },
    {},
  );
  const warmupSteps = warmupRunEntries.reduce<Record<string, WarmupStep[]>>(
    (acc, entry) => {
      acc[entry.planId] = entry.steps;
      return acc;
    },
    {},
  );
  const warmupRunErrors = warmupRunEntries.reduce<Record<string, string>>(
    (acc, entry) => {
      if (entry.error) {
        acc[entry.planId] = entry.error;
      }
      return acc;
    },
    {},
  );

  return { proxyUsage, warmupRuns, warmupSteps, warmupRunErrors };
}

function pickRecord<T>(record: Record<string, T>, keys: string[]) {
  const allowed = new Set(keys);
  return Object.fromEntries(
    Object.entries(record).filter(([key]) => allowed.has(key)),
  ) as Record<string, T>;
}

function omitKey<T>(record: Record<string, T>, key: string) {
  const next = { ...record };
  delete next[key];
  return next;
}

export default DashboardApp;
